export type TokenType = 'num' | 'word';

export interface Token {
  type: TokenType;
  text: string;
  /** Lower-cased, NFC-normalised text, used for keyword and name lookups. */
  norm: string;
  value: number;
  line: number;
  column: number;
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let column = 1;
  while (i < source.length) {
    const ch = source[i];
    if (ch === '\n') {
      i++;
      line++;
      column = 1;
      continue;
    }
    if (/\s/.test(ch)) {
      i++;
      column++;
      continue;
    }
    const start = i;
    if (/[0-9]/.test(ch)) {
      while (i < source.length && /[0-9]/.test(source[i])) i++;
    } else {
      while (i < source.length && !/\s/.test(source[i])) i++;
    }
    const text = source.slice(start, i);
    tokens.push({
      type: /^[0-9]/.test(text) ? 'num' : 'word',
      text,
      norm: text.normalize('NFC').toLowerCase(),
      value: Number(text),
      line,
      column,
    });
    column += i - start;
  }
  return tokens;
}

