import { compile } from './parser';
import type { Mode, RunResult } from './types';

export type { Mode, RunResult, Segment, LogoError, Vec3 } from './types';

/** Interprets a whole program and returns the drawn segments and the first error. */
export function run(source: string, _mode: Mode): RunResult {
  const program = compile(source);
  const machine = createMachine();
  for (const _ of execute(machine, program));
  return { segments: machine.segments, error: null };
}

