import type { Vec3 } from './types';

/** Reduces an angle in degrees to [0, 360). */
function reduce(deg: number): number {
  const r = deg % 360;
  return r < 0 ? r + 360 : r;
}

/** Sine of an angle in degrees, exact at multiples of 90. */
export function sinDeg(deg: number): number {
  const r = reduce(deg);
  if (r === 0 || r === 180) return 0;
  if (r === 90) return 1;
  if (r === 270) return -1;
  return Math.sin((r * Math.PI) / 180);
}

/** Cosine of an angle in degrees, exact at multiples of 90. */
export function cosDeg(deg: number): number {
  return sinDeg(deg + 90);
}

/**
 * The turtle's orientation. While the turtle lies flat (up = +Z) it is kept as a
 * heading angle, measured clockwise from +Y, so flat drawings stay as exact as
 * possible and are identical in 2D and 3D.
 */
export class Orientation {
  private theta = 0;

  turn(deg: number): void {
    this.theta = reduce(this.theta + deg);
  }

  heading(): Vec3 {
    return [sinDeg(this.theta), cosDeg(this.theta), 0];
  }
}

