export type Keyword = 'forward' | 'back' | 'right' | 'left';

const ALIASES: Record<Keyword, string[]> = {
  forward: ['np', 'naprzod', 'naprzód', 'fd', 'forward'],
  back: ['ws', 'wstecz', 'bk', 'back'],
  right: ['pw', 'prawo', 'rt', 'right'],
  left: ['lw', 'lewo', 'lt', 'left'],
};

const LOOKUP = new Map<string, Keyword>();
for (const [keyword, words] of Object.entries(ALIASES) as [Keyword, string[]][]) {
  for (const word of words) LOOKUP.set(word.normalize('NFC'), keyword);
}

/** The keyword a normalised word stands for, if any. */
export function keywordOf(norm: string): Keyword | undefined {
  return LOOKUP.get(norm);
}

