import { keywordOf } from './keywords';
import { tokenize, type Token } from './lexer';

export type Expr = { kind: 'num'; value: number; token: Token };

export type Stmt =
  | { kind: 'move'; sign: 1 | -1; arg: Expr; token: Token }
  | { kind: 'turn'; sign: 1 | -1; arg: Expr; token: Token }
  | { kind: 'repeat'; count: Expr; body: Stmt[]; token: Token; close: Token };

export interface Program {
  body: Stmt[];
}

class Parser {
  private pos = 0;
  constructor(private readonly tokens: Token[]) {}

  private next(): Token {
    return this.tokens[this.pos++];
  }

  private peek(): Token | undefined {
    return this.tokens[this.pos];
  }

  parseList(): Stmt[] {
    const list: Stmt[] = [];
    while (this.peek() && this.peek()!.type !== ']') list.push(this.parseStatement());
    return list;
  }

  private parseExpr(): Expr {
    const token = this.next();
    return { kind: 'num', value: token.value, token };
  }

  private parseStatement(): Stmt {
    const token = this.next();
    switch (keywordOf(token.norm)) {
      case 'forward':
        return { kind: 'move', sign: 1, arg: this.parseExpr(), token };
      case 'back':
        return { kind: 'move', sign: -1, arg: this.parseExpr(), token };
      case 'right':
        return { kind: 'turn', sign: 1, arg: this.parseExpr(), token };
      case 'left':
        return { kind: 'turn', sign: -1, arg: this.parseExpr(), token };
      case 'repeat': {
        const count = this.parseExpr();
        this.next(); // [
        const body = this.parseList();
        const close = this.next();
        return { kind: 'repeat', count, body, token, close };
      }
    }
    throw new Error('unknown command');
  }
}

export function compile(source: string): Program {
  return { body: new Parser(tokenize(source)).parseList() };
}

