import { keywordOf } from './keywords';
import { tokenize, type Token } from './lexer';

export type Expr = { kind: 'num'; value: number; token: Token };

export type Stmt =
  | { kind: 'move'; sign: 1 | -1; arg: Expr; token: Token }
  | { kind: 'turn'; sign: 1 | -1; arg: Expr; token: Token };

export interface Program {
  body: Stmt[];
}

export function compile(source: string): Program {
  const tokens = tokenize(source);
  const body: Stmt[] = [];
  let pos = 0;
  while (pos < tokens.length) {
    const token = tokens[pos++];
    const argToken = tokens[pos++];
    const arg: Expr = { kind: 'num', value: argToken.value, token: argToken };
    switch (keywordOf(token.norm)) {
      case 'forward':
        body.push({ kind: 'move', sign: 1, arg, token });
        break;
      case 'back':
        body.push({ kind: 'move', sign: -1, arg, token });
        break;
      case 'right':
        body.push({ kind: 'turn', sign: 1, arg, token });
        break;
      case 'left':
        body.push({ kind: 'turn', sign: -1, arg, token });
        break;
    }
  }
  return { body };
}

