import { Orientation } from './geometry';
import type { Expr, Program, Stmt } from './parser';
import type { Segment, Vec3 } from './types';

export interface Turtle {
  position: Vec3;
  orientation: Orientation;
  color: string;
  width: number;
}

export interface Machine {
  turtle: Turtle;
  segments: Segment[];
}

export function createMachine(): Machine {
  return {
    turtle: { position: [0, 0, 0], orientation: new Orientation(), color: '#16866a', width: 3 },
    segments: [],
  };
}

function evaluate(expr: Expr): number {
  return expr.value;
}

function move(m: Machine, distance: number): void {
  const t = m.turtle;
  const h = t.orientation.heading();
  const from = t.position;
  const to: Vec3 = [from[0] + h[0] * distance, from[1] + h[1] * distance, from[2] + h[2] * distance];
  m.segments.push({ from, to, color: t.color, width: t.width });
  t.position = to;
}

function* execStmt(m: Machine, stmt: Stmt): Generator<Stmt> {
  switch (stmt.kind) {
    case 'move':
      move(m, evaluate(stmt.arg) * stmt.sign);
      break;
    case 'turn':
      m.turtle.orientation.turn(evaluate(stmt.arg) * stmt.sign);
      break;
  }
  yield stmt;
}

export function* execute(m: Machine, program: Program): Generator<Stmt> {
  for (const stmt of program.body) yield* execStmt(m, stmt);
}

