import type { Token } from './lexer';
import type { LogoError } from './types';

/** Thrown inside the language implementation; converted to a plain LogoError at the edge. */
export class LogoFailure extends Error {
  constructor(
    message: string,
    readonly line: number,
    readonly column: number,
  ) {
    super(message);
  }

  static at(token: Pick<Token, 'line' | 'column'>, message: string): LogoFailure {
    return new LogoFailure(message, token.line, token.column);
  }

  toError(): LogoError {
    return { message: this.message, line: this.line, column: this.column };
  }
}

