export type TokenType = 'num' | 'word' | 'str' | '[' | ']';

export interface Token {
  type: TokenType;
  text: string;
  /** Lower-cased, NFC-normalised text, used for keyword and name lookups. */
  norm: string;
  value: number;
  line: number;
  column: number;
}

const DIGIT = /[0-9]/;
const WORD_CHAR = /[\p{L}\p{M}\p{N}_]/u;

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let column = 1;
  const push = (type: TokenType, start: number, value = NaN) => {
    const text = source.slice(start, i);
    tokens.push({ type, text, norm: text.normalize('NFC').toLowerCase(), value, line, column });
    column += i - start;
  };
  while (i < source.length) {
    const ch = source[i];
    const start = i;
    if (ch === '\n') {
      i++;
      line++;
      column = 1;
    } else if (/\s/.test(ch)) {
      i++;
      column++;
    } else if (ch === '[' || ch === ']') {
      i++;
      push(ch, start);
    } else if (ch === '"') {
      i++;
      while (i < source.length && source[i] !== '"' && source[i] !== '\n') i++;
      if (source[i] === '"') i++;
      push('str', start);
    } else if (DIGIT.test(ch)) {
      while (i < source.length && DIGIT.test(source[i])) i++;
      push('num', start, Number(source.slice(start, i)));
    } else {
      while (i < source.length && WORD_CHAR.test(source[i])) i++;
      if (i === start) i++;
      push('word', start);
    }
  }
  return tokens;
}

