import { describe, expect, test } from 'bun:test';
import { run } from '../src/lang';

describe('drawing in 2D', () => {
  test('np draws one segment forward along +Y with the default pen', () => {
    expect(run('np 100', '2d')).toEqual({
      segments: [{ from: [0, 0, 0], to: [0, 100, 0], color: '#16866a', width: 3 }],
      error: null,
    });
  });

  test('pw 90 turns clockwise seen from above, so the turtle then heads along +X', () => {
    const { segments, error } = run('pw 90 np 50', '2d');
    expect(error).toBeNull();
    expect(segments.map((s) => [s.from, s.to])).toEqual([[[0, 0, 0], [50, 0, 0]]]);
  });

  test('powtorz runs its bracketed body the given number of times', () => {
    const { segments, error } = run('powtorz 4 [np 120 pw 90]', '2d');
    expect(error).toBeNull();
    expect(segments.map((s) => s.to)).toEqual([
      [0, 120, 0],
      [120, 120, 0],
      [120, 0, 0],
      [0, 0, 0],
    ]);
  });

  test('pod lifts the pen so moves draw nothing until opu lowers it', () => {
    const { segments } = run('pod np 10 opu np 10', '2d');
    expect(segments.map((s) => [s.from, s.to])).toEqual([[[0, 10, 0], [0, 20, 0]]]);
  });

  test('kolor and grubosc style the following segments; colours come back lowercase', () => {
    const { segments } = run('kolor "#C1763D" grubosc 5 np 10', '2d');
    expect(segments.map((s) => [s.color, s.width])).toEqual([['#c1763d', 5]]);
  });

  test('a semicolon starts a comment that runs to the end of the line', () => {
    const { segments, error } = run('; Cztery boki\nnp 10 ; i skręt pw 90\nnp 5', '2d');
    expect(error).toBeNull();
    expect(segments.map((s) => s.to)).toEqual([
      [0, 10, 0],
      [0, 15, 0],
    ]);
  });
});

/** Distance moved by a single `np <expr>` program. */
function distanceOf(expr: string): number | string {
  const { segments, error } = run(`np ${expr}`, '2d');
  if (error) return `error @${error.line}:${error.column}`;
  return segments.length === 0 ? 0 : segments[0].to[1];
}

describe('expressions', () => {
  test('* and / bind tighter than + and -, equal precedence associates left', () => {
    expect([distanceOf('2 + 3 * 4'), distanceOf('20 - 5 - 3'), distanceOf('100 / 5 / 2')]).toEqual([14, 12, 10]);
  });

  test('a binary operator needs whitespace on both sides or on neither', () => {
    expect([distanceOf('10 - 5'), distanceOf('10-5'), distanceOf('10 -5'), distanceOf('10- 5')]).toEqual([
      5,
      5,
      'error @1:7',
      'error @1:6',
    ]);
  });

  test('division by zero and non-finite results are run-time errors at the first token of the argument', () => {
    const zero = run('np 10\nnp 5 + 1 / (2 - 2)', '2d');
    expect(zero.segments.length).toBe(1);
    expect(zero.error).toMatchObject({ line: 2, column: 4 });
    const huge = run(`niech a 1${'0'.repeat(300)}\npw 90 np (a * a)`, '2d');
    expect(huge.error).toMatchObject({ line: 2, column: 10 });
  });

  test('parentheses group and unary signs stack anywhere an operand is expected', () => {
    expect([distanceOf('(2 + 3) * 4'), distanceOf('-(3 - 5)'), distanceOf('- -2'), distanceOf('+4'), distanceOf('2 * -(-3)')]).toEqual([
      20, 2, 2, 4, 6,
    ]);
  });

  test('numbers are unsigned decimal literals and nothing else', () => {
    expect(['12.5', '.5', '007'].map(distanceOf)).toEqual([12.5, 0.5, 7]);
    expect(['1e3', '0x10', 'NaN', 'Infinity', '12.', '1.2.3'].map(distanceOf)).toEqual(Array(6).fill('error @1:4'));
  });
});

/** Length of every drawn segment, rounded to 1e-9. */
function lengths(source: string, mode: '2d' | '3d' = '2d'): number[] {
  const { segments, error } = run(source, mode);
  if (error) throw new Error(`${error.line}:${error.column} ${error.message}`);
  return segments.map((s) => Math.round(Math.hypot(...s.to.map((v, i) => v - s.from[i])) * 1e9) / 1e9);
}

describe('repeat', () => {
  test('nrpowt is the iteration number of the innermost enclosing repeat, starting at 1', () => {
    expect(lengths('powtorz 3 [np nrpowt * 10 pw 90]')).toEqual([10, 20, 30]);
    expect(lengths('powtorz 2 [powtorz 3 [np nrpowt] np 100 * repcount]')).toEqual([1, 2, 3, 100, 1, 2, 3, 200]);
  });

  test('nrpowt outside any repeat is a parse-time error at nrpowt', () => {
    expect(run('np 10\nnp 2 * nrpowt', '2d')).toMatchObject({ segments: [], error: { line: 2, column: 8 } });
    expect(run('powtorz nrpowt [np 1]', '2d').error).toMatchObject({ line: 1, column: 9 });
  });
});

describe('conditionals', () => {
  test('jeśli runs its body when the condition holds; jeżeli picks one of two bodies', () => {
    const source = [
      'niech a 5',
      'jeśli a > 3 [np 1]',
      'jesli a < 3 [np 2]',
      'jeżeli a = 5 [np 3] [np 4]',
      'jezeli a <> 5 [np 5] [np 6]',
      'if a <= 5 [np 7]',
      'ifelse a >= 6 [np 8] [np 9]',
      'jeśli a>4 [np 10]',
    ].join('\n');
    expect(lengths(source)).toEqual([1, 3, 6, 7, 9, 10]);
  });
});

describe('variables', () => {
  test('niech assigns a variable that later expressions read, also as :name; reassignment updates it', () => {
    const { segments, error } = run('niech bok 30\nnp bok\nniech bok :bok + 10\nnp BOK * 2', '2d');
    expect(error).toBeNull();
    expect(segments.map((s) => s.to[1])).toEqual([30, 110]);
  });

  test('reading a variable before it is assigned is a run-time error at the argument; the drawing is kept', () => {
    const { segments, error } = run('np 10\nnp 1 + x\nniech x 5', '2d');
    expect(segments.map((s) => s.to)).toEqual([[0, 10, 0]]);
    expect(error).toMatchObject({ line: 2, column: 4 });
    expect(error!.message).toContain('x');
  });
});

describe('parse-time errors', () => {
  test('an unknown command is reported at its line and column and nothing is drawn', () => {
    const { segments, error } = run('np 10\n  nq 20', '2d');
    expect(segments).toEqual([]);
    expect(error).toMatchObject({ line: 2, column: 3 });
    expect(error!.message).toContain('nq');
  });

  test('a missing argument is reported where it should have started, or at the command at the end', () => {
    const at = (source: string) => {
      const { error } = run(source, '2d');
      return error && [error.line, error.column];
    };
    expect([at('powtorz 2 [np]'), at('np ()'), at('pw 90\nnp'), at('np pw 90')]).toEqual([
      [1, 14],
      [1, 5],
      [2, 1],
      [1, 4],
    ]);
  });

  test('a stray value where a command is expected is reported at that value and quoted whole', () => {
    const { error } = run('np 10 -5', '2d');
    expect(error).toMatchObject({ line: 1, column: 7 });
    expect(error!.message).toContain('„-5”');
    expect(run('np 10 20', '2d').error).toMatchObject({ line: 1, column: 7 });
  });

  test('unbalanced brackets are reported at the unmatched bracket', () => {
    const at = (source: string) => {
      const { error } = run(source, '2d');
      return error && [error.line, error.column];
    };
    expect([
      at('powtorz 4 [np 10'),
      at('np 10 ]'),
      at('powtorz 4 [\n  powtorz 2 [np 10]\n'),
      at('powtorz 4 np 10'),
      at('powtorz 4'),
    ]).toEqual([
      [1, 11],
      [1, 7],
      [1, 11],
      [1, 11],
      [1, 1],
    ]);
  });

  test('a malformed colour literal is reported at the literal', () => {
    const at = (source: string) => {
      const { error } = run(source, '2d');
      return error && [error.line, error.column];
    };
    expect([
      at('kolor "#12345"'),
      at('kolor "red"'),
      at('kolor "#12345g"'),
      at('kolor "#123456'),
      at('kolor 5'),
      at('np 5 kolor'),
      at('kolor "#AbCdEf"'),
    ]).toEqual([[1, 7], [1, 7], [1, 7], [1, 7], [1, 7], [1, 6], null]);
  });

  test('a literal width outside 1–12 or not an integer is a parse-time error at the argument', () => {
    for (const bad of ['13', '0', '2.5', '(20 - 7)', '-1']) {
      const { segments, error } = run(`np 10 grubosc ${bad}`, '2d');
      expect({ bad, segments, at: error && [error.line, error.column] }).toEqual({ bad, segments: [], at: [1, 15] });
    }
    expect(run('grubosc 6 * 2 np 1', '2d').segments[0].width).toBe(12);
  });

  test('a literal repeat count outside 0–10000 or not an integer is a parse-time error at the argument', () => {
    for (const bad of ['10001', '2.5', '-1', '(1 - 2)']) {
      const { segments, error } = run(`np 10 powtorz ${bad} [np 1]`, '2d');
      expect({ bad, segments, at: error && [error.line, error.column] }).toEqual({ bad, segments: [], at: [1, 15] });
    }
    expect(run('powtorz 0 [np 10] np 1', '2d')).toEqual({
      segments: [{ from: [0, 0, 0], to: [0, 1, 0], color: '#16866a', width: 3 }],
      error: null,
    });
  });
});

