1	import { LogoFailure } from './errors';
2	import { keywordOf } from './keywords';
3	import { tokenize, type Token } from './lexer';
4	
5	export type BinaryOp = '+' | '-' | '*' | '/';
6	
7	export type Expr =
8	  | { kind: 'num'; value: number; token: Token }
9	  | { kind: 'var'; name: string; token: Token }
10	  | { kind: 'repcount'; token: Token }
11	  | { kind: 'negate'; operand: Expr; token: Token }
12	  | { kind: 'binary'; op: BinaryOp; left: Expr; right: Expr; token: Token };
13	
14	/** An argument of a command: run-time problems with it are reported at its first token. */
15	export interface Arg {
16	  expr: Expr;
17	  first: Token;
18	}
19	
20	export type Comparison = '<' | '>' | '=' | '<=' | '>=' | '<>';
21	
22	/** `left op right`; run-time problems with it are reported at its first token. */
23	export interface Condition {
24	  left: Expr;
25	  op: Comparison;
26	  right: Expr;
27	  first: Token;
28	}
29	
30	export interface Body {
31	  body: Stmt[];
32	  close: Token;
33	}
34	
35	const PRECEDENCE: Record<BinaryOp, number> = { '+': 1, '-': 1, '*': 2, '/': 2 };
36	
37	export type Stmt =
38	  | { kind: 'move'; sign: 1 | -1; arg: Arg; token: Token }
39	  | { kind: 'turn'; sign: 1 | -1; arg: Arg; token: Token }
40	  | { kind: 'pen'; down: boolean; token: Token }
41	  | { kind: 'color'; color: string; token: Token }
42	  | { kind: 'width'; arg: Arg; token: Token }
43	  | { kind: 'repeat'; count: Arg; body: Stmt[]; token: Token; close: Token }
44	  | { kind: 'let'; name: string; arg: Arg; token: Token }
45	  | { kind: 'if'; cond: Condition; then: Body; otherwise: Body | null; token: Token };
46	
47	export interface Program {
48	  body: Stmt[];
49	}
50	
51	type IntegerCheck = (value: number, at: Token) => void;
52	
53	export const checkWidth: IntegerCheck = (value, at) => {
54	  if (!Number.isInteger(value) || value < 1 || value > 12) {
55	    throw LogoFailure.at(at, `Grubość musi być liczbą całkowitą od 1 do 12, a wynosi ${value}.`);
56	  }
57	};
58	
59	export const checkRepeatCount: IntegerCheck = (value, at) => {
60	  if (!Number.isInteger(value) || value < 0 || value > 10000) {
61	    throw LogoFailure.at(at, `Liczba powtórzeń musi być liczbą całkowitą od 0 do 10 000, a wynosi ${value}.`);
62	  }
63	};
64	
65	export function applyOp(op: BinaryOp, a: number, b: number): number {
66	  switch (op) {
67	    case '+':
68	      return a + b;
69	    case '-':
70	      return a - b;
71	    case '*':
72	      return a * b;
73	    case '/':
74	      return a / b;
75	  }
76	}
