78	/** The value of an expression made only of numbers and operators, otherwise undefined. */
79	function constantValue(expr: Expr): number | undefined {
80	  switch (expr.kind) {
81	    case 'num':
82	      return expr.value;
83	    case 'var':
84	    case 'repcount':
85	      return undefined;
86	    case 'negate': {
87	      const v = constantValue(expr.operand);
88	      return v === undefined ? undefined : -v;
89	    }
90	    case 'binary': {
91	      const a = constantValue(expr.left);
92	      const b = constantValue(expr.right);
93	      if (a === undefined || b === undefined) return undefined;
94	      return applyOp(expr.op, a, b);
95	    }
96	  }
97	}
