230	  private parsePrimary(context: Token): Expr {
231	    const token = this.peek();
232	    if (!token) throw LogoFailure.at(context, `Po „${context.text}” brakuje liczby.`);
233	    if (!this.canStartExpr(token)) {
234	      throw LogoFailure.at(token, `Po „${context.text}” powinna być liczba, a jest „${token.text}”.`);
235	    }
236	    this.pos++;
