285	  }
286	
287	  private parseStatement(): Stmt {
288	    const token = this.next();
289	    if (token.type !== 'word' && this.canStartExpr(token)) {
290	      this.pos--;
291	      throw this.strayValue(token);
292	    }
293	    if (token.type === ')') throw LogoFailure.at(token, 'Nawias „)” nie ma pary — brakuje otwierającego „(”.');
294	    if (token.type === '[') {
295	      throw LogoFailure.at(token, 'Nawias „[” może stać tylko po poleceniu, np. „powtórz 4 [ … ]”.');
296	    }
297	    switch (keywordOf(token.norm)) {
298	      case 'forward':
299	        return { kind: 'move', sign: 1, arg: this.parseArg(token), token };
300	      case 'back':
301	        return { kind: 'move', sign: -1, arg: this.parseArg(token), token };
302	      case 'right':
303	        return { kind: 'turn', sign: 1, arg: this.parseArg(token), token };
304	      case 'left':
305	        return { kind: 'turn', sign: -1, arg: this.parseArg(token), token };
306	      case 'penup':
307	        return { kind: 'pen', down: false, token };
308	      case 'pendown':
309	        return { kind: 'pen', down: true, token };
310	      case 'color':
311	        return { kind: 'color', color: this.parseColor(token), token };
312	      case 'width':
