314	      case 'let': {
315	        const target = this.peek();
316	        if (!target) throw LogoFailure.at(token, `Po „${token.text}” brakuje nazwy zmiennej, np. „niech bok 50”.`);
317	        if ((target.type !== 'word' && target.type !== 'name') || keywordOf(target.norm)) {
318	          throw LogoFailure.at(target, `Po „${token.text}” powinna być nazwa zmiennej, a jest „${target.text}”.`);
319	        }
320	        this.pos++;
321	        return { kind: 'let', name: target.norm, arg: this.parseArg(target), token };
322	      }
323	      case 'if': {
324	        const cond = this.parseCondition(token);
325	        return { kind: 'if', cond, then: this.parseBody(token), otherwise: null, token };
326	      }
327	      case 'ifelse': {
328	        const cond = this.parseCondition(token);
329	        const then = this.parseBody(token);
330	        return { kind: 'if', cond, then, otherwise: this.parseBody(token), token };
331	      }
332	      case 'repeat': {
333	        const count = this.parseIntegerArg(token, checkRepeatCount);
334	        this.repeatDepth++;
335	        const { body, close } = this.parseBody(token);
336	        this.repeatDepth--;
337	        return { kind: 'repeat', count, body, token, close };
338	      }
339	    }
340	    throw LogoFailure.at(token, `Nie znam polecenia „${token.text}”.`);
341	  }
342	}
343	
344	export type CompileResult = { program: Program; error: null } | { program: null; error: LogoFailure };
345	
346	export function compile(source: string): CompileResult {
347	  try {
348	    return { program: { body: new Parser(source, tokenize(source)).parseProgram() }, error: null };
349	  } catch (e) {
350	    if (e instanceof LogoFailure) return { program: null, error: e };
351	    throw e;
352	  }
