import { LogoFailure } from './errors';
import { keywordOf } from './keywords';
import { tokenize, type Token } from './lexer';

export type BinaryOp = '+' | '-' | '*' | '/';

export type Expr =
  | { kind: 'num'; value: number; token: Token }
  | { kind: 'var'; name: string; token: Token }
  | { kind: 'repcount'; token: Token }
  | { kind: 'negate'; operand: Expr; token: Token }
  | { kind: 'binary'; op: BinaryOp; left: Expr; right: Expr; token: Token };

/** An argument of a command: run-time problems with it are reported at its first token. */
export interface Arg {
  expr: Expr;
  first: Token;
}

export type Comparison = '<' | '>' | '=' | '<=' | '>=' | '<>';

/** `left op right`; run-time problems with it are reported at its first token. */
export interface Condition {
  left: Expr;
  op: Comparison;
  right: Expr;
  first: Token;
}

export interface Body {
  body: Stmt[];
  close: Token;
}

const PRECEDENCE: Record<BinaryOp, number> = { '+': 1, '-': 1, '*': 2, '/': 2 };

export type Stmt =
  | { kind: 'move'; sign: 1 | -1; arg: Arg; token: Token }
  | { kind: 'turn'; sign: 1 | -1; arg: Arg; token: Token }
  | { kind: 'pen'; down: boolean; token: Token }
  | { kind: 'color'; color: string; token: Token }
  | { kind: 'width'; arg: Arg; token: Token }
  | { kind: 'repeat'; count: Arg; body: Stmt[]; token: Token; close: Token }
  | { kind: 'let'; name: string; arg: Arg; token: Token }
  | { kind: 'if'; cond: Condition; then: Body; otherwise: Body | null; token: Token };

export interface Program {
  body: Stmt[];
}

type IntegerCheck = (value: number, at: Token) => void;

export const checkWidth: IntegerCheck = (value, at) => {
  if (!Number.isInteger(value) || value < 1 || value > 12) {
    throw LogoFailure.at(at, `Grubość musi być liczbą całkowitą od 1 do 12, a wynosi ${value}.`);
  }
};

export const checkRepeatCount: IntegerCheck = (value, at) => {
  if (!Number.isInteger(value) || value < 0 || value > 10000) {
    throw LogoFailure.at(at, `Liczba powtórzeń musi być liczbą całkowitą od 0 do 10 000, a wynosi ${value}.`);
  }
};

export function applyOp(op: BinaryOp, a: number, b: number): number {
  switch (op) {
    case '+':
      return a + b;
    case '-':
      return a - b;
    case '*':
      return a * b;
    case '/':
      return a / b;
  }
}

/** The value of an expression made only of numbers and operators, otherwise undefined. */
function constantValue(expr: Expr): number | undefined {
  switch (expr.kind) {
    case 'num':
      return expr.value;
    case 'var':
    case 'repcount':
      return undefined;
    case 'negate': {
      const v = constantValue(expr.operand);
      return v === undefined ? undefined : -v;
    }
    case 'binary': {
      const a = constantValue(expr.left);
      const b = constantValue(expr.right);
      if (a === undefined || b === undefined) return undefined;
      return applyOp(expr.op, a, b);
    }
  }
}

class Parser {
  private pos = 0;
  /** How many repeat bodies lexically enclose the current position. */
  private repeatDepth = 0;
  /** Names assigned by `niech` anywhere in the program. */
  private readonly variables = new Set<string>();

  constructor(
    private readonly source: string,
    private readonly tokens: Token[],
  ) {
    tokens.forEach((token, i) => {
      const target = tokens[i + 1];
      if (keywordOf(token.norm) === 'let' && target && (target.type === 'word' || target.type === 'name')) {
        this.variables.add(target.norm);
      }
    });
  }

  private next(): Token {
    return this.tokens[this.pos++];
  }

  private peek(): Token | undefined {
    return this.tokens[this.pos];
  }

  parseProgram(): Stmt[] {
    const list = this.parseList();
    const extra = this.peek();
    if (extra) throw LogoFailure.at(extra, 'Nawias „]” nie ma pary — brakuje otwierającego „[”.');
    return list;
  }

  private parseList(): Stmt[] {
    const list: Stmt[] = [];
    while (this.peek() && this.peek()!.type !== ']') list.push(this.parseStatement());
    return list;
  }

  private parseCondition(owner: Token): Condition {
    const { expr: left, first } = this.parseArg(owner);
    const token = this.peek();
    const hint = 'porównanie: <, >, =, <=, >= albo <>';
    if (!token) throw LogoFailure.at(owner, `Po „${owner.text}” brakuje warunku z porównaniem (${hint}).`);
    if (token.type !== 'cmp') throw LogoFailure.at(token, `W warunku powinno być ${hint}, a jest „${token.text}”.`);
    this.pos++;
    const right = this.parseExpr(token);
    return { left, op: token.text as Comparison, right, first };
  }

  /** Parses `[ ... ]` after `owner`; returns the statements and the closing bracket. */
  private parseBody(owner: Token): Body {
    const open = this.peek();
    if (!open) throw LogoFailure.at(owner, `Po „${owner.text}” brakuje nawiasu „[” z poleceniami.`);
    if (open.type !== '[') {
      throw LogoFailure.at(open, `Po „${owner.text}” powinien być nawias „[” z poleceniami, a jest „${open.text}”.`);
    }
    this.pos++;
    const body = this.parseList();
    const close = this.peek();
    if (!close) throw LogoFailure.at(open, 'Nawias „[” nie został zamknięty — brakuje „]”.');
    this.pos++;
    return { body, close };
  }

  /** Parses the expression argument of `owner`, reporting a missing one where it should start. */
  private parseArg(owner: Token): Arg {
    const token = this.peek();
    if (!token) throw LogoFailure.at(owner, `Po „${owner.text}” brakuje liczby.`);
    if (!this.canStartExpr(token)) {
      throw LogoFailure.at(token, `Po „${owner.text}” powinna być liczba, a jest „${token.text}”.`);
    }
    return { expr: this.parseExpr(owner), first: token };
  }

  /** Parses an integer argument; when it is written without names it is checked right away. */
  private parseIntegerArg(owner: Token, check: IntegerCheck): Arg {
    const arg = this.parseArg(owner);
    const value = constantValue(arg.expr);
    if (value !== undefined) check(value, arg.first);
    return arg;
  }

  private canStartExpr(token: Token): boolean {
    switch (token.type) {
      case 'num':
      case 'name':
      case '(':
        return true;
      case 'op':
        return token.text === '-' || token.text === '+';
      case 'word': {
        const keyword = keywordOf(token.norm);
        return keyword === undefined || keyword === 'repcount';
      }
      default:
        return false;
    }
  }

  /** `context` is the token after which the expression starts, used to report a missing operand. */
  private parseExpr(context: Token, minPrecedence = 1): Expr {
    let left = this.parseOperand(context);
    for (;;) {
      const token = this.peek();
      if (!token || token.type !== 'op') return left;
      // `np 10 -5` is `np 10` followed by a stray `-5`: the sign is not a binary operator.
      if (token.spaceBefore !== token.spaceAfter) return left;
      const op = token.text as BinaryOp;
      const precedence = PRECEDENCE[op];
      if (precedence < minPrecedence) return left;
      this.pos++;
      const right = this.parseExpr(token, precedence + 1);
      left = { kind: 'binary', op, left, right, token };
    }
  }

  private parseOperand(context: Token): Expr {
    // Signs are collected iteratively so that long chains like `- - - 2` cannot overflow the stack.
    const signs: Token[] = [];
    while (this.peek()?.type === 'op' && (this.peek()!.text === '-' || this.peek()!.text === '+')) {
      signs.push(this.next());
    }
    let expr = this.parsePrimary(signs.length > 0 ? signs[signs.length - 1] : context);
    for (let i = signs.length - 1; i >= 0; i--) {
      if (signs[i].text === '-') expr = { kind: 'negate', operand: expr, token: signs[i] };
    }
    return expr;
  }

  private parsePrimary(context: Token): Expr {
    const token = this.peek();
    if (!token) throw LogoFailure.at(context, `Po „${context.text}” brakuje liczby.`);
    if (!this.canStartExpr(token)) {
      throw LogoFailure.at(token, `Po „${context.text}” powinna być liczba, a jest „${token.text}”.`);
    }
    this.pos++;
    if (token.type === '(') {
      const inner = this.parseExpr(token);
      if (this.peek()?.type !== ')') throw LogoFailure.at(token, 'Nawias „(” nie został zamknięty.');
      this.pos++;
      return inner;
    }
    if (token.type === 'word' && keywordOf(token.norm) === 'repcount') {
      if (this.repeatDepth === 0) {
        throw LogoFailure.at(token, `„${token.text}” działa tylko wewnątrz nawiasów polecenia „powtórz”.`);
      }
      return { kind: 'repcount', token };
    }
    if (token.type === 'word' || token.type === 'name') {
      if (!this.variables.has(token.norm)) throw LogoFailure.at(token, `Nie znam nazwy „${token.text}”.`);
      return { kind: 'var', name: token.norm, token };
    }
    return { kind: 'num', value: token.value, token };
  }

  private parseColor(owner: Token): string {
    const token = this.peek();
    const example = 'np. kolor "#16866a"';
    if (!token) throw LogoFailure.at(owner, `Po „${owner.text}” brakuje koloru (${example}).`);
    if (token.type !== 'str') {
      throw LogoFailure.at(token, `Kolor zapisuje się w cudzysłowie jako # i sześć cyfr szesnastkowych (${example}).`);
    }
    const color = token.norm.slice(1, -1);
    if (!/^#[0-9a-f]{6}$/.test(color)) {
      throw LogoFailure.at(token, `${token.text} nie jest poprawnym kolorem. Podaj # i sześć cyfr szesnastkowych (${example}).`);
    }
    this.pos++;
    return color;
  }

  /** Reports a value standing where a command should be, quoting the whole value. */
  private strayValue(token: Token): LogoFailure {
    let text = token.text;
    try {
      this.parseExpr(token);
      text = this.source.slice(token.start, this.tokens[this.pos - 1].end);
    } catch {
      // The value itself is malformed; quoting its first token is enough.
    }
    let message = `„${text}” to wartość, a w tym miejscu powinno stać polecenie.`;
    if (token.type === 'op' && token.spaceBefore && !token.spaceAfter) {
      message += ` Jeśli to miało być działanie, postaw odstępy po obu stronach „${token.text}” albo po żadnej.`;
    }
    return LogoFailure.at(token, message);
  }

  private parseStatement(): Stmt {
    const token = this.next();
    if (token.type !== 'word' && this.canStartExpr(token)) {
      this.pos--;
      throw this.strayValue(token);
    }
    if (token.type === ')') throw LogoFailure.at(token, 'Nawias „)” nie ma pary — brakuje otwierającego „(”.');
    if (token.type === '[') {
