import { LogoFailure } from './errors';
import { Orientation } from './geometry';
import { applyOp, type Arg, type Condition, type Expr, type Program, type Stmt } from './parser';
import type { Segment, Vec3 } from './types';

export interface Turtle {
  position: Vec3;
  orientation: Orientation;
  penDown: boolean;
  color: string;
  width: number;
}

export interface Machine {
  turtle: Turtle;
  segments: Segment[];
  globals: Map<string, number>;
  /** Iteration numbers of the active repeats, innermost last. */
  iterations: number[];
}

export function createMachine(): Machine {
  return {
    turtle: { position: [0, 0, 0], orientation: new Orientation(), penDown: true, color: '#16866a', width: 3 },
    segments: [],
    globals: new Map(),
    iterations: [],
  };
}

/** A problem found while evaluating; it is reported at the first token of the whole argument. */
class EvalProblem {
  constructor(readonly message: string) {}
}

function finite(value: number): number {
  if (!Number.isFinite(value)) throw new EvalProblem('Wynik obliczenia jest za duży, by go użyć.');
  return value;
}

function evaluate(m: Machine, expr: Expr): number {
  switch (expr.kind) {
    case 'num':
      return expr.value;
    case 'var': {
      const value = m.globals.get(expr.name);
      if (value === undefined) throw new EvalProblem(`Zmienna „${expr.token.text}” nie ma jeszcze wartości — najpierw nadaj ją przez „niech”.`);
      return value;
    }
    case 'repcount':
      return m.iterations[m.iterations.length - 1];
    case 'negate':
      return -evaluate(m, expr.operand);
    case 'binary': {
      const a = evaluate(m, expr.left);
      const b = evaluate(m, expr.right);
      if (expr.op === '/' && b === 0) throw new EvalProblem('Nie można dzielić przez zero.');
      return finite(applyOp(expr.op, a, b));
    }
  }
}

function evaluateArg(m: Machine, arg: Arg): number {
  try {
    return evaluate(m, arg.expr);
  } catch (e) {
    if (e instanceof EvalProblem) throw LogoFailure.at(arg.first, e.message);
    throw e;
  }
}

function holds(m: Machine, cond: Condition): boolean {
  try {
    const a = evaluate(m, cond.left);
    const b = evaluate(m, cond.right);
    switch (cond.op) {
      case '<':
        return a < b;
      case '>':
        return a > b;
      case '=':
        return a === b;
      case '<=':
        return a <= b;
      case '>=':
        return a >= b;
      case '<>':
        return a !== b;
    }
  } catch (e) {
    if (e instanceof EvalProblem) throw LogoFailure.at(cond.first, e.message);
    throw e;
  }
}

function move(m: Machine, distance: number): void {
  const t = m.turtle;
  const h = t.orientation.heading();
  const from = t.position;
  const to: Vec3 = [from[0] + h[0] * distance, from[1] + h[1] * distance, from[2] + h[2] * distance];
  if (t.penDown) m.segments.push({ from, to, color: t.color, width: t.width });
  t.position = to;
}

function* execStmt(m: Machine, stmt: Stmt): Generator<Stmt> {
  switch (stmt.kind) {
    case 'move':
      move(m, evaluateArg(m, stmt.arg) * stmt.sign);
      break;
    case 'turn':
      m.turtle.orientation.turn(evaluateArg(m, stmt.arg) * stmt.sign);
      break;
    case 'pen':
      m.turtle.penDown = stmt.down;
      break;
    case 'color':
      m.turtle.color = stmt.color;
      break;
    case 'width':
      m.turtle.width = evaluateArg(m, stmt.arg);
      break;
    case 'let':
      m.globals.set(stmt.name, evaluateArg(m, stmt.arg));
      break;
    case 'if': {
      const branch = holds(m, stmt.cond) ? stmt.then : stmt.otherwise;
      yield stmt;
      if (branch) yield* execList(m, branch.body);
      return;
    }
    case 'repeat': {
      const n = evaluateArg(m, stmt.count);
      yield stmt;
      m.iterations.push(0);
      for (let i = 1; i <= n; i++) {
        m.iterations[m.iterations.length - 1] = i;
        yield* execList(m, stmt.body);
      }
      m.iterations.pop();
      return;
    }
  }
  yield stmt;
}

function* execList(m: Machine, list: Stmt[]): Generator<Stmt> {
  for (const stmt of list) yield* execStmt(m, stmt);
}

export function* execute(m: Machine, program: Program): Generator<Stmt> {
  yield* execList(m, program.body);
}

