      at('kolor "red"'),
      at('kolor "#12345g"'),
      at('kolor "#123456'),
      at('kolor 5'),
      at('np 5 kolor'),
      at('kolor "#AbCdEf"'),
    ]).toEqual([[1, 7], [1, 7], [1, 7], [1, 7], [1, 7], [1, 6], null]);
  });

