import { describe, expect, test } from 'bun:test';
import { EXAMPLES } from '../src/app/examples';
import { run } from '../src/lang';
import { STANDARD } from './fixtures/standard-programs';

describe('standard programs', () => {
  test('are shipped verbatim under their names and modes', () => {
    expect(EXAMPLES.map(({ id, title, mode, source }) => ({ id, title, mode, source }))).toEqual(STANDARD);
  });

  // Segment counts worked out by hand from each program.
  const expectedSegments: Record<string, number> = {
    kwadrat: 4,
    gwiazda: 5,
    rozeta: 48,
    spirala: 90,
    wielokaty: 3 + 4 + 5 + 6 + 7 + 8 + 9,
    drzewo: 255, // lengths 90 … 7.41 draw (8 levels): 2^8 − 1 branches
    sniezynka: 3 * 4 ** 4,
    schody: 12,
    szescian: 4 + 1 + 4 + 4 * 2,
    pierscien: 36,
    kula: 12 * 36,
    helisa: 120 * 2,
    drzewo3d: 1 + 3 + 9 + 27 + 81, // lengths 70 … 9.07 draw (5 levels)
  };

  for (const program of STANDARD) {
    test(`${program.id} runs without error in ${program.mode}`, () => {
      const { segments, error } = run(program.source, program.mode);
      expect(error).toBeNull();
      expect(segments.length).toBe(expectedSegments[program.id]);
    });
  }

  test('kwadrat closes a 120 × 120 square', () => {
    const { segments } = run(STANDARD[0].source, '2d');
    expect(segments.map((s) => s.to)).toEqual([
      [0, 120, 0],
      [120, 120, 0],
      [120, 0, 0],
      [0, 0, 0],
    ]);
  });
});

