import { LogoFailure } from './errors';
import { keywordOf } from './keywords';
import { tokenize, type Token } from './lexer';
import type { Mode } from './types';

export type BinaryOp = '+' | '-' | '*' | '/';

export type Expr =
  | { kind: 'num'; value: number; token: Token }
  | { kind: 'var'; name: string; token: Token }
  | { kind: 'repcount'; token: Token }
  | { kind: 'negate'; operand: Expr; token: Token }
  | { kind: 'binary'; op: BinaryOp; left: Expr; right: Expr; token: Token };

/** An argument of a command: run-time problems with it are reported at its first token. */
export interface Arg {
  expr: Expr;
  first: Token;
}

export type Comparison = '<' | '>' | '=' | '<=' | '>=' | '<>';

/** `left op right`; run-time problems with it are reported at its first token. */
export interface Condition {
  left: Expr;
  op: Comparison;
  right: Expr;
  first: Token;
}

export interface Body {
  body: Stmt[];
  close: Token;
}

const PRECEDENCE: Record<BinaryOp, number> = { '+': 1, '-': 1, '*': 2, '/': 2 };

export type Stmt =
  | { kind: 'move'; sign: 1 | -1; arg: Arg; token: Token }
  | { kind: 'turn'; axis: 'yaw' | 'pitch' | 'roll'; sign: 1 | -1; arg: Arg; token: Token }
  | { kind: 'pen'; down: boolean; token: Token }
  | { kind: 'stop'; token: Token }
  | { kind: 'home'; token: Token }
  | { kind: 'clear'; token: Token }
  | { kind: 'color'; color: string; token: Token }
  | { kind: 'width'; arg: Arg; token: Token }
  | { kind: 'repeat'; count: Arg; body: Stmt[]; token: Token; close: Token }
  | { kind: 'let'; name: string; arg: Arg; token: Token }
  | { kind: 'if'; cond: Condition; then: Body; otherwise: Body | null; token: Token }
  | { kind: 'call'; proc: Procedure; args: Arg[]; token: Token };

export interface Procedure {
  name: string;
  /** The name as written in the definition. */
  title: string;
  params: string[];
  body: Stmt[];
  /** The `już` that closes the definition. */
  end: Token;
}

export interface Program {
  body: Stmt[];
  procedures: Procedure[];
}

type IntegerCheck = (value: number, at: Token) => void;

export const checkWidth: IntegerCheck = (value, at) => {
  if (!Number.isInteger(value) || value < 1 || value > 12) {
    throw LogoFailure.at(at, `Grubość musi być liczbą całkowitą od 1 do 12, a wynosi ${value}.`);
  }
};

export const checkRepeatCount: IntegerCheck = (value, at) => {
  if (!Number.isInteger(value) || value < 0 || value > 10000) {
    throw LogoFailure.at(at, `Liczba powtórzeń musi być liczbą całkowitą od 0 do 10 000, a wynosi ${value}.`);
  }
};

export function applyOp(op: BinaryOp, a: number, b: number): number {
  switch (op) {
    case '+':
      return a + b;
    case '-':
      return a - b;
    case '*':
      return a * b;
    case '/':
      return a / b;
  }
}

/** The value of an expression made only of numbers and operators, otherwise undefined. */
function constantValue(expr: Expr): number | undefined {
  switch (expr.kind) {
    case 'num':
      return expr.value;
    case 'var':
    case 'repcount':
      return undefined;
    case 'negate': {
      const v = constantValue(expr.operand);
      return v === undefined ? undefined : -v;
    }
    case 'binary': {
      const a = constantValue(expr.left);
      const b = constantValue(expr.right);
      if (a === undefined || b === undefined) return undefined;
      return applyOp(expr.op, a, b);
    }
  }
}

/** A definition found by the structure pass; its body is parsed later, in source order. */
interface Definition {
  oto: Token;
  proc: Procedure;
  bodyTokens: Token[];
  /** A problem with the header, the closing `już` or a repeated name. */
  problem: LogoFailure | null;
}

interface Structure {
  mode: Mode;
  /** Top-level tokens; each definition is replaced by one `def` token. */
  top: Token[];
  definitions: Map<Token, Definition>;
  procedures: Map<string, Procedure>;
}

const isName = (token: Token): boolean =>
  (token.type === 'word' || token.type === 'name') && keywordOf(token.norm) === undefined;

/** Reads `name`, then optionally `ma: a, b` or the legacy `:a :b`, from the header line. */
function parseHeader(oto: Token, line: Token[], proc: Procedure): LogoFailure | null {
  const [nameToken, ...rest] = line;
  if (!nameToken) return LogoFailure.at(oto, `Po „${oto.text}” podaj nazwę procedury, np. „oto kwadrat ma: bok”.`);
  if (nameToken.type !== 'word' || keywordOf(nameToken.norm) !== undefined) {
    return LogoFailure.at(nameToken, `„${nameToken.text}” nie może być nazwą procedury.`);
  }
  proc.name = nameToken.norm;
  proc.title = nameToken.text;
  const addParam = (token: Token | undefined, after: Token): LogoFailure | null => {
    if (!token) return LogoFailure.at(after, `Po „${after.text}” podaj nazwę parametru.`);
    if (!isName(token)) return LogoFailure.at(token, `„${token.text}” nie może być nazwą parametru.`);
    if (proc.params.includes(token.norm)) return LogoFailure.at(token, `Parametr „${token.text}” powtarza się.`);
    proc.params.push(token.norm);
    return null;
  };
  if (rest.length === 0) return null;
  if (rest[0].type === 'label' && rest[0].norm === 'ma') {
    for (let i = 1; ; i += 2) {
      const problem = addParam(rest[i], rest[i - 1]);
      if (problem) return problem;
      const comma = rest[i + 1];
      if (!comma) return null;
      if (comma.type !== ',') return LogoFailure.at(comma, `Parametry oddziela się przecinkami, a jest „${comma.text}”.`);
    }
  }
  if (rest[0].type === 'name') {
    for (const token of rest) {
      if (token.type !== 'name') return LogoFailure.at(token, `Parametry zapisuje się jako :nazwa, a jest „${token.text}”.`);
      const problem = addParam(token, token);
      if (problem) return problem;
    }
    return null;
  }
  return LogoFailure.at(rest[0], `Po nazwie procedury może być tylko „ma:” i lista parametrów, np. „oto ${proc.title} ma: bok”.`);
}

const isEndLine = (token: Token) => keywordOf(token.norm) === 'end' && token.lineStart && token.lineEnd;

/** Splits the program into top-level code and procedure definitions. */
function structure(tokens: Token[], mode: Mode): Structure {
  const top: Token[] = [];
  const definitions = new Map<Token, Definition>();
  const procedures = new Map<string, Procedure>();
  let i = 0;
  while (i < tokens.length) {
    const oto = tokens[i];
    if (oto.type !== 'word' || keywordOf(oto.norm) !== 'to' || !oto.lineStart) {
      top.push(oto);
      i++;
      continue;
    }
    let j = i + 1;
    while (j < tokens.length && tokens[j].line === oto.line) j++;
    const proc: Procedure = { name: '', title: '', params: [], body: [], end: oto };
    let problem = parseHeader(oto, tokens.slice(i + 1, j), proc);
    const bodyStart = j;
    while (j < tokens.length && !isEndLine(tokens[j])) j++;
    const bodyTokens = tokens.slice(bodyStart, j);
    if (j < tokens.length) {
      proc.end = tokens[j++];
    } else {
      problem ??= LogoFailure.at(oto, `Procedura „${proc.title || '?'}” nie ma zakończenia — dopisz „już” w osobnym wierszu.`);
    }
    if (proc.name) {
      if (procedures.has(proc.name)) {
        problem ??= LogoFailure.at(tokens[i + 1], `Procedura „${proc.title}” jest już zdefiniowana.`);
      } else {
        procedures.set(proc.name, proc);
      }
    }
    const marker: Token = { ...oto, type: 'def' };
    definitions.set(marker, { oto, proc, bodyTokens, problem });
    top.push(marker);
    i = j;
  }
  return { mode, top, definitions, procedures };
}

/** Names assigned by `niech` among the tokens. */
function assignedNames(tokens: Token[]): Set<string> {
  const names = new Set<string>();
  tokens.forEach((token, i) => {
    const target = tokens[i + 1];
    if (keywordOf(token.norm) === 'let' && target && (target.type === 'word' || target.type === 'name')) {
      names.add(target.norm);
    }
  });
  return names;
}

interface Scope {
  /** The procedure being parsed, or null at top level. */
  proc: Procedure | null;
  /** Parameters and names assigned in the procedure body. */
  locals: Set<string>;
  globals: Set<string>;
}

class Parser {
  private pos = 0;
  /** How many repeat bodies lexically enclose the current position. */
  private repeatDepth = 0;
  /** How many bracket bodies enclose the current position. */
  private bracketDepth = 0;

  constructor(
    private readonly source: string,
    private readonly tokens: Token[],
    private readonly structure: Structure,
    private readonly scope: Scope,
  ) {}

  private knows(name: string): boolean {
    return this.scope.locals.has(name) || this.scope.globals.has(name);
  }

  private next(): Token {
    return this.tokens[this.pos++];
  }

  private peek(): Token | undefined {
    return this.tokens[this.pos];
  }

  /** Parses a whole unit: the top-level code or a procedure body. */
  parseUnit(): Stmt[] {
    const list = this.parseList();
    const extra = this.peek();
    if (extra) throw LogoFailure.at(extra, 'Nawias „]” nie ma pary — brakuje otwierającego „[”.');
    return list;
  }

  private parseList(): Stmt[] {
    const list: Stmt[] = [];
    for (let token = this.peek(); token && token.type !== ']'; token = this.peek()) {
      if (token.type === 'def') {
        this.pos++;
        this.parseDefinition(token);
      } else {
        list.push(this.parseStatement());
      }
    }
    return list;
  }

  private parseDefinition(marker: Token): void {
    const def = this.structure.definitions.get(marker)!;
    if (this.bracketDepth > 0) {
      throw LogoFailure.at(def.oto, 'Procedury definiuje się poza nawiasami, nie wewnątrz „powtórz” ani warunku.');
    }
    if (def.problem) throw def.problem;
    const locals = new Set([...def.proc.params, ...assignedNames(def.bodyTokens)]);
    const scope: Scope = { proc: def.proc, locals, globals: this.scope.globals };
    def.proc.body = new Parser(this.source, def.bodyTokens, this.structure, scope).parseUnit();
  }

  private parseCondition(owner: Token): Condition {
    const { expr: left, first } = this.parseArg(owner);
    const token = this.peek();
    const hint = 'porównanie: <, >, =, <=, >= albo <>';
    if (!token) throw LogoFailure.at(owner, `Po „${owner.text}” brakuje warunku z porównaniem (${hint}).`);
    if (token.type !== 'cmp') throw LogoFailure.at(token, `W warunku powinno być ${hint}, a jest „${token.text}”.`);
    this.pos++;
    const right = this.parseExpr(token);
    return { left, op: token.text as Comparison, right, first };
  }

  /** Parses `[ ... ]` after `owner`; returns the statements and the closing bracket. */
  private parseBody(owner: Token): Body {
    const open = this.peek();
    if (!open) throw LogoFailure.at(owner, `Po „${owner.text}” brakuje nawiasu „[” z poleceniami.`);
    if (open.type !== '[') {
      throw LogoFailure.at(open, `Po „${owner.text}” powinien być nawias „[” z poleceniami, a jest „${open.text}”.`);
    }
    this.pos++;
    this.bracketDepth++;
    const body = this.parseList();
    this.bracketDepth--;
    const close = this.peek();
    if (!close) throw LogoFailure.at(open, 'Nawias „[” nie został zamknięty — brakuje „]”.');
    this.pos++;
    return { body, close };
  }

  /** Parses the expression argument of `owner`, reporting a missing one where it should start. */
  private parseArg(owner: Token): Arg {
    const token = this.peek();
    if (!token) throw LogoFailure.at(owner, `Po „${owner.text}” brakuje liczby.`);
    if (!this.canStartExpr(token)) {
      throw LogoFailure.at(token, `Po „${owner.text}” powinna być liczba, a jest „${token.text}”.`);
    }
    return { expr: this.parseExpr(owner), first: token };
  }

  /** Parses an integer argument; when it is written without names it is checked right away. */
  private parseIntegerArg(owner: Token, check: IntegerCheck): Arg {
    const arg = this.parseArg(owner);
    const value = constantValue(arg.expr);
    if (value !== undefined) check(value, arg.first);
    return arg;
  }

  private canStartExpr(token: Token): boolean {
    switch (token.type) {
      case 'num':
      case 'name':
      case '(':
        return true;
      case 'op':
        return token.text === '-' || token.text === '+';
      case 'word': {
        const keyword = keywordOf(token.norm);
        return keyword === undefined || keyword === 'repcount';
      }
      default:
        return false;
    }
  }

  /** `context` is the token after which the expression starts, used to report a missing operand. */
  private parseExpr(context: Token, minPrecedence = 1): Expr {
    let left = this.parseOperand(context);
    for (;;) {
      const token = this.peek();
      if (!token || token.type !== 'op') return left;
      // `np 10 -5` is `np 10` followed by a stray `-5`: the sign is not a binary operator.
      if (token.spaceBefore !== token.spaceAfter) return left;
      const op = token.text as BinaryOp;
      const precedence = PRECEDENCE[op];
      if (precedence < minPrecedence) return left;
      this.pos++;
      const right = this.parseExpr(token, precedence + 1);
      left = { kind: 'binary', op, left, right, token };
    }
  }

  private parseOperand(context: Token): Expr {
    // Signs are collected iteratively so that long chains like `- - - 2` cannot overflow the stack.
    const signs: Token[] = [];
    while (this.peek()?.type === 'op' && (this.peek()!.text === '-' || this.peek()!.text === '+')) {
      signs.push(this.next());
    }
    let expr = this.parsePrimary(signs.length > 0 ? signs[signs.length - 1] : context);
    for (let i = signs.length - 1; i >= 0; i--) {
      if (signs[i].text === '-') expr = { kind: 'negate', operand: expr, token: signs[i] };
    }
    return expr;
  }

  private parsePrimary(context: Token): Expr {
    const token = this.peek();
    if (!token) throw LogoFailure.at(context, `Po „${context.text}” brakuje liczby.`);
    if (!this.canStartExpr(token)) {
      throw LogoFailure.at(token, `Po „${context.text}” powinna być liczba, a jest „${token.text}”.`);
    }
    this.pos++;
    if (token.type === '(') {
      const inner = this.parseExpr(token);
      if (this.peek()?.type !== ')') throw LogoFailure.at(token, 'Nawias „(” nie został zamknięty.');
      this.pos++;
      return inner;
    }
    if (token.type === 'word' && keywordOf(token.norm) === 'repcount') {
      if (this.repeatDepth === 0) {
        throw LogoFailure.at(token, `„${token.text}” działa tylko wewnątrz nawiasów polecenia „powtórz”.`);
      }
      return { kind: 'repcount', token };
    }
    if (token.type === 'word' || token.type === 'name') {
      if (!this.knows(token.norm)) throw LogoFailure.at(token, `Nie znam nazwy „${token.text}”.`);
      return { kind: 'var', name: token.norm, token };
    }
    return { kind: 'num', value: token.value, token };
  }

  private parseColor(owner: Token): string {
    const token = this.peek();
    const example = 'np. kolor "#16866a"';
    if (!token) throw LogoFailure.at(owner, `Po „${owner.text}” brakuje koloru (${example}).`);
    if (token.type !== 'str') {
      throw LogoFailure.at(token, `Kolor zapisuje się w cudzysłowie jako # i sześć cyfr szesnastkowych (${example}).`);
    }
    const color = token.norm.slice(1, -1);
    if (!/^#[0-9a-f]{6}$/.test(color)) {
      throw LogoFailure.at(token, `${token.text} nie jest poprawnym kolorem. Podaj # i sześć cyfr szesnastkowych (${example}).`);
    }
    this.pos++;
    return color;
  }

  /** Reports a value standing where a command should be, quoting the whole value. */
  private strayValue(token: Token): LogoFailure {
    let text = token.text;
    try {
      this.parseExpr(token);
      text = this.source.slice(token.start, this.tokens[this.pos - 1].end);
    } catch {
      // The value itself is malformed; quoting its first token is enough.
    }
    let message = `„${text}” to wartość, a w tym miejscu powinno stać polecenie.`;
    if (token.type === 'op' && token.spaceBefore && !token.spaceAfter) {
      message += ` Jeśli to miało być działanie, postaw odstępy po obu stronach „${token.text}” albo po żadnej.`;
    }
    return LogoFailure.at(token, message);
  }

  private parseStatement(): Stmt {
    const token = this.next();
    if (token.type !== 'word' && this.canStartExpr(token)) {
      this.pos--;
      throw this.strayValue(token);
    }
    if (token.type === ')') throw LogoFailure.at(token, 'Nawias „)” nie ma pary — brakuje otwierającego „(”.');
    if (token.type === '[') {
      throw LogoFailure.at(token, 'Nawias „[” może stać tylko po poleceniu, np. „powtórz 4 [ … ]”.');
    }
    switch (keywordOf(token.norm)) {
      case 'forward':
        return { kind: 'move', sign: 1, arg: this.parseArg(token), token };
      case 'back':
        return { kind: 'move', sign: -1, arg: this.parseArg(token), token };
      case 'right':
        return { kind: 'turn', axis: 'yaw', sign: 1, arg: this.parseArg(token), token };
      case 'left':
        return { kind: 'turn', axis: 'yaw', sign: -1, arg: this.parseArg(token), token };
      case 'pitchup':
      case 'pitchdown':
      case 'rollright':
      case 'rollleft':
        if (this.structure.mode === '2d') {
          throw LogoFailure.at(token, `Polecenie „${token.text}” działa tylko w trybie 3D. Przełącz tryb na 3D, aby obracać żółwia w przestrzeni.`);
        }
        break;
    }
    switch (keywordOf(token.norm)) {
      case 'pitchup':
        return { kind: 'turn', axis: 'pitch', sign: 1, arg: this.parseArg(token), token };
      case 'pitchdown':
        return { kind: 'turn', axis: 'pitch', sign: -1, arg: this.parseArg(token), token };
      case 'rollright':
        return { kind: 'turn', axis: 'roll', sign: 1, arg: this.parseArg(token), token };
      case 'rollleft':
        return { kind: 'turn', axis: 'roll', sign: -1, arg: this.parseArg(token), token };
      case 'penup':
        return { kind: 'pen', down: false, token };
      case 'pendown':
        return { kind: 'pen', down: true, token };
      case 'stop':
        return { kind: 'stop', token };
      case 'home':
        return { kind: 'home', token };
      case 'clear':
        return { kind: 'clear', token };
      case 'to':
        if (this.scope.proc) {
          throw LogoFailure.at(token, `Nie można definiować procedury wewnątrz innej procedury („${this.scope.proc.title}”).`);
        }
        throw LogoFailure.at(token, `Definicja procedury musi zaczynać się od „${token.text}” na początku wiersza.`);
      case 'end':
        if (token.lineStart && token.lineEnd) {
          throw LogoFailure.at(token, `„${token.text}” kończy definicję procedury, ale żadna nie została tu rozpoczęta słowem „oto”.`);
        }
        throw LogoFailure.at(token, `„${token.text}” musi stać sam w osobnym wierszu, aby zakończyć procedurę.`);
      case 'color':
        return { kind: 'color', color: this.parseColor(token), token };
      case 'width':
        return { kind: 'width', arg: this.parseIntegerArg(token, checkWidth), token };
      case 'let': {
        const target = this.peek();
        if (!target) throw LogoFailure.at(token, `Po „${token.text}” brakuje nazwy zmiennej, np. „niech bok 50”.`);
        if ((target.type !== 'word' && target.type !== 'name') || keywordOf(target.norm)) {
          throw LogoFailure.at(target, `Po „${token.text}” powinna być nazwa zmiennej, a jest „${target.text}”.`);
        }
        this.pos++;
        return { kind: 'let', name: target.norm, arg: this.parseArg(target), token };
      }
      case 'if': {
        const cond = this.parseCondition(token);
        return { kind: 'if', cond, then: this.parseBody(token), otherwise: null, token };
      }
      case 'ifelse': {
        const cond = this.parseCondition(token);
        const then = this.parseBody(token);
        return { kind: 'if', cond, then, otherwise: this.parseBody(token), token };
      }
      case 'repeat': {
        const count = this.parseIntegerArg(token, checkRepeatCount);
        this.repeatDepth++;
        const { body, close } = this.parseBody(token);
        this.repeatDepth--;
        return { kind: 'repeat', count, body, token, close };
      }
    }
    const proc = this.structure.procedures.get(token.norm);
    if (proc) return { kind: 'call', proc, args: this.parseCallArgs(token, proc), token };
    throw LogoFailure.at(token, `Nie znam polecenia „${token.text}”.`);
  }

  private parseCallArgs(token: Token, proc: Procedure): Arg[] {
    const args: Arg[] = [];
    for (const _ of proc.params) {
      const next = this.peek();
      if (!next || !this.canStartExpr(next)) {
        const count = proc.params.length;
        const message =
          `Procedura „${proc.title}” potrzebuje ${count} ${count === 1 ? 'argumentu' : 'argumentów'} ` +
          `(${proc.params.join(', ')}), a podano ${args.length}.`;
        throw LogoFailure.at(next ?? token, message);
      }
      args.push(this.parseArg(token));
    }
    return args;
  }
}

export type CompileResult = { program: Program; error: null } | { program: null; error: LogoFailure };

export function compile(source: string, mode: Mode): CompileResult {
  try {
    const tokens = tokenize(source);
    const struct = structure(tokens, mode);
    const scope: Scope = { proc: null, locals: new Set(), globals: assignedNames(struct.top) };
    const body = new Parser(source, struct.top, struct, scope).parseUnit();
    return { program: { body, procedures: [...struct.procedures.values()] }, error: null };
  } catch (e) {
    if (e instanceof LogoFailure) return { program: null, error: e };
    throw e;
  }
}

