import { describe, expect, test } from 'bun:test';
import { run } from '../src/lang';

const outcome = (source: string, mode: '2d' | '3d' = '2d') => {
  const { segments, error } = run(source, mode);
  return { segments: segments.length, at: error && [error.line, error.column] };
};

describe('run-time argument checks', () => {
  test('widths and repeat counts computed from names are checked when executed, at the argument', () => {
    expect(outcome('niech g 13\nnp 1\ngrubosc g')).toEqual({ segments: 1, at: [3, 9] });
    expect(outcome('niech g 6\nnp 1\ngrubosc (g / 4)')).toEqual({ segments: 1, at: [3, 9] });
    expect(outcome('niech n 2.5\nnp 1\npowtorz n [np 1]')).toEqual({ segments: 1, at: [3, 9] });
    expect(outcome('niech n 10001\npowtorz n [np 1]')).toEqual({ segments: 0, at: [2, 9] });
    expect(outcome('powtorz 3 [powtorz nrpowt - 2 [np 1]]')).toEqual({ segments: 0, at: [1, 20] });
  });
});

describe('nesting limit', () => {
  test('brackets may nest 32 deep; the 33rd is a parse-time error at that bracket', () => {
    const nest = (n: number) => 'powtorz 1 ['.repeat(n) + 'np 1' + ']'.repeat(n);
    expect(outcome(nest(32))).toEqual({ segments: 1, at: null });
    expect(outcome(nest(33))).toEqual({ segments: 0, at: [1, 33 * 11] });
  });

  test('conditional bodies count toward the nesting depth', () => {
    const source = 'powtorz 1 ['.repeat(16) + 'jeśli 1 = 1 ['.repeat(17) + 'np 1' + ']'.repeat(33);
    expect(outcome(source)).toEqual({ segments: 0, at: [1, 16 * 11 + 17 * 13] });
  });
});

describe('coordinate limit', () => {
  test('coordinates may reach ±100,000 but not pass it, pen up or down', () => {
    expect(outcome('np 100000 ws 200000')).toEqual({ segments: 2, at: null });
    expect(outcome('np 50000\nnp 50000.5')).toEqual({ segments: 1, at: [2, 1] });
    expect(outcome('np 1\npw 90 pod np 100001')).toEqual({ segments: 1, at: [2, 11] });
    expect(outcome('gora 90 np 100000 np 1', '3d')).toEqual({ segments: 1, at: [1, 19] });
  });
});

describe('frame limit', () => {
  test('32 active procedure-call and repeat frames are allowed; the 33rd is an error at its call', () => {
    const countdown = 'oto f ma: n\n  jeśli n > 0 [f n - 1]\njuż\n';
    expect(outcome(countdown + 'f 31')).toEqual({ segments: 0, at: null }); // f(31) … f(0): 32 calls
    expect(outcome(countdown + 'f 32')).toEqual({ segments: 0, at: [2, 16] });
  });

  test('repeats are frames too, conditional bodies are not', () => {
    const nested = 'oto g ma: n\n  powtorz 1 [jeśli n > 0 [g n - 1]]\njuż\n';
    expect(outcome(nested + 'g 15')).toEqual({ segments: 0, at: null }); // 16 calls + 16 repeats
    expect(outcome(nested + 'np 5\ng 16')).toEqual({ segments: 1, at: [2, 27] }); // the 17th call is frame 33
  });
});

describe('operation limit', () => {
  // repeat (1) + 4999 × (pw + finishing the iteration) = 9999 operations.
  const turns = 'powtorz 4999 [pw 1]';

  test('10,000 operations run; the 10,001st is an error at its token and the drawing is kept', () => {
    expect(outcome(`${turns}\nnp 1`)).toEqual({ segments: 1, at: null });
    expect(outcome(`${turns}\nnp 1\nnp 1`)).toEqual({ segments: 1, at: [3, 1] });
  });

  test('finishing a repeat iteration counts and is reported at its closing bracket', () => {
    // repeat (1) + 5000 × pw = 5001, finishing iterations 1–4999 = 4999 → 10,000; finishing #5000 fails.
    expect(outcome('powtorz 5000 [pw 1]')).toEqual({ segments: 0, at: [1, 19] });
  });

  test('niech, conditionals, calls and finishing their bodies all count', () => {
    // 1 + 2499 × (jeśli + pw + end of body + end of iteration) = 9997, then 3 moves = 10,000.
    expect(outcome('powtorz 2499 [jeśli 1 = 1 [pw 1]]\nnp 1 np 1 np 1')).toEqual({ segments: 3, at: null });
    expect(outcome('powtorz 2499 [jeśli 1 = 1 [pw 1]]\nnp 1 np 1 np 1 np 1')).toEqual({ segments: 3, at: [2, 16] });
    // A false condition counts once: 1 + 3333 × (jeśli + niech + end of iteration) = 10,000.
    expect(outcome('powtorz 3333 [jeśli 1 = 2 [pw 1] niech a 1]')).toEqual({ segments: 0, at: null });
    expect(outcome('powtorz 3333 [jeśli 1 = 2 [pw 1] niech a 1]\nnp 1')).toEqual({ segments: 0, at: [2, 1] });
    // 1 + 3333 × (call + end of call + end of iteration) = 10,000.
    expect(outcome('oto f\njuż\npowtorz 3333 [f]')).toEqual({ segments: 0, at: null });
    expect(outcome('oto f\njuż\npowtorz 3333 [f]\nnp 1')).toEqual({ segments: 0, at: [4, 1] });
  });
});

