test('a literal width or count that divides by zero is reported as a division by zero', () => {
  for (const source of ['np 1 grubosc 6 / (3 - 3)', 'np 1 powtorz 1 / 0 [np 1]']) {
    const { segments, error } = run(source, '2d');
    expect({ segments, column: error?.column, zero: /zero/.test(error?.message ?? '') }).toEqual({
      segments: [],
      column: 14,
      zero: true,
    });
  }
