import { describe, expect, test } from 'bun:test';

// Bun runs on JavaScriptCore, whose stack is much deeper than V8's (Chrome, Edge, Node).
// These programs are valid within the 10,000-token limit, so the interpreter is also run under Node.
const node = Bun.which('node');

const programs = {
  parentheses: 'np ' + '('.repeat(4998) + '1' + ')'.repeat(4998),
  signs: 'np ' + '- '.repeat(9997) + '1',
  sums: 'np 1' + ' + 1'.repeat(4999),
  nestedSums: 'np ' + '(1 + '.repeat(2499) + '1' + ')'.repeat(2499),
};

describe.skipIf(!node)('deep expressions under V8', () => {
  test('deeply nested parentheses, long sign chains and long sums evaluate without overflowing the stack', async () => {
    const build = await Bun.build({ entrypoints: [`${import.meta.dir}/../src/lang/index.ts`], format: 'esm' });
    const bundle = await build.outputs[0].text();
    const script = `${bundle}\nconst programs = ${JSON.stringify(programs)};\n` +
      `const out = {};\nfor (const [k, src] of Object.entries(programs)) {\n` +
      `  try { const r = run(src, '2d'); out[k] = r.error ? r.error.message : r.segments[0].to[1]; }\n` +
      `  catch (e) { out[k] = 'threw ' + e.message; }\n}\nconsole.log(JSON.stringify(out));`;
    const proc = Bun.spawnSync([node!, '--input-type=module', '-'], { stdin: Buffer.from(script) });
    const output = JSON.parse(proc.stdout.toString());
    expect(output).toEqual({ parentheses: 1, signs: -1, sums: 5000, nestedSums: 2500 });
  });
});

