export interface TurtlePose {
  position: Vec3;
  heading: Vec3;
  right: Vec3;
  up: Vec3;
  penDown: boolean;
  color: string;
  width: number;
}

/** The outcome of executing one operation. */
export type Advance =
  | { kind: 'op'; line: number; column: number; finish: boolean }
  | { kind: 'done' }
  | { kind: 'error'; error: LogoError };

/** A program being executed one operation at a time. */
export interface Execution {
  /** Executes the next operation. After `done` or `error` it keeps returning the same outcome. */
  next(): Advance;
  /** The segments kept so far (a `czyść` replaces the array). */
  readonly segments: Segment[];
  readonly turtle: TurtlePose;
  readonly operations: number;
}

const zero = (v: number) => (v === 0 ? 0 : v);
const clean = (v: Vec3): Vec3 => [zero(v[0]), zero(v[1]), zero(v[2])];

function poseOf(machine: Machine): TurtlePose {
  const t = machine.turtle;
  const { heading, right, up } = t.orientation.vectors();
  return { position: clean(t.position), heading, right, up, penDown: t.penDown, color: t.color, width: t.width };
}

class RunningProgram implements Execution {
  private finished: Advance | null = null;

  constructor(
    private readonly machine: Machine,
    private readonly steps: Generator<Step, void>,
  ) {}

  next(): Advance {
    if (this.finished) return this.finished;
    try {
      const result = this.steps.next();
      if (!result.done) {
        const { token, finish } = result.value;
        return { kind: 'op', line: token.line, column: token.column, finish };
      }
      this.finished = { kind: 'done' };
    } catch (e) {
      if (!(e instanceof LogoFailure)) throw e;
      this.finished = { kind: 'error', error: e.toError() };
    }
    return this.finished;
  }

  get segments(): Segment[] {
    return this.machine.segments;
  }

  get turtle(): TurtlePose {
    return poseOf(this.machine);
  }

  get operations(): number {
    return this.machine.operations;
  }
}

