  const { program, error } = compile(source, mode);
  if (!program) return { execution: null, error: error.toError() };
  const machine = createMachine();
  return { execution: new RunningProgram(machine, execute(machine, program)), error: null };
}

const outward = (s: Segment): Segment => ({ from: clean(s.from), to: clean(s.to), color: s.color, width: s.width });

