import { start, type Execution, type LogoError, type Mode, type Segment, type TurtlePose } from '../lang';

/** Requests animation frames; `requestAnimationFrame` in the browser. */
export interface Scheduler {
  request(callback: (now: number) => void): number;
  cancel(handle: number): void;
}

export type RunState = 'idle' | 'running' | 'paused' | 'finished' | 'error';

export interface Snapshot {
  state: RunState;
  mode: Mode;
  segments: readonly Segment[];
  turtle: TurtlePose;
  /** Line of the command executed last while running or paused; null otherwise. */
  line: number | null;
  error: LogoError | null;
  operations: number;
  /** Increases whenever the drawing was cleared or replaced, so views can rebuild. */
  generation: number;
}

export interface Controller {
  /** Starts the program from scratch and animates it at the current speed. */
  run(source: string, mode: Mode): void;
  /** Executes one command; starts the program first unless it is paused part-way. */
  step(source: string, mode: Mode): void;
  pause(): void;
  resume(): void;
  /** Runs the rest of the program at once (starting it if needed). */
  finish(source: string, mode: Mode): void;
  /** Stops and clears the drawing. */
  reset(mode?: Mode): void;
  /** Stops the program where it is, keeping the drawing (e.g. after the code was edited). */
  stop(): void;
  setSpeed(level: number): void;
  readonly speed: number;
  snapshot(): Snapshot;
  subscribe(listener: (snapshot: Snapshot) => void): () => void;
}

export const HOME: TurtlePose = {
  position: [0, 0, 0],
  heading: [0, 1, 0],
  right: [1, 0, 0],
  up: [0, 0, 1],
  penDown: true,
  color: '#16866a',
  width: 3,
};

export function createController({ scheduler }: { scheduler: Scheduler }): Controller {
  let state: RunState = 'idle';
  let mode: Mode = '2d';
  let execution: Execution | null = null;
  let line: number | null = null;
  let error: LogoError | null = null;
  let generation = 0;
  let speed = 6;
  const listeners = new Set<(snapshot: Snapshot) => void>();

  const snapshot = (): Snapshot => ({
    state,
    mode,
    segments: execution?.segments ?? [],
    turtle: execution?.turtle ?? HOME,
    line,
    error,
    operations: execution?.operations ?? 0,
    generation,
  });
  const notify = () => {
    const s = snapshot();
    for (const listener of listeners) listener(s);
  };

  const begin = (source: string, m: Mode): boolean => {
    mode = m;
    generation++;
    line = null;
    const started = start(source, m);
    execution = started.execution;
    error = started.error;
    state = execution ? 'paused' : 'error';
    return execution !== null;
  };

  /** Executes operations up to and including the next command. */
  const advance = () => {
    if (!execution) return;
    for (;;) {
      const outcome = execution.next();
      if (outcome.kind === 'op') {
        if (outcome.finish) continue;
        line = outcome.line;
        return;
      }
      line = null;
      if (outcome.kind === 'error') {
        error = outcome.error;
        line = outcome.error.line;
        state = 'error';
      } else {
        state = 'finished';
      }
      return;
    }
  };

  const controller: Controller = {
    run(source, m) {
      begin(source, m);
      notify();
    },
    step(source, m) {
      if (state !== 'paused' || !execution) {
        if (!begin(source, m)) return notify();
