import { keywordOf, type Keyword } from './keywords';

export type HighlightKind =
  | 'command' // turtle commands: np, pw, kolor …
  | 'control' // powtórz, jeśli, oto, już, niech, stop
  | 'value' // nrpowt
  | 'number'
  | 'name'
  | 'procedure'
  | 'string'
  | 'comment'
  | 'bracket'
  | 'paren'
  | 'operator'
  | 'invalid';

export interface HighlightSpan {
  start: number;
  end: number;
  kind: HighlightKind;
}

const CONTROL = new Set<Keyword>(['repeat', 'let', 'if', 'ifelse', 'stop', 'to', 'end']);
const WORD_CHAR = /[\p{L}\p{M}\p{N}_]/u;
const QUOTE = /["„“”]/;

/** Splits source into coloured spans. Never fails: malformed text becomes `invalid`. */
export function highlight(source: string): HighlightSpan[] {
  const spans: HighlightSpan[] = [];
  const procedures = new Set<string>();
  for (const match of source.matchAll(/^[ \t]*(?:oto|to)[ \t]+([\p{L}_][\p{L}\p{M}\p{N}_]*)/gimu)) {
    procedures.add(match[1].normalize('NFC').toLowerCase());
  }
  let i = 0;
  const add = (start: number, kind: HighlightKind) => spans.push({ start, end: i, kind });
  while (i < source.length) {
    const ch = source[i];
    const start = i;
    if (/\s/.test(ch)) {
      i++;
    } else if (ch === ';') {
      while (i < source.length && source[i] !== '\n') i++;
      add(start, 'comment');
    } else if (ch === '[' || ch === ']') {
      i++;
      add(start, 'bracket');
    } else if (ch === '(' || ch === ')') {
      i++;
      add(start, 'paren');
    } else if ('+-*/<>=,'.includes(ch)) {
      i++;
      add(start, 'operator');
    } else if (QUOTE.test(ch)) {
      i++;
      while (i < source.length && !QUOTE.test(source[i]) && source[i] !== '\n') i++;
      if (QUOTE.test(source[i] ?? '')) i++;
      add(start, 'string');
    } else if (/[0-9.]/.test(ch)) {
      while (i < source.length && (WORD_CHAR.test(source[i]) || source[i] === '.')) i++;
      add(start, /^(\d+(\.\d+)?|\.\d+)$/.test(source.slice(start, i)) ? 'number' : 'invalid');
    } else if (WORD_CHAR.test(ch) || ch === ':') {
