import { highlight, type LogoError } from '../lang';
import { escapeHtml, h } from './dom';

export interface EditorError extends LogoError {
  /** `live` errors come from checking while typing; others from running the program. */
  live?: boolean;
}

export interface Editor {
  element: HTMLElement;
  textarea: HTMLTextAreaElement;
  get value(): string;
  /** Replaces the whole text, as if the user had selected all and pasted. */
  set value(text: string);
  setError(error: EditorError | null): void;
  /** Highlights the line being executed (1-based), or nothing. */
  setActiveLine(line: number | null): void;
  /** Moves the caret to a position and scrolls it into view. */
  reveal(line: number, column: number): void;
  setReadOnly(readOnly: boolean): void;
}

/** A plain textarea with a highlighted overlay, line numbers and an inline error marker. */
export function createEditor(options: { id: string; describedBy?: string; onInput: (text: string) => void }): Editor {
  const textarea = h('textarea', {
    id: options.id,
    class: 'editor-input',
    spellcheck: 'false',
    autocapitalize: 'off',
    autocomplete: 'off',
    autocorrect: 'off',
    wrap: 'off',
    'aria-label': 'Kod programu',
    'aria-describedby': options.describedBy,
    'data-gramm': 'false',
  });
  const code = h('code');
  const pre = h('pre', { class: 'editor-highlight', 'aria-hidden': 'true' }, code);
  const activeLine = h('div', { class: 'editor-active-line', hidden: true });
  const lines = h('div', { class: 'editor-lines' });
  const gutter = h('div', { class: 'editor-gutter', 'aria-hidden': 'true' }, lines);
  const layer = h('div', { class: 'editor-layer' }, activeLine, pre);
  const body = h('div', { class: 'editor-body' }, layer, textarea);
  const element = h('div', { class: 'editor' }, gutter, body);

  let error: EditorError | null = null;
  let active: number | null = null;
  let lineCount = 0;
  let escapePressed = false;

  const render = () => {
    const text = textarea.value;
    const errorLine = error?.line ?? -1;
    const offsets = lineOffsets(text);
    let errorStart = -1;
    let errorEnd = -1;
    if (error && error.line <= offsets.length) {
      errorStart = offsets[error.line - 1] + error.column - 1;
      const rest = text.slice(errorStart);
      const token = /^(\S+?)(?=[\s\[\]()]|$)|^[\s\S]/.exec(rest);
      errorEnd = errorStart + Math.max(1, token ? token[0].length : 1);
    }
    let html = '';
    let pos = 0;
    const plain = (end: number) => {
      if (end > pos) html += escapeHtml(text.slice(pos, end));
      pos = Math.max(pos, end);
    };
    for (const span of highlight(text)) {
      plain(span.start);
      let inner = escapeHtml(text.slice(span.start, span.end));
      let cls = `tok tok-${span.kind}`;
      if (span.start < errorEnd && span.end > errorStart) cls += ' tok-error';
      if (span.kind === 'string' && /^.#[0-9a-f]{6}.$/i.test(text.slice(span.start, span.end))) {
        inner = `<span class="tok-swatch" style="--swatch:${text.slice(span.start + 1, span.end - 1)}">${inner}</span>`;
      }
      html += `<span class="${cls}">${inner}</span>`;
      pos = span.end;
    }
    plain(text.length);
    if (error && errorStart >= 0 && !hasSpanAt(text, errorStart)) {
      // The error sits on whitespace or past the end of the line: mark the spot itself.
      html = insertMarker(html, text, errorStart);
    }
    if (error) html = appendLens(html, errorLine, error.message, !!error.live);
    code.innerHTML = html + '\n ';

    const count = offsets.length;
    if (count !== lineCount || lines.dataset.error !== String(errorLine)) {
      lineCount = count;
      lines.dataset.error = String(errorLine);
      lines.innerHTML = Array.from({ length: count }, (_, i) =>
        `<span class="editor-line-number${i + 1 === errorLine ? ' has-error' : ''}">${i + 1}</span>`,
      ).join('');
    }
    updateActiveLine();
  };

  const updateActiveLine = () => {
    activeLine.hidden = active === null;
    if (active !== null) activeLine.style.setProperty('--line', String(active - 1));
  };

  const syncScroll = () => {
    layer.style.transform = `translate(${-textarea.scrollLeft}px, ${-textarea.scrollTop}px)`;
    lines.style.transform = `translateY(${-textarea.scrollTop}px)`;
  };

  const insert = (text: string) => {
    textarea.focus();
    // execCommand keeps the browser's undo history; setRangeText is the fallback.
    const ok = typeof document.execCommand === 'function' && document.execCommand('insertText', false, text);
    if (!ok) {
      textarea.setRangeText(text, textarea.selectionStart, textarea.selectionEnd, 'end');
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
    }
  };

  textarea.addEventListener('input', () => {
    render();
    options.onInput(textarea.value);
  });
  textarea.addEventListener('scroll', syncScroll);
  textarea.addEventListener('keydown', (event) => {
    const wasEscape = escapePressed;
    escapePressed = event.key === 'Escape';
    if (event.key === 'Tab' && !event.ctrlKey && !event.altKey && !event.metaKey && !wasEscape) {
      // Tab indents; Escape followed by Tab leaves the editor, so the keyboard is never trapped.
      event.preventDefault();
      if (event.shiftKey) outdent(textarea);
      else insert('  ');
    } else if (event.key === 'Enter' && !event.ctrlKey && !event.metaKey && !event.shiftKey && !event.altKey) {
      const before = textarea.value.slice(0, textarea.selectionStart);
      const indent = /[ \t]*/.exec(before.slice(before.lastIndexOf('\n') + 1))![0];
      const opens = /\[\s*$/.test(before) ? '  ' : '';
      if (indent || opens) {
        event.preventDefault();
        insert('\n' + indent + opens);
      }
    }
  });

  render();

  return {
    element,
    textarea,
    get value() {
      return textarea.value;
    },
    set value(text: string) {
      textarea.value = text;
      textarea.scrollTop = 0;
      textarea.scrollLeft = 0;
      syncScroll();
      render();
    },
    setError(next) {
      error = next;
      render();
    },
    setActiveLine(line) {
      if (line === active) return;
      active = line;
      updateActiveLine();
    },
    reveal(line, column) {
      const offsets = lineOffsets(textarea.value);
      const at = (offsets[line - 1] ?? textarea.value.length) + column - 1;
      textarea.focus();
      textarea.setSelectionRange(at, at);
      const lineHeight = parseFloat(getComputedStyle(textarea).lineHeight) || 22;
      const top = (line - 1) * lineHeight;
      if (top < textarea.scrollTop || top > textarea.scrollTop + textarea.clientHeight - lineHeight * 2) {
        textarea.scrollTop = Math.max(0, top - textarea.clientHeight / 3);
      }
      syncScroll();
    },
    setReadOnly(readOnly) {
      textarea.readOnly = readOnly;
    },
  };
}

function lineOffsets(text: string): number[] {
  const offsets = [0];
  for (let i = 0; i < text.length; i++) if (text[i] === '\n') offsets.push(i + 1);
  return offsets;
}

function hasSpanAt(text: string, offset: number): boolean {
  return offset < text.length && !/\s/.test(text[offset]);
}

/** Inserts an error marker at a source offset into highlighted HTML (only for whitespace spots). */
function insertMarker(html: string, text: string, offset: number): string {
  // Map the source offset to an HTML position by walking the visible characters.
  let visible = 0;
  for (let i = 0; i < html.length; i++) {
    if (visible === offset) return html.slice(0, i) + '<span class="tok-error-spot"></span>' + html.slice(i);
    const c = html[i];
    if (c === '<') {
      i = html.indexOf('>', i);
      continue;
    }
    if (c === '&') i = html.indexOf(';', i);
    visible++;
  }
  return offset >= text.length ? html + '<span class="tok-error-spot"></span>' : html;
}

/** Appends the error message at the end of its line, without moving any code. */
function appendLens(html: string, line: number, message: string, live: boolean): string {
  let current = 1;
  let depth = 0;
  for (let i = 0; i < html.length; i++) {
    const c = html[i];
    if (c === '<') {
      depth += html[i + 1] === '/' ? -1 : 1;
      i = html.indexOf('>', i);
      continue;
    }
    if (c === '\n') {
      if (current === line && depth === 0) return html.slice(0, i) + lens(message, live) + html.slice(i);
      current++;
    }
  }
  return html + lens(message, live);
}

function lens(message: string, live: boolean): string {
  return `<span class="error-lens${live ? ' is-live' : ''}" role="presentation">${escapeHtml(message)}</span>`;
}

function outdent(textarea: HTMLTextAreaElement): void {
  const { value, selectionStart } = textarea;
  const lineStart = value.lastIndexOf('\n', selectionStart - 1) + 1;
  const spaces = /^ {1,2}/.exec(value.slice(lineStart))?.[0].length ?? 0;
  if (!spaces) return;
  textarea.setSelectionRange(lineStart, lineStart + spaces);
  textarea.setRangeText('', lineStart, lineStart + spaces, 'start');
  textarea.setSelectionRange(Math.max(lineStart, selectionStart - spaces), Math.max(lineStart, selectionStart - spaces));
  textarea.dispatchEvent(new Event('input', { bubbles: true }));
}

