import type { Segment, TurtlePose, Vec3 } from '../lang';

/** What a view draws. */
export interface Scene {
  segments: readonly Segment[];
  turtle: TurtlePose;
  /** A faint target drawing shown behind the program's own (challenges). */
  ghost: readonly Segment[];
  showTurtle: boolean;
}

/** Colours a view reads from the page's CSS custom properties. */
export interface Palette {
  background: string;
  grid: string;
  gridMajor: string;
  axis: string;
  axisX: string;
  axisY: string;
  axisZ: string;
  ink: string;
  muted: string;
  ghost: string;
  turtleOutline: string;
}

export function readPalette(el: Element): Palette {
  const style = getComputedStyle(el);
  const v = (name: string, fallback: string) => style.getPropertyValue(name).trim() || fallback;
  return {
    background: v('--canvas-bg', '#fbf8f1'),
    grid: v('--canvas-grid', '#ebe5d8'),
    gridMajor: v('--canvas-grid-major', '#d9d1c0'),
    axis: v('--canvas-axis', '#9a917f'),
    axisX: v('--canvas-axis-x', '#c4503d'),
    axisY: v('--canvas-axis-y', '#3c8f4f'),
    axisZ: v('--canvas-axis-z', '#3a6fc4'),
    ink: v('--ink', '#1f2a2a'),
    muted: v('--ink-muted', '#5d6866'),
    ghost: v('--canvas-ghost', 'rgba(193, 118, 61, 0.35)'),
    turtleOutline: v('--canvas-turtle-outline', '#1f2a2a'),
  };
}

export interface Bounds {
  min: Vec3;
  max: Vec3;
}

/** Bounds of the segments and the turtle; null when there is nothing to frame. */
export function boundsOf(segments: readonly Segment[], extra: Vec3[] = []): Bounds | null {
  if (segments.length === 0 && extra.length === 0) return null;
  const min: Vec3 = [Infinity, Infinity, Infinity];
  const max: Vec3 = [-Infinity, -Infinity, -Infinity];
  const add = (p: Vec3) => {
    for (let i = 0; i < 3; i++) {
      if (p[i] < min[i]) min[i] = p[i];
      if (p[i] > max[i]) max[i] = p[i];
    }
  };
  for (const s of segments) {
    add(s.from);
    add(s.to);
  }
  extra.forEach(add);
  return { min, max };
}

/** A "nice" grid step (1, 2 or 5 × 10ⁿ) of at least `raw`. */
export function niceStep(raw: number): number {
  const exp = Math.pow(10, Math.floor(Math.log10(Math.max(raw, 1e-9))));
  for (const m of [1, 2, 5, 10]) if (m * exp >= raw) return m * exp;
  return 10 * exp;
}

/** Mixes a #rrggbb colour toward another by t (0–1). */
export function mix(a: string, b: string, t: number): string {
  const pa = parseHex(a);
  const pb = parseHex(b);
  if (!pa || !pb) return a;
  const c = pa.map((v, i) => Math.round(v + (pb[i] - v) * t));
  return `rgb(${c[0]}, ${c[1]}, ${c[2]})`;
}

function parseHex(color: string): number[] | null {
  const m = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(color.trim());
  return m ? [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16)] : null;
}

export const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
export const add = (a: Vec3, b: Vec3): Vec3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
export const scale = (a: Vec3, k: number): Vec3 => [a[0] * k, a[1] * k, a[2] * k];
export const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
export const cross = (a: Vec3, b: Vec3): Vec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
export const length = (a: Vec3) => Math.hypot(a[0], a[1], a[2]);
export const normalize = (a: Vec3): Vec3 => {
  const l = length(a);
  return l === 0 ? [0, 0, 0] : scale(a, 1 / l);
};

