import type { Segment, TurtlePose } from '../lang';
import { boundsOf, niceStep, type Palette, type Scene } from './scene';

/** A flat camera: the world point at the centre of the canvas and pixels per unit. */
export interface Camera2D {
  cx: number;
  cy: number;
  scale: number;
}

export const DEFAULT_CAMERA_2D: Camera2D = { cx: 0, cy: 0, scale: 1.4 };
const MIN_SCALE = 0.002;
const MAX_SCALE = 400;

export const clampScale = (s: number) => Math.min(MAX_SCALE, Math.max(MIN_SCALE, s));

export function toScreen2D(cam: Camera2D, w: number, h: number, x: number, y: number): [number, number] {
  return [w / 2 + (x - cam.cx) * cam.scale, h / 2 - (y - cam.cy) * cam.scale];
}

export function toWorld2D(cam: Camera2D, w: number, h: number, sx: number, sy: number): [number, number] {
  return [cam.cx + (sx - w / 2) / cam.scale, cam.cy - (sy - h / 2) / cam.scale];
}

/** Frames the drawing (and the turtle) with a margin. */
export function fit2D(scene: Scene, w: number, h: number): Camera2D {
  const b = boundsOf(scene.segments.length ? scene.segments : scene.ghost, [scene.turtle.position]);
  if (!b) return { ...DEFAULT_CAMERA_2D };
  const bw = Math.max(b.max[0] - b.min[0], 1);
  const bh = Math.max(b.max[1] - b.min[1], 1);
  const margin = Math.min(64, Math.min(w, h) * 0.12);
  const scale = clampScale(Math.min((w - margin * 2) / bw, (h - margin * 2) / bh, 8));
  return { cx: (b.min[0] + b.max[0]) / 2, cy: (b.min[1] + b.max[1]) / 2, scale };
}

export function zoom2D(cam: Camera2D, w: number, h: number, factor: number, sx = w / 2, sy = h / 2): Camera2D {
  const [wx, wy] = toWorld2D(cam, w, h, sx, sy);
  const scale = clampScale(cam.scale * factor);
  // Keep the world point under the cursor where it is.
  return { scale, cx: wx - (sx - w / 2) / scale, cy: wy + (sy - h / 2) / scale };
}

export function render2D(
  ctx: CanvasRenderingContext2D,
  scene: Scene,
  cam: Camera2D,
  w: number,
  h: number,
  p: Palette,
): void {
  ctx.fillStyle = p.background;
  ctx.fillRect(0, 0, w, h);
  drawGrid(ctx, cam, w, h, p);
  if (scene.ghost.length) drawSegments(ctx, scene.ghost, cam, w, h, p.ghost, 7, [10, 8]);
  drawSegments(ctx, scene.segments, cam, w, h);
  if (scene.showTurtle) drawTurtle(ctx, scene.turtle, cam, w, h, p);
}

function drawGrid(ctx: CanvasRenderingContext2D, cam: Camera2D, w: number, h: number, p: Palette): void {
  const step = niceStep(22 / cam.scale);
  const major = step * 5;
  const [x0, y1] = toWorld2D(cam, w, h, 0, 0);
  const [x1, y0] = toWorld2D(cam, w, h, w, h);
  ctx.lineWidth = 1;
  for (const [spacing, color] of [
    [step, p.grid],
    [major, p.gridMajor],
  ] as const) {
    ctx.beginPath();
    for (let x = Math.ceil(x0 / spacing) * spacing; x <= x1; x += spacing) {
      const sx = Math.round(toScreen2D(cam, w, h, x, 0)[0]) + 0.5;
      ctx.moveTo(sx, 0);
      ctx.lineTo(sx, h);
    }
    for (let y = Math.ceil(y0 / spacing) * spacing; y <= y1; y += spacing) {
      const sy = Math.round(toScreen2D(cam, w, h, 0, y)[1]) + 0.5;
      ctx.moveTo(0, sy);
      ctx.lineTo(w, sy);
    }
    ctx.strokeStyle = color;
    ctx.stroke();
  }
  // Axes through the origin, with labels toward the positive ends.
  const [ox, oy] = toScreen2D(cam, w, h, 0, 0);
  ctx.lineWidth = 1.5;
  ctx.strokeStyle = p.axisX;
  ctx.beginPath();
  ctx.moveTo(0, Math.round(oy) + 0.5);
  ctx.lineTo(w, Math.round(oy) + 0.5);
  ctx.stroke();
  ctx.strokeStyle = p.axisY;
  ctx.beginPath();
  ctx.moveTo(Math.round(ox) + 0.5, 0);
  ctx.lineTo(Math.round(ox) + 0.5, h);
  ctx.stroke();
  ctx.font = '600 12px system-ui, sans-serif';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = p.axisX;
  ctx.textAlign = 'right';
  if (oy > 8 && oy < h - 8) ctx.fillText('x', w - 8, oy - 10);
  ctx.fillStyle = p.axisY;
  ctx.textAlign = 'left';
  if (ox > 8 && ox < w - 8) ctx.fillText('y', ox + 8, 12);
  // The origin.
  if (ox > -10 && ox < w + 10 && oy > -10 && oy < h + 10) {
    ctx.fillStyle = p.background;
    ctx.strokeStyle = p.axis;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(ox, oy, 4.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = p.muted;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = '11px system-ui, sans-serif';
    ctx.fillText('0', ox + 6, oy + 5);
  }
}

/** Strokes segments, batching runs of the same style into one path. */
function drawSegments(
  ctx: CanvasRenderingContext2D,
  segments: readonly Segment[],
  cam: Camera2D,
  w: number,
  h: number,
  color?: string,
  width?: number,
  dash?: number[],
): void {
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.setLineDash(dash ?? []);
  let i = 0;
  while (i < segments.length) {
    const style = segments[i];
    ctx.beginPath();
    let last: [number, number] | null = null;
    for (; i < segments.length && segments[i].color === style.color && segments[i].width === style.width; i++) {
      const s = segments[i];
      const a = toScreen2D(cam, w, h, s.from[0], s.from[1]);
      const b = toScreen2D(cam, w, h, s.to[0], s.to[1]);
      if (!last || Math.abs(last[0] - a[0]) > 0.01 || Math.abs(last[1] - a[1]) > 0.01) ctx.moveTo(a[0], a[1]);
      ctx.lineTo(b[0], b[1]);
      last = b;
    }
    ctx.strokeStyle = color ?? style.color;
    ctx.lineWidth = width ?? style.width;
    ctx.stroke();
  }
  ctx.setLineDash([]);
}

/** A little turtle seen from above: shell in the pen colour (hollow when the pen is up). */
export function drawTurtle(
  ctx: CanvasRenderingContext2D,
  turtle: TurtlePose,
  cam: Camera2D,
  w: number,
  h: number,
  p: Palette,
): void {
  const [x, y] = toScreen2D(cam, w, h, turtle.position[0], turtle.position[1]);
  const angle = Math.atan2(turtle.heading[0], turtle.heading[1]);
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.lineWidth = 1.6;
  ctx.strokeStyle = p.turtleOutline;
  // Legs and head.
  ctx.fillStyle = turtle.color;
  for (const [lx, ly] of [
    [-8, -6],
    [8, -6],
    [-7, 7],
    [7, 7],
  ]) {
    ctx.beginPath();
    ctx.ellipse(lx, ly, 3.2, 2.4, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.ellipse(0, -13, 3.6, 4.2, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
  // Shell.
  ctx.beginPath();
  ctx.ellipse(0, 0, 8, 10, 0, 0, Math.PI * 2);
  ctx.fillStyle = turtle.penDown ? turtle.color : p.background;
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, -6);
  ctx.lineTo(4.5, -1);
  ctx.lineTo(3, 5);
  ctx.lineTo(-3, 5);
  ctx.lineTo(-4.5, -1);
  ctx.closePath();
  ctx.globalAlpha = 0.35;
  ctx.stroke();
  ctx.restore();
}

