const MAX_PITCH = (89 * Math.PI) / 180;
export const DEFAULT_CAMERA_3D: Camera3D = {
  target: [0, 0, 30],
  yaw: (-62 * Math.PI) / 180,
  pitch: (24 * Math.PI) / 180,
  distance: 420,
};

export function clampPitch(p: number): number {
  return Math.max(-MAX_PITCH, Math.min(MAX_PITCH, p));
}

export function clampDistance(d: number): number {
  return Math.max(1, Math.min(2_000_000, d));
}

interface Projector {
  eye: Vec3;
  right: Vec3;
  up: Vec3;
  forward: Vec3;
  focal: number;
  near: number;
  w: number;
  h: number;
}

export function projector(cam: Camera3D, w: number, h: number): Projector {
  const dir: Vec3 = [
    Math.cos(cam.pitch) * Math.cos(cam.yaw),
    Math.cos(cam.pitch) * Math.sin(cam.yaw),
    Math.sin(cam.pitch),
  ];
  const eye = add(cam.target, scale(dir, cam.distance));
  const forward = scale(dir, -1);
  let right = cross(forward, [0, 0, 1]);
  right = Math.hypot(...right) < 1e-6 ? [1, 0, 0] : normalize(right);
  const up = cross(right, forward);
  return { eye, right, up, forward, focal: h / 2 / Math.tan(FOV / 2), near: Math.max(0.05, cam.distance * 0.002), w, h };
}

/** Camera-space coordinates: x right, y up, z depth in front of the eye. */
function toView(p: Projector, v: Vec3): Vec3 {
  const d = sub(v, p.eye);
  return [dot(d, p.right), dot(d, p.up), dot(d, p.forward)];
}

function toScreen(p: Projector, c: Vec3): [number, number] {
  return [p.w / 2 + (c[0] / c[2]) * p.focal, p.h / 2 - (c[1] / c[2]) * p.focal];
}

/** Projects a segment, clipping it at the near plane; null when it is entirely behind. */
function projectSegment(p: Projector, a: Vec3, b: Vec3): { a: [number, number]; b: [number, number]; depth: number } | null {
  let ca = toView(p, a);
  let cb = toView(p, b);
  if (ca[2] < p.near && cb[2] < p.near) return null;
  if (ca[2] < p.near || cb[2] < p.near) {
    const t = (p.near - ca[2]) / (cb[2] - ca[2]);
    const cut: Vec3 = [ca[0] + (cb[0] - ca[0]) * t, ca[1] + (cb[1] - ca[1]) * t, p.near];
    if (ca[2] < p.near) ca = cut;
    else cb = cut;
  }
  return { a: toScreen(p, ca), b: toScreen(p, cb), depth: (ca[2] + cb[2]) / 2 };
}

/** Frames the drawing from the current direction (or the default one). */
export function fit3D(scene: Scene, w: number, h: number, from: Camera3D = DEFAULT_CAMERA_3D): Camera3D {
  const b = boundsOf(scene.segments.length ? scene.segments : scene.ghost, [scene.turtle.position]);
  if (!b || (scene.segments.length === 0 && scene.ghost.length === 0)) {
    return { ...from, target: [0, 0, 0], distance: DEFAULT_CAMERA_3D.distance };
  }
  const center: Vec3 = [(b.min[0] + b.max[0]) / 2, (b.min[1] + b.max[1]) / 2, (b.min[2] + b.max[2]) / 2];
  const radius = Math.max(Math.hypot(b.max[0] - b.min[0], b.max[1] - b.min[1], b.max[2] - b.min[2]) / 2, 10);
  const aspect = w > 0 && h > 0 ? w / h : 1.5;
  const half = Math.min(FOV / 2, Math.atan(Math.tan(FOV / 2) * aspect));
  return { ...from, target: center, distance: clampDistance((radius / Math.sin(half)) * 1.08) };
}

export function render3D(
  ctx: CanvasRenderingContext2D,
  scene: Scene,
  cam: Camera3D,
  w: number,
  h: number,
  pal: Palette,
): void {
  const p = projector(cam, w, h);
  ctx.fillStyle = pal.background;
  ctx.fillRect(0, 0, w, h);
  drawGround(ctx, p, cam, scene, pal);
  if (scene.ghost.length) drawLines(ctx, p, cam, scene.ghost, pal, pal.ghost, 6);
  drawLines(ctx, p, cam, scene.segments, pal);
  if (scene.showTurtle) drawDart(ctx, p, scene.turtle, cam, pal);
}

function drawGround(ctx: CanvasRenderingContext2D, p: Projector, cam: Camera3D, scene: Scene, pal: Palette): void {
  const b = boundsOf(scene.segments);
  const step = niceStep(cam.distance / 14);
  const reach = Math.max(
    step * 10,
    b ? Math.max(Math.abs(b.min[0]), Math.abs(b.max[0]), Math.abs(b.min[1]), Math.abs(b.max[1])) + step * 2 : 0,
  );
  const n = Math.min(80, Math.ceil(reach / step));
  const extent = n * step;
  ctx.lineWidth = 1;
  for (let i = -n; i <= n; i++) {
    const v = i * step;
    const major = i % 5 === 0;
    ctx.strokeStyle = major ? pal.gridMajor : pal.grid;
    for (const [a, c] of [
      [[v, -extent, 0], [v, extent, 0]],
      [[-extent, v, 0], [extent, v, 0]],
    ] as [Vec3, Vec3][]) {
      if (v === 0) continue;
      const s = projectSegment(p, a, c);
      if (!s) continue;
      ctx.beginPath();
      ctx.moveTo(s.a[0], s.a[1]);
      ctx.lineTo(s.b[0], s.b[1]);
      ctx.stroke();
    }
  }
  // Axes from the origin: X red, Y green, Z blue.
  const length = step * 4;
  const axes: [Vec3, string, string][] = [
    [[length, 0, 0], pal.axisX, 'x'],
    [[0, length, 0], pal.axisY, 'y'],
    [[0, 0, length], pal.axisZ, 'z'],
  ];
  ctx.font = '600 12px system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (const [end, color, label] of axes) {
    const neg = projectSegment(p, scale(end, -1 * (extent / length)), [0, 0, 0]);
    if (neg && label !== 'z') {
      ctx.strokeStyle = mix(color, pal.background, 0.55);
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(neg.a[0], neg.a[1]);
      ctx.lineTo(neg.b[0], neg.b[1]);
      ctx.stroke();
    }
    const pos = projectSegment(p, [0, 0, 0], label === 'z' ? end : scale(end, extent / length));
    if (!pos) continue;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(pos.a[0], pos.a[1]);
    ctx.lineTo(pos.b[0], pos.b[1]);
    ctx.stroke();
    const tip = projectSegment(p, [0, 0, 0], scale(end, 1.12));
    if (tip) {
      ctx.fillStyle = color;
      ctx.fillText(label, tip.b[0], tip.b[1]);
    }
  }
  const o = projectSegment(p, [0, 0, 0], [0, 0, 0]);
  if (o) {
    ctx.fillStyle = pal.background;
    ctx.strokeStyle = pal.axis;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(o.a[0], o.a[1], 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }
}

/** Draws segments far to near, thicker when close, slightly faded with distance. */
function drawLines(
  ctx: CanvasRenderingContext2D,
  p: Projector,
  cam: Camera3D,
  segments: readonly Segment[],
  pal: Palette,
  color?: string,
  width?: number,
): void {
  const projected: { a: [number, number]; b: [number, number]; depth: number; s: Segment }[] = [];
  let near = Infinity;
  let far = 0;
  for (const s of segments) {
    const pr = projectSegment(p, s.from, s.to);
    if (!pr) continue;
    projected.push({ ...pr, s });
    near = Math.min(near, pr.depth);
    far = Math.max(far, pr.depth);
  }
  projected.sort((x, y) => y.depth - x.depth);
  const range = Math.max(far - near, 1e-6);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  if (color) ctx.setLineDash([8, 7]);
  for (const { a, b, depth, s } of projected) {
    const perspective = Math.min(2.6, Math.max(0.45, cam.distance / depth));
    ctx.lineWidth = (width ?? s.width) * perspective;
    ctx.strokeStyle = color ?? mix(s.color, pal.background, ((depth - near) / range) * 0.3);
    ctx.beginPath();
    ctx.moveTo(a[0], a[1]);
    ctx.lineTo(b[0], b[1]);
    ctx.stroke();
  }
  ctx.setLineDash([]);
}

/** The turtle as a small dart: a body along heading/right and a fin along up, so roll shows. */
function drawDart(ctx: CanvasRenderingContext2D, p: Projector, t: TurtlePose, cam: Camera3D, pal: Palette): void {
  const size = cam.distance * 0.045;
  const at = (fwd: number, right: number, up: number): Vec3 =>
    add(t.position, add(scale(t.heading, fwd * size), add(scale(t.right, right * size), scale(t.up, up * size))));
  const faces: { points: Vec3[]; fill: string }[] = [
    { points: [at(1, 0, 0), at(-0.6, 0.62, 0), at(-0.3, 0, 0), at(-0.6, -0.62, 0)], fill: t.penDown ? t.color : pal.background },
    { points: [at(0.6, 0, 0), at(-0.55, 0, 0.55), at(-0.3, 0, 0)], fill: mix(t.color, '#ffffff', 0.35) },
  ];
  ctx.lineWidth = 1.5;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = pal.turtleOutline;
  const depthOf = (pts: Vec3[]) => pts.reduce((sum, v) => sum + toView(p, v)[2], 0) / pts.length;
  faces.sort((a, b) => depthOf(b.points) - depthOf(a.points));
  for (const face of faces) {
    const view = face.points.map((v) => toView(p, v));
    if (view.some((c) => c[2] < p.near)) continue;
    ctx.beginPath();
    view.forEach((c, i) => {
      const [x, y] = toScreen(p, c);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.closePath();
    ctx.fillStyle = face.fill;
    ctx.fill();
    ctx.stroke();
  }
}

