import type { Mode } from '../lang';
import { h } from './dom';
import { readPalette, type Palette, type Scene } from './scene';
import { DEFAULT_CAMERA_2D, fit2D, render2D, zoom2D, type Camera2D } from './view2d';
import { clampDistance, clampPitch, DEFAULT_CAMERA_3D, fit3D, projector, render3D, type Camera3D } from './view3d';
import { HOME } from './controller';

export interface Surface {
  element: HTMLElement;
  canvas: HTMLCanvasElement;
  /** False when the browser cannot draw on a canvas; `reason` explains why. */
  readonly available: boolean;
  readonly reason: string | null;
  setMode(mode: Mode): void;
  setScene(scene: Scene): void;
  /** Frames the whole drawing. */
  fit(): void;
  /** Back to the default view: origin-centred in 2D, the default camera in 3D. */
  resetView(): void;
  zoom(factor: number): void;
  /** Draws now instead of on the next frame. */
  renderNow(): void;
  /** A PNG of the current view without the turtle. */
  toBlob(): Promise<Blob | null>;
  /** Re-reads theme colours. */
  refreshPalette(): void;
  destroy(): void;
}

const EMPTY_SCENE: Scene = { segments: [], ghost: [], turtle: HOME, showTurtle: true };

export function createSurface(options: { request: (cb: () => void) => void }): Surface {
  const canvas = h('canvas', {
    class: 'view-canvas',
    tabindex: '0',
    role: 'img',
    'aria-roledescription': 'rysunek',
  });
  const notice = h('p', { class: 'view-notice', hidden: true });
  const element = h('div', { class: 'view-stage' }, canvas, notice);
  const ctx = canvas.getContext('2d');
  const reason = ctx ? null : 'Ta przeglądarka nie potrafi rysować na elemencie canvas, więc rysunek nie może zostać wyświetlony.';
  if (reason) {
    notice.textContent = reason;
    notice.hidden = false;
  }

  let mode: Mode = '2d';
  let scene = EMPTY_SCENE;
  let cam2: Camera2D = { ...DEFAULT_CAMERA_2D };
  let cam3: Camera3D = { ...DEFAULT_CAMERA_3D };
  let width = 600;
  let height = 400;
  let dpr = 1;
  let palette: Palette | null = null;
  let pending = false;

  const draw = (target: CanvasRenderingContext2D, w: number, h: number, s: Scene) => {
    palette ??= readPalette(element);
    if (mode === '2d') render2D(target, s, cam2, w, h, palette);
    else render3D(target, s, cam3, w, h, palette);
  };

  const renderNow = () => {
    pending = false;
    if (!ctx) return;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    draw(ctx, width, height, scene);
  };

  const invalidate = () => {
    if (pending) return;
    pending = true;
    options.request(renderNow);
  };

  const resize = () => {
    const rect = element.getBoundingClientRect();
    const w = Math.round(rect.width) || 600;
    const h = Math.round(rect.height) || 400;
    const ratio = Math.min(window.devicePixelRatio || 1, 3);
    if (w === width && h === height && ratio === dpr && canvas.width > 0) return;
    width = w;
    height = h;
    dpr = ratio;
    canvas.width = Math.round(w * ratio);
    canvas.height = Math.round(h * ratio);
    renderNow();
  };
  const observer = typeof ResizeObserver === 'function' ? new ResizeObserver(resize) : null;
  observer?.observe(element);

  // Pointer interaction: one pointer pans (2D) or orbits (3D, pans with Shift or the right button);
  // two pointers pinch to zoom and pan.
  const pointers = new Map<number, { x: number; y: number }>();
  let dragButton = 0;
  const local = (e: PointerEvent | WheelEvent) => {
    const r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };
  const pan = (dx: number, dy: number) => {
    if (mode === '2d') {
      cam2 = { ...cam2, cx: cam2.cx - dx / cam2.scale, cy: cam2.cy + dy / cam2.scale };
    } else {
      const p = projector(cam3, width, height);
      const k = cam3.distance / p.focal;
      cam3 = {
        ...cam3,
        target: [
          cam3.target[0] - (p.right[0] * dx - p.up[0] * dy) * k,
          cam3.target[1] - (p.right[1] * dx - p.up[1] * dy) * k,
          cam3.target[2] - (p.right[2] * dx - p.up[2] * dy) * k,
        ],
      };
    }
    invalidate();
  };
  const orbit = (dx: number, dy: number) => {
    cam3 = { ...cam3, yaw: cam3.yaw - dx * 0.008, pitch: clampPitch(cam3.pitch + dy * 0.008) };
    invalidate();
  };
  const zoomAt = (factor: number, x = width / 2, y = height / 2) => {
    if (mode === '2d') cam2 = zoom2D(cam2, width, height, factor, x, y);
    else cam3 = { ...cam3, distance: clampDistance(cam3.distance / factor) };
    invalidate();
  };

  canvas.addEventListener('pointerdown', (e) => {
    canvas.setPointerCapture?.(e.pointerId);
    pointers.set(e.pointerId, local(e));
    dragButton = e.shiftKey ? 2 : e.button;
  });
  canvas.addEventListener('pointermove', (e) => {
    const prev = pointers.get(e.pointerId);
    if (!prev) return;
    const now = local(e);
    if (pointers.size === 1) {
      const dx = now.x - prev.x;
      const dy = now.y - prev.y;
      if (mode === '3d' && dragButton === 0 && !e.shiftKey) orbit(dx, dy);
      else pan(dx, dy);
    } else if (pointers.size === 2) {
      const [a, b] = [...pointers.entries()].map(([id, p]) => (id === e.pointerId ? now : p));
      const [pa, pb] = [...pointers.values()];
      const before = Math.hypot(pa.x - pb.x, pa.y - pb.y);
      const after = Math.hypot(a.x - b.x, a.y - b.y);
      if (before > 0) zoomAt(after / before, (a.x + b.x) / 2, (a.y + b.y) / 2);
      pan((now.x - prev.x) / 2, (now.y - prev.y) / 2);
    }
    pointers.set(e.pointerId, now);
  });
  const release = (e: PointerEvent) => pointers.delete(e.pointerId);
  canvas.addEventListener('pointerup', release);
  canvas.addEventListener('pointercancel', release);
  canvas.addEventListener('contextmenu', (e) => e.preventDefault());
  canvas.addEventListener(
    'wheel',
    (e) => {
      e.preventDefault();
      const { x, y } = local(e);
      zoomAt(Math.exp(-e.deltaY * (e.ctrlKey ? 0.01 : 0.0015)), x, y);
    },
    { passive: false },
  );
  canvas.addEventListener('dblclick', () => surface.fit());
  canvas.addEventListener('keydown', (e) => {
    const stepPx = e.shiftKey ? 120 : 40;
    const keys: Record<string, () => void> = {
      ArrowLeft: () => (mode === '3d' && !e.shiftKey ? orbit(-24, 0) : pan(stepPx, 0)),
      ArrowRight: () => (mode === '3d' && !e.shiftKey ? orbit(24, 0) : pan(-stepPx, 0)),
      ArrowUp: () => (mode === '3d' && !e.shiftKey ? orbit(0, -24) : pan(0, stepPx)),
      ArrowDown: () => (mode === '3d' && !e.shiftKey ? orbit(0, 24) : pan(0, -stepPx)),
      '+': () => zoomAt(1.25),
      '=': () => zoomAt(1.25),
      '-': () => zoomAt(0.8),
      f: () => surface.fit(),
      F: () => surface.fit(),
      '0': () => surface.resetView(),
      Home: () => surface.resetView(),
    };
    const action = keys[e.key];
    if (action && !e.ctrlKey && !e.metaKey && !e.altKey) {
      e.preventDefault();
      action();
    }
  });

  const surface: Surface = {
    element,
    canvas,
    get available() {
      return ctx !== null;
    },
    get reason() {
      return reason;
    },
    setMode(next) {
      mode = next;
      invalidate();
    },
    setScene(next) {
      scene = next;
      invalidate();
    },
    fit() {
      resize();
      if (mode === '2d') cam2 = fit2D(scene, width, height);
      else cam3 = fit3D(scene, width, height, cam3);
      invalidate();
    },
    resetView() {
      if (mode === '2d') cam2 = { ...DEFAULT_CAMERA_2D };
      else cam3 = { ...DEFAULT_CAMERA_3D };
      invalidate();
    },
    zoom(factor) {
      zoomAt(factor);
    },
    renderNow() {
      resize();
      renderNow();
    },
    async toBlob() {
      if (!ctx) return null;
      const out = document.createElement('canvas');
      const ratio = Math.max(2, dpr);
      out.width = Math.round(width * ratio);
      out.height = Math.round(height * ratio);
      const octx = out.getContext('2d');
      if (!octx) return null;
      octx.setTransform(ratio, 0, 0, ratio, 0, 0);
      draw(octx, width, height, { ...scene, showTurtle: false });
      return new Promise((resolve) => out.toBlob((blob) => resolve(blob), 'image/png'));
    },
    refreshPalette() {
      palette = null;
      invalidate();
    },
    destroy() {
      observer?.disconnect();
    },
  };
  return surface;
}

