    canvas,
    get available() {
      return ctx !== null;
    },
    get reason() {
      return reason;
    },
    setMode(next) {
      mode = next;
      invalidate();
    },
    setScene(next) {
      scene = next;
      invalidate();
    },
    fit() {
      resize();
      if (mode === '2d') cam2 = fit2D(scene, width, height);
      else cam3 = fit3D(scene, width, height, cam3);
      invalidate();
    },
