import { h } from './dom';

let dialogCount = 0;

export interface Dialog {
  element: HTMLDialogElement;
  body: HTMLElement;
  open(): void;
  close(): void;
  readonly isOpen: boolean;
}

/** A modal dialog with a heading; Escape and the close button dismiss it. */
export function createDialog(title: string, options: { wide?: boolean; onClose?: () => void } = {}): Dialog {
  const id = `dialog-title-${++dialogCount}`;
  const body = h('div', { class: 'dialog-body' });
  const element = h(
    'dialog',
    { class: `dialog${options.wide ? ' dialog-wide' : ''}`, 'aria-labelledby': id },
    h(
      'div',
      { class: 'dialog-head' },
      h('h2', { id, class: 'dialog-title' }, title),
      h('button', { type: 'button', class: 'btn btn-icon btn-ghost', 'aria-label': 'Zamknij', onclick: () => dialog.close() }, '×'),
    ),
    body,
  );
  element.addEventListener('close', () => options.onClose?.());
  element.addEventListener('click', (event) => {
    // A click on the backdrop (outside the content box) closes the dialog.
    if (event.target === element) dialog.close();
  });
  document.body.append(element);
  const dialog: Dialog = {
    element,
    body,
    open() {
      if (element.open) return;
      if (typeof element.showModal === 'function') element.showModal();
      else element.setAttribute('open', '');
    },
    close() {
      if (!element.open) return;
      if (typeof element.close === 'function') element.close();
      else element.removeAttribute('open');
    },
    get isOpen() {
      return element.open;
    },
  };
  return dialog;
}

/** Asks a yes/no question; resolves to true when the user confirms. */
export function confirmDialog(options: {
  title: string;
  message: string;
  confirm: string;
  cancel?: string;
}): Promise<boolean> {
  return new Promise((resolve) => {
    let answer = false;
    const dialog = createDialog(options.title, {
      onClose: () => {
        dialog.element.remove();
        resolve(answer);
      },
    });
    const yes = h('button', { type: 'button', class: 'btn btn-primary', onclick: () => ((answer = true), dialog.close()) }, options.confirm);
    const no = h('button', { type: 'button', class: 'btn', onclick: () => dialog.close() }, options.cancel ?? 'Anuluj');
    dialog.body.append(h('p', null, options.message), h('div', { class: 'dialog-actions' }, no, yes));
    dialog.open();
    yes.focus();
  });
}

export interface Toaster {
  element: HTMLElement;
  show(message: string, action?: { label: string; run: () => void }): void;
}

/** Brief messages in a polite live region, optionally with one action button. */
export function createToaster(): Toaster {
  const element = h('div', { class: 'toasts', 'aria-live': 'polite', 'aria-atomic': 'false' });
  return {
    element,
    show(message, action) {
      const toast = h('div', { class: 'toast' }, h('span', null, message));
      const dismiss = () => toast.remove();
      if (action) {
        toast.append(
          h('button', { type: 'button', class: 'btn btn-small', onclick: () => (action.run(), dismiss()) }, action.label),
        );
      }
      toast.append(h('button', { type: 'button', class: 'btn btn-icon btn-ghost btn-small', 'aria-label': 'Zamknij komunikat', onclick: dismiss }, '×'));
      element.append(toast);
      while (element.children.length > 3) element.firstElementChild?.remove();
      setTimeout(dismiss, action ? 12000 : 5000);
    },
  };
}

