import { afterEach, describe, expect, test } from 'bun:test';
import { screen } from '@testing-library/dom';
import { mountApp, type AppDeps, type MountedApp } from '../src/app/app';
import type { Scheduler } from '../src/app/controller';

/** A frame scheduler the test drives by hand. */
function manualClock() {
  const callbacks = new Map<number, (now: number) => void>();
  let next = 0;
  let now = 0;
  const scheduler: Scheduler = {
    request(callback) {
      callbacks.set(++next, callback);
      return next;
    },
    cancel(handle) {
      callbacks.delete(handle);
    },
  };
  const tick = () => {
    now += 16;
    const due = [...callbacks.values()];
    callbacks.clear();
    for (const callback of due) callback(now);
  };
  return {
    scheduler,
    advance(ms: number) {
      for (let t = 0; t < ms; t += 16) tick();
    },
    tick,
  };
}

let app: MountedApp | null = null;
let clock = manualClock();
const downloads: { name: string; text: string }[] = [];

function mount(hash = '#/', storage: Storage = window.localStorage): MountedApp {
  app?.destroy();
  document.body.innerHTML = '<div id="app"></div>';
  history.replaceState(null, '', hash);
  clock = manualClock();
  const deps: AppDeps = {
    storage,
    scheduler: clock.scheduler,
    download: async (name, blob) => {
      downloads.push({ name, text: await blob.text() });
    },
  };
  app = mountApp(document.getElementById('app')!, deps);
  return app;
}

/** Resolves a promise that waits for animation frames by advancing the manual clock. */
async function settle<T>(promise: Promise<T>): Promise<T> {
  let done = false;
  let value: T;
  promise.then((v) => {
    done = true;
    value = v;
  });
  for (let i = 0; i < 200 && !done; i++) {
    clock.tick();
    await new Promise((resolve) => setTimeout(resolve, 0));
  }
  if (!done) throw new Error('promise did not settle');
  return value!;
}

const editor = () => screen.getByRole('textbox', { name: 'Kod programu' }) as HTMLTextAreaElement;
const modeRadio = (mode: '2D' | '3D') => screen.getByRole('radio', { name: mode }) as HTMLInputElement;

afterEach(() => {
  app?.destroy();
  app = null;
  window.localStorage.clear();
  downloads.length = 0;
});

const button = (name: string | RegExp) => screen.getByRole('button', { name }) as HTMLButtonElement;
const statusText = () => screen.getByRole('status').textContent ?? '';

function type(text: string) {
  const area = editor();
  area.value = text;
  area.dispatchEvent(new Event('input', { bubbles: true }));
}

function setSpeed(level: number) {
  const slider = screen.getByRole('slider', { name: /Prędkość/ }) as HTMLInputElement;
  slider.value = String(level);
  slider.dispatchEvent(new Event('input', { bubbles: true }));
}

describe('execution controls', () => {
  test('Krok executes one command at a time and highlights the line being executed', () => {
    mount();
    type('np 10\npw 90\nnp 20');
    button('Krok').click();
    button('Krok').click();
    expect(statusText()).toContain('Pauza w linii 2');
    expect(document.querySelector('.editor-active-line')?.getAttribute('style')).toContain('--line: 1');
  });

  test('Uruchom animates the program; Pauza and Wznów stop and continue it; Reset clears it', () => {
    mount();
    setSpeed(1);
    type('np 10\npw 90\nnp 20');
    button('Uruchom').click();
    clock.advance(1100);
    button('Pauza').click();
    const paused = statusText();
    clock.advance(5000);
    button('Wznów').click();
    clock.advance(3000);
    const finished = statusText();
    button('Reset').click();
    expect([paused, finished, statusText()]).toEqual([
      'Pauza w linii 2. Narysowano 1 odcinek.',
      'Gotowe: narysowano 2 odcinki (3 operacje).',
      'Gotowe do pracy. Napisz program i naciśnij „Uruchom”.',
    ]);
  });
});

describe('keyboard shortcuts', () => {
  const press = (key: string, mods: KeyboardEventInit = {}) =>
    editor().dispatchEvent(new KeyboardEvent('keydown', { key, bubbles: true, cancelable: true, ...mods }));

  test('run, step, pause/resume and reset have shortcuts that work from the editor', () => {
    mount();
    setSpeed(1);
    type('np 10\npw 90\nnp 20');
    press('Enter', { ctrlKey: true, shiftKey: true });
    const stepped = statusText();
    press('Enter', { ctrlKey: true });
    clock.advance(20);
    press('.', { ctrlKey: true });
    const paused = statusText();
    press('.', { ctrlKey: true });
    const resumed = controllerState();
    press('Backspace', { ctrlKey: true, shiftKey: true });
    expect([stepped, paused, resumed, statusText()]).toEqual([
      'Pauza w linii 1. Narysowano 1 odcinek.',
      'Pauza w linii 1. Narysowano 1 odcinek.',
      'running',
      'Gotowe do pracy. Napisz program i naciśnij „Uruchom”.',
    ]);
    expect(editor().value).toBe('np 10\npw 90\nnp 20');
  });

  test('the shortcuts are listed in the interface', () => {
    mount();
    button('Skróty klawiszowe').click();
    const dialog = screen.getByRole('dialog', { name: 'Skróty klawiszowe' });
    for (const keys of ['Ctrl + Enter', 'Ctrl + Shift + Enter', 'Ctrl + .', 'Ctrl + Shift + Backspace']) {
      expect(dialog.textContent).toContain(keys);
    }
    expect(button('Uruchom').getAttribute('aria-keyshortcuts')).toBe('Control+Enter');
  });
});

const controllerState = () => document.querySelector<HTMLElement>('[role="status"]')?.dataset.state;

describe('testing hook', () => {
  test('window.logomocja exposes a version, run and open', () => {
    mount();
    const hook = window.logomocja;
    expect([typeof hook.version, typeof hook.run, typeof hook.open]).toEqual(['string', 'function', 'function']);
    expect(hook.run('np 5', '2d')).toEqual({
      segments: [{ from: [0, 0, 0], to: [0, 5, 0], color: '#16866a', width: 3 }],
      error: null,
    });
  });

  test('open loads the program into the editor in the given mode and resolves with its drawing', async () => {
    mount();
    const result = await settle(window.logomocja.open('gora 90 np 50', '3d'));
    expect(result).toEqual({
      segments: [{ from: [0, 0, 0], to: [0, 0, 50], color: '#16866a', width: 3 }],
      error: null,
    });
    expect([editor().value, modeRadio('3D').checked, modeRadio('2D').checked]).toEqual(['gora 90 np 50', true, false]);
  });

  test('a parse error from open is marked inline in the editor and in the status, and nothing is drawn', async () => {
    mount();
    const result = await settle(window.logomocja.open('np 10\nnq 5', '2d'));
    expect(result.segments).toEqual([]);
    expect(result.error).toMatchObject({ line: 2, column: 1 });
    const marker = document.querySelector('.editor .error-lens');
    expect(marker?.textContent).toBe(result.error!.message);
    expect(screen.getByRole('status').textContent).toContain('Linia 2, kolumna 1');
    expect(editor().getAttribute('aria-invalid')).toBe('true');
  });
});

