import type { Mode } from '../lang';

const PREFIX = 'logomocja:';

export type ThemeChoice = 'system' | 'light' | 'dark';

export interface ChallengeProgress {
  /** Challenge id → when it was first solved (ms since epoch). */
  solved: Record<string, number>;
  /** Challenge id → the user's latest program for it. */
  drafts: Record<string, string>;
}

/** Everything the app keeps in local storage. Storage failures (private mode, quota) are ignored. */
export function createStore(storage: Storage) {
  const get = (key: string): string | null => {
    try {
      return storage.getItem(PREFIX + key);
    } catch {
      return null;
    }
  };
  const set = (key: string, value: string | null) => {
    try {
      if (value === null) storage.removeItem(PREFIX + key);
      else storage.setItem(PREFIX + key, value);
    } catch {
      // Not persisted; the app keeps working for this visit.
    }
  };
  return {
    draft: (mode: Mode) => get(`draft:${mode}`),
    saveDraft: (mode: Mode, text: string) => set(`draft:${mode}`, text),
    backup: (mode: Mode) => get(`backup:${mode}`),
    saveBackup: (mode: Mode, text: string | null) => set(`backup:${mode}`, text),
    mode: (): Mode | null => {
      const m = get('mode');
      return m === '2d' || m === '3d' ? m : null;
    },
    saveMode: (mode: Mode) => set('mode', mode),
    speed: (): number | null => {
      const n = Number(get('speed'));
      return Number.isInteger(n) && n > 0 ? n : null;
    },
    saveSpeed: (level: number) => set('speed', String(level)),
    theme: (): ThemeChoice => {
      const t = get('theme');
      return t === 'light' || t === 'dark' ? t : 'system';
    },
    saveTheme: (theme: ThemeChoice) => set('theme', theme === 'system' ? null : theme),
    progress: (): ChallengeProgress => {
      try {
        const parsed = JSON.parse(get('challenges') ?? '{}');
        return { solved: { ...parsed.solved }, drafts: { ...parsed.drafts } };
      } catch {
        return { solved: {}, drafts: {} };
      }
    },
    saveProgress: (progress: ChallengeProgress) => set('challenges', JSON.stringify(progress)),
  };
}

export type Store = ReturnType<typeof createStore>;

