    theme: (): ThemeChoice => {
      const t = get('theme');
      return t === 'light' || t === 'dark' ? t : 'system';
    },
    saveTheme: (theme: ThemeChoice) => set('theme', theme === 'system' ? null : theme),
    progress: (): ChallengeProgress => {
      try {
        const parsed = JSON.parse(get('challenges') ?? '{}');
        return { solved: { ...parsed.solved }, drafts: { ...parsed.drafts } };
      } catch {
        return { solved: {}, drafts: {} };
      }
    },
    saveProgress: (progress: ChallengeProgress) => set('challenges', JSON.stringify(progress)),
  };
}

export type Store = ReturnType<typeof createStore>;

