import { check, type LogoError, type Mode, type Segment } from '../lang';
import { createController, MAX_SPEED, type Scheduler, type Snapshot } from './controller';
import { h, icon, plural } from './dom';
import { createEditor } from './editor';
import { ICONS } from './icons';
import type { Store } from './store';
import { createSurface } from './surface';

type Action = 'run' | 'step' | 'pause' | 'reset';

/** Keyboard shortcuts; Ctrl may also be ⌘ on a Mac. */
export const SHORTCUTS: { action: Action; label: string; keys: string; aria: string; match: (e: KeyboardEvent) => boolean }[] = [
  { action: 'run', label: 'Uruchom program', keys: 'Ctrl + Enter', aria: 'Control+Enter', match: (e) => e.key === 'Enter' && !e.shiftKey },
  { action: 'step', label: 'Wykonaj jeden krok', keys: 'Ctrl + Shift + Enter', aria: 'Control+Shift+Enter', match: (e) => e.key === 'Enter' && e.shiftKey },
  { action: 'pause', label: 'Pauza / wznów', keys: 'Ctrl + .', aria: 'Control+.', match: (e) => e.key === '.' && !e.shiftKey },
  { action: 'reset', label: 'Wyczyść rysunek (reset)', keys: 'Ctrl + Shift + Backspace', aria: 'Control+Shift+Backspace', match: (e) => e.key === 'Backspace' && e.shiftKey },
];

export interface Workspace {
  element: HTMLElement;
  /** The area above the editor where a challenge brief appears. */
  aside: HTMLElement;
  /** Toolbar slot for file and sharing actions. */
  tools: HTMLElement;
  readonly mode: Mode;
  readonly source: string;
  /** Shows a program in a mode, replacing the editor text (callers protect drafts first). */
  show(source: string, mode: Mode): void;
  run(): void;
  /** Runs to the end at once, frames the drawing and resolves once it is on screen. */
  runAtOnce(): Promise<Snapshot>;
  snapshot(): Snapshot;
  setGhost(segments: readonly Segment[]): void;
  /** Locks the mode, e.g. while solving a challenge made for one mode. */
  lockMode(locked: boolean): void;
  exportPng(): Promise<Blob | null>;
  refreshPalette(): void;
  /** Handles a global keyboard shortcut; returns true when it was one. */
  handleShortcut(event: KeyboardEvent): boolean;
  focusEditor(): void;
  destroy(): void;
}

function describe(s: Snapshot): string {
  const drawn = `${s.segments.length} ${plural(s.segments.length, 'odcinek', 'odcinki', 'odcinków')}`;
  switch (s.state) {
    case 'idle':
      return 'Gotowe do pracy. Napisz program i naciśnij „Uruchom”.';
    case 'running':
      return 'Żółw rysuje…';
    case 'paused':
      return `Pauza${s.line ? ` w linii ${s.line}` : ''}. Narysowano ${drawn}.`;
    case 'finished':
      return `Gotowe: narysowano ${drawn} (${s.operations} ${plural(s.operations, 'operacja', 'operacje', 'operacji')}).`;
    case 'stopped':
      return `Zatrzymano, bo kod się zmienił. Narysowano ${drawn}.`;
    case 'error':
      return s.error ? `Linia ${s.error.line}, kolumna ${s.error.column}: ${s.error.message}` : 'Błąd.';
  }
}

function speedText(level: number): string {
  if (level >= MAX_SPEED) return 'natychmiast';
  if (level <= 2) return 'bardzo wolno';
  if (level <= 4) return 'wolno';
  if (level <= 6) return 'średnio';
  if (level <= 8) return 'szybko';
  return 'bardzo szybko';
}

export function createWorkspace(options: {
  store: Store;
  scheduler: Scheduler;
  initialMode: Mode;
  initialSource: (mode: Mode) => string;
  onModeChange?: (mode: Mode) => void;
  onEdit?: (source: string, mode: Mode) => void;
}): Workspace {
  const { store, scheduler } = options;
  const controller = createController({ scheduler });
  controller.setSpeed(store.speed() ?? controller.speed);
  let mode: Mode = options.initialMode;
  let ghost: readonly Segment[] = [];
  let checkTimer: ReturnType<typeof setTimeout> | undefined;

  const surface = createSurface({ request: (cb) => scheduler.request(cb) });
  const editor = createEditor({ id: 'editor', describedBy: 'status editor-help', onInput: () => onEdit() });
  const status = h('p', { class: 'status', role: 'status', id: 'status' });

  // Mode switch.
  const modeInputs = (['2d', '3d'] as const).map((m) =>
    h('input', { type: 'radio', name: 'mode', value: m, id: `mode-${m}`, onchange: () => switchMode(m) }),
  );
  const modeSwitch = h(
    'fieldset',
    { class: 'mode-switch' },
    h('legend', { class: 'sr-only' }, 'Tryb rysowania'),
    ...modeInputs.map((input, i) =>
      h('label', { class: 'mode-option', for: input.id }, input, h('span', null, i ? '3D' : '2D')),
    ),
  );
  const modeNote = h('p', { class: 'mode-note', hidden: true });

  // Run controls.
  const actions: Record<Action, () => void> = {
    run: () => controller.run(editor.value, mode),
    step: () => controller.step(editor.value, mode),
    pause: () => {
      const { state } = controller.snapshot();
      if (state === 'running') controller.pause();
      else if (state === 'paused') controller.resume();
    },
    reset: () => controller.reset(mode),
  };
  const controlButton = (action: Action, text: string, glyph: string, primary = false) =>
    h('button', { type: 'button', class: `btn${primary ? ' btn-primary' : ''}`, onclick: () => actions[action]() }, icon(glyph), h('span', { class: 'btn-text' }, text));
  const runButton = controlButton('run', 'Uruchom', ICONS.play, true);
  const stepButton = controlButton('step', 'Krok', ICONS.step);
  const pauseButton = controlButton('pause', 'Pauza', ICONS.pause);
  const resetButton = controlButton('reset', 'Reset', ICONS.reset);
  const buttons: Record<Action, HTMLButtonElement> = { run: runButton, step: stepButton, pause: pauseButton, reset: resetButton };
  for (const shortcut of SHORTCUTS) {
    buttons[shortcut.action].setAttribute('aria-keyshortcuts', shortcut.aria);
    buttons[shortcut.action].title = `${shortcut.label} (${shortcut.keys})`;
  }
  const speedValue = h('span', { class: 'speed-value', 'aria-hidden': 'true' });
  const speed = h('input', {
    type: 'range',
    min: '1',
    max: String(MAX_SPEED),
    step: '1',
    id: 'speed',
    'aria-label': 'Prędkość',
    oninput: () => setSpeed(Number(speed.value)),
  });
  const runBar = h(
    'div',
    { class: 'run-bar' },
    h('div', { class: 'run-buttons', role: 'group', 'aria-label': 'Wykonanie programu' }, runButton, stepButton, pauseButton, resetButton),
    h('label', { class: 'speed', for: 'speed' }, h('span', { class: 'speed-label' }, 'Prędkość'), speed, speedValue),
  );

  // View controls.
  const viewButton = (label: string, glyph: string, onclick: () => void) =>
    h('button', { type: 'button', class: 'btn btn-icon', 'aria-label': label, title: label, onclick }, icon(glyph));
  const resetViewLabel = () => (mode === '2d' ? 'Wróć do początku układu' : 'Ustaw kamerę od nowa');
  const resetViewButton = viewButton(resetViewLabel(), ICONS.home, () => surface.resetView());
  const viewControls = h(
    'div',
    { class: 'view-controls', role: 'group', 'aria-label': 'Widok rysunku' },
    viewButton('Przybliż', ICONS.zoomIn, () => surface.zoom(1.25)),
    viewButton('Oddal', ICONS.zoomOut, () => surface.zoom(0.8)),
    viewButton('Dopasuj widok do rysunku', ICONS.fit, () => surface.fit()),
    resetViewButton,
  );
  const viewHint = h('p', { class: 'view-hint', id: 'view-hint' });
  surface.canvas.setAttribute('aria-describedby', 'view-hint');

  const aside = h('div', { class: 'workspace-aside' });
  const tools = h('div', { class: 'workspace-tools' });
  const help = h(
    'p',
    { class: 'sr-only', id: 'editor-help' },
    'Tab wstawia wcięcie; Esc, a potem Tab, przenosi dalej. Ctrl+Enter uruchamia program.',
  );

  const element = h(
    'div',
    { class: 'workspace' },
    h(
      'section',
      { class: 'pane pane-code', 'aria-label': 'Program' },
      aside,
      h('div', { class: 'code-toolbar' }, modeSwitch, tools),
      modeNote,
      runBar,
      editor.element,
      help,
      status,
    ),
    h(
      'section',
      { class: 'pane pane-view', 'aria-label': 'Rysunek' },
      surface.element,
      viewControls,
      viewHint,
    ),
  );

  function setSpeed(level: number) {
    controller.setSpeed(level);
    store.saveSpeed(controller.speed);
    speed.value = String(controller.speed);
    const text = speedText(controller.speed);
    speedValue.textContent = text;
    speed.setAttribute('aria-valuetext', text);
  }

  function showError(error: LogoError | null, live = false) {
    editor.setError(error && { ...error, live });
    editor.textarea.setAttribute('aria-invalid', String(error !== null));
  }

  /** Checks the program shortly after typing stops and marks a parse error inline. */
  function scheduleCheck() {
    clearTimeout(checkTimer);
    checkTimer = setTimeout(() => showError(check(editor.value, mode), true), 400);
  }

  /** The running program no longer matches the code, so it stops; what it drew stays. */
  function onEdit() {
    store.saveDraft(mode, editor.value);
    controller.stop();
    showError(null);
    scheduleCheck();
    options.onEdit?.(editor.value, mode);
  }

  function applyMode(m: Mode) {
    mode = m;
    modeInputs.forEach((input) => (input.checked = input.value === m));
    surface.setMode(m);
    resetViewButton.setAttribute('aria-label', resetViewLabel());
    resetViewButton.title = resetViewLabel();
    viewHint.textContent =
      m === '2d'
        ? 'Przeciągnij, aby przesunąć; kółko myszy lub dwa palce przybliżają. Na rysunku działają też strzałki, + i −, F (dopasuj).'
        : 'Przeciągnij, aby obrócić kamerę; z Shiftem lub prawym przyciskiem przesuwasz; kółko lub dwa palce przybliżają. Strzałki obracają, F dopasowuje.';
  }

  /** A switch by the user: the editor shows the other mode's draft. */
  function switchMode(m: Mode) {
    if (m === mode) return;
    applyMode(m);
    store.saveMode(m);
    editor.value = options.initialSource(m);
    controller.reset(m);
    showError(null);
    surface.fit();
    options.onModeChange?.(m);
  }

  let shownState = '';
  const render = (s: Snapshot) => {
    surface.setScene({ segments: s.segments, turtle: s.turtle, ghost, showTurtle: true });
    editor.setActiveLine(s.state === 'running' || s.state === 'paused' ? s.line : null);
    const pauseText = s.state === 'paused' ? 'Wznów' : 'Pauza';
    pauseButton.querySelector('.btn-text')!.textContent = pauseText;
    pauseButton.querySelector('svg')!.innerHTML = s.state === 'paused' ? ICONS.play : ICONS.pause;
    pauseButton.disabled = s.state !== 'running' && s.state !== 'paused';
    element.dataset.state = s.state;
    // The live region only changes on state changes, so screen readers are not flooded while drawing.
    const key = s.state === 'running' ? 'running' : `${s.state}:${s.line}:${s.error?.line}:${s.error?.column}:${s.segments.length}`;
    if (key !== shownState) {
      shownState = key;
      status.textContent = describe(s);
      status.dataset.state = s.state;
      if (s.state !== 'stopped') {
        clearTimeout(checkTimer);
        showError(s.error);
      }
    }
    surface.canvas.setAttribute(
      'aria-label',
      `Rysunek ${mode.toUpperCase()}: ${s.segments.length} ${plural(s.segments.length, 'odcinek', 'odcinki', 'odcinków')}. ` +
        `Żółw w punkcie (${s.turtle.position.map((v) => Math.round(v * 10) / 10).join('; ')}).`,
    );
  };
  controller.subscribe(render);

  applyMode(mode);
  editor.value = options.initialSource(mode);
  setSpeed(controller.speed);
  render(controller.snapshot());
  // Frame the (empty) drawing once the layout has settled.
  scheduler.request(() => surface.fit());

  return {
    element,
    aside,
    tools,
    get mode() {
      return mode;
    },
    get source() {
      return editor.value;
    },
    show(source, m) {
      applyMode(m);
      store.saveMode(m);
      editor.value = source;
      store.saveDraft(m, source);
      controller.reset(m);
      showError(null);
      surface.fit();
    },
    run: () => actions.run(),
    async runAtOnce() {
      controller.reset(mode);
      controller.finish(editor.value, mode);
      surface.fit();
      surface.renderNow();
      await new Promise<void>((resolve) => scheduler.request(() => resolve()));
      return controller.snapshot();
    },
    snapshot: () => controller.snapshot(),
    setGhost(segments) {
      ghost = segments;
      render(controller.snapshot());
    },
    lockMode(locked) {
      modeInputs.forEach((input) => (input.disabled = locked));
      modeNote.hidden = !locked;
      modeNote.textContent = locked ? `To wyzwanie rozwiązuje się w trybie ${mode.toUpperCase()}.` : '';
    },
    exportPng: () => surface.toBlob(),
    refreshPalette: () => surface.refreshPalette(),
    handleShortcut(event) {
      if (!(event.ctrlKey || event.metaKey) || event.altKey) return false;
      const shortcut = SHORTCUTS.find((s) => s.match(event));
      if (!shortcut) return false;
      event.preventDefault();
      actions[shortcut.action]();
      return true;
    },
    focusEditor: () => editor.textarea.focus(),
    destroy() {
      clearTimeout(checkTimer);
      controller.reset();
      surface.destroy();
    },
  };
}

