  };
  controller.subscribe(render);

  applyMode(mode);
  editor.value = options.initialSource(mode);
  setSpeed(controller.speed);
  render(controller.snapshot());
  // Frame the (empty) drawing once the layout has settled.
  scheduler.request(() => surface.fit());

