import { check, type LogoError, type Mode, type Segment } from '../lang';
import { createController, MAX_SPEED, type Scheduler, type Snapshot } from './controller';
import { h, icon, plural } from './dom';
import { createEditor } from './editor';
import { ICONS } from './icons';
import type { Store } from './store';
import { createSurface } from './surface';

type Action = 'run' | 'step' | 'pause' | 'reset';

/** Keyboard shortcuts; Ctrl may also be ⌘ on a Mac. */
export const SHORTCUTS: { action: Action; label: string; keys: string; aria: string; match: (e: KeyboardEvent) => boolean }[] = [
  { action: 'run', label: 'Uruchom program', keys: 'Ctrl + Enter', aria: 'Control+Enter', match: (e) => e.key === 'Enter' && !e.shiftKey },
  { action: 'step', label: 'Wykonaj jeden krok', keys: 'Ctrl + Shift + Enter', aria: 'Control+Shift+Enter', match: (e) => e.key === 'Enter' && e.shiftKey },
  { action: 'pause', label: 'Pauza / wznów', keys: 'Ctrl + .', aria: 'Control+.', match: (e) => e.key === '.' && !e.shiftKey },
  { action: 'reset', label: 'Wyczyść rysunek (reset)', keys: 'Ctrl + Shift + Backspace', aria: 'Control+Shift+Backspace', match: (e) => e.key === 'Backspace' && e.shiftKey },
];

export interface Workspace {
  element: HTMLElement;
  /** The area above the editor where a challenge brief appears. */
  aside: HTMLElement;
  /** Toolbar slot for file and sharing actions. */
  tools: HTMLElement;
  readonly mode: Mode;
  readonly source: string;
  /** Shows a program in a mode, replacing the editor text (callers protect drafts first). */
  show(source: string, mode: Mode): void;
  run(): void;
  /** Runs to the end at once, frames the drawing and resolves once it is on screen. */
  runAtOnce(): Promise<Snapshot>;
  snapshot(): Snapshot;
  setGhost(segments: readonly Segment[]): void;
  /** Locks the mode, e.g. while solving a challenge made for one mode. */
  lockMode(locked: boolean): void;
  exportPng(): Promise<Blob | null>;
  refreshPalette(): void;
  /** Handles a global keyboard shortcut; returns true when it was one. */
  handleShortcut(event: KeyboardEvent): boolean;
  focusEditor(): void;
  destroy(): void;
}

function describe(s: Snapshot): string {
  const drawn = `${s.segments.length} ${plural(s.segments.length, 'odcinek', 'odcinki', 'odcinków')}`;
  switch (s.state) {
    case 'idle':
      return 'Gotowe do pracy. Napisz program i naciśnij „Uruchom”.';
    case 'running':
      return 'Żółw rysuje…';
    case 'paused':
      return `Pauza${s.line ? ` w linii ${s.line}` : ''}. Narysowano ${drawn}.`;
    case 'finished':
      return `Gotowe: narysowano ${drawn} (${s.operations} ${plural(s.operations, 'operacja', 'operacje', 'operacji')}).`;
    case 'stopped':
      return `Zatrzymano, bo kod się zmienił. Narysowano ${drawn}.`;
    case 'error':
      return s.error ? `Linia ${s.error.line}, kolumna ${s.error.column}: ${s.error.message}` : 'Błąd.';
  }
}

function speedText(level: number): string {
  if (level >= MAX_SPEED) return 'natychmiast';
  if (level <= 2) return 'bardzo wolno';
  if (level <= 4) return 'wolno';
  if (level <= 6) return 'średnio';
  if (level <= 8) return 'szybko';
  return 'bardzo szybko';
}

export function createWorkspace(options: {
  store: Store;
  scheduler: Scheduler;
  initialMode: Mode;
  initialSource: (mode: Mode) => string;
  onModeChange?: (mode: Mode) => void;
  onEdit?: (source: string, mode: Mode) => void;
}): Workspace {
  const { store, scheduler } = options;
  const controller = createController({ scheduler });
  controller.setSpeed(store.speed() ?? controller.speed);
  let mode: Mode = options.initialMode;
  let ghost: readonly Segment[] = [];
  let checkTimer: ReturnType<typeof setTimeout> | undefined;

  const surface = createSurface({ request: (cb) => scheduler.request(cb) });
  const editor = createEditor({ id: 'editor', describedBy: 'status editor-help', onInput: () => onEdit() });
  const status = h('p', { class: 'status', role: 'status', id: 'status' });

  // Mode switch.
  const modeInputs = (['2d', '3d'] as const).map((m) =>
    h('input', { type: 'radio', name: 'mode', value: m, id: `mode-${m}`, onchange: () => switchMode(m) }),
  );
  const modeSwitch = h(
    'fieldset',
    { class: 'mode-switch' },
    h('legend', { class: 'sr-only' }, 'Tryb rysowania'),
    ...modeInputs.map((input, i) =>
      h('label', { class: 'mode-option', for: input.id }, input, h('span', null, i ? '3D' : '2D')),
    ),
  );
  const modeNote = h('p', { class: 'mode-note', hidden: true });

  // Run controls.
  const actions: Record<Action, () => void> = {
    run: () => controller.run(editor.value, mode),
    step: () => controller.step(editor.value, mode),
    pause: () => {
      const { state } = controller.snapshot();
      if (state === 'running') controller.pause();
      else if (state === 'paused') controller.resume();
    },
    reset: () => controller.reset(mode),
  };
  const controlButton = (action: Action, text: string, glyph: string, primary = false) =>
    h('button', { type: 'button', class: `btn${primary ? ' btn-primary' : ''}`, onclick: () => actions[action]() }, icon(glyph), h('span', { class: 'btn-text' }, text));
  const runButton = controlButton('run', 'Uruchom', ICONS.play, true);
  const stepButton = controlButton('step', 'Krok', ICONS.step);
  const pauseButton = controlButton('pause', 'Pauza', ICONS.pause);
  const resetButton = controlButton('reset', 'Reset', ICONS.reset);
  const buttons: Record<Action, HTMLButtonElement> = { run: runButton, step: stepButton, pause: pauseButton, reset: resetButton };
  for (const shortcut of SHORTCUTS) {
    buttons[shortcut.action].setAttribute('aria-keyshortcuts', shortcut.aria);
    buttons[shortcut.action].title = `${shortcut.label} (${shortcut.keys})`;
  }
  const speedValue = h('span', { class: 'speed-value', 'aria-hidden': 'true' });
  const speed = h('input', {
    type: 'range',
    min: '1',
    max: String(MAX_SPEED),
    step: '1',
    id: 'speed',
