import type { Mode, Segment } from '../lang';
import { HOME } from './controller';
import { readPalette, type Scene } from './scene';
import { fit2D, render2D } from './view2d';
import { fit3D, render3D } from './view3d';

/** Draws a static, framed picture of a drawing (no turtle) into a small canvas. */
export function drawThumbnail(canvas: HTMLCanvasElement, segments: readonly Segment[], mode: Mode, ghost = false): void {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  const w = canvas.clientWidth || Number(canvas.getAttribute('width')) || 240;
  const h = canvas.clientHeight || Number(canvas.getAttribute('height')) || 160;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.round(w * dpr);
  canvas.height = Math.round(h * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const scene: Scene = ghost
    ? { segments: [], ghost: segments, turtle: HOME, showTurtle: false }
    : { segments, ghost: [], turtle: HOME, showTurtle: false };
  const palette = readPalette(canvas);
  if (mode === '2d') render2D(ctx, scene, fit2D(scene, w, h), w, h, palette);
  else render3D(ctx, scene, fit3D(scene, w, h), w, h, palette);
}
