import { run } from '../../lang';
import { h } from '../dom';
import { EXAMPLES, type Example } from '../examples';
import { drawThumbnail } from '../thumbnail';

export interface ExamplesPage {
  element: HTMLElement;
  /** Draws the thumbnails (lazily, the first time the page is shown, and on theme changes). */
  refresh(): void;
}

export function createExamplesPage(options: { onOpen(example: Example): void }): ExamplesPage {
  const thumbnails: { canvas: HTMLCanvasElement; example: Example }[] = [];
  const card = (example: Example) => {
    const canvas = h('canvas', { class: 'card-thumb', width: '280', height: '180', 'aria-hidden': 'true' });
    thumbnails.push({ canvas, example });
    return h(
      'li',
      { class: 'card' },
      canvas,
      h(
        'div',
        { class: 'card-body' },
        h('h3', { class: 'card-title' }, example.title, h('span', { class: 'badge' }, example.mode.toUpperCase())),
        h('p', { class: 'card-text' }, example.description),
        h(
          'button',
          {
            type: 'button',
            class: 'btn btn-small card-action',
            'aria-label': `Otwórz przykład ${example.title}`,
            onclick: () => options.onOpen(example),
          },
          'Otwórz i uruchom',
        ),
      ),
    );
  };
  const group = (mode: '2d' | '3d', title: string, lead: string) =>
    h(
      'section',
      { class: 'page-section', 'aria-labelledby': `examples-${mode}` },
      h('h2', { id: `examples-${mode}` }, title),
      h('p', { class: 'muted' }, lead),
      h('ul', { class: 'cards' }, EXAMPLES.filter((e) => e.mode === mode).map(card)),
    );
  const element = h(
    'div',
    { class: 'page-inner' },
    h(
      'header',
      { class: 'page-head' },
      h('h1', { tabindex: '-1' }, 'Przykłady'),
      h(
        'p',
        { class: 'lead' },
        'Trzynaście programów do obejrzenia, uruchomienia i przerobienia. Każdy otwiera się w swoim trybie; jeśli masz własny szkic, najpierw zapytam, czy go zastąpić.',
      ),
    ),
    group('2d', 'Na płaszczyźnie (2D)', 'Kwadraty, gwiazdy, spirale, procedury i rekurencja.'),
    group('3d', 'W przestrzeni (3D)', 'Żółw wznosi się, pochyla i przechyla: góra, dół, pp i pl.'),
  );
  let drawn = false;
  return {
    element,
    refresh() {
      drawn = true;
      for (const { canvas, example } of thumbnails) drawThumbnail(canvas, run(example.source, example.mode).segments, example.mode);
    },
    get drawn() {
      return drawn;
    },
  } as ExamplesPage;
}
