import { version } from '../../package.json';
import { run, type Mode, type RunResult } from '../lang';
import type { Scheduler } from './controller';
import { h, icon } from './dom';
import { EXAMPLES, findExample, WELCOME, type Example } from './examples';
import { ICONS, TURTLE_LOGO } from './icons';
import { createExamplesPage } from './pages/examples';
import { createStore } from './store';
import { confirmDialog, createDialog, createToaster } from './ui';
import { createWorkspace, SHORTCUTS } from './workspace';

/** The testing hook installed as `window.logomocja`. */
export interface LogomocjaHook {
  version: string;
  run(source: string, mode: Mode): RunResult;
  open(source: string, mode: Mode): Promise<RunResult>;
}

declare global {
  interface Window {
    logomocja: LogomocjaHook;
  }
}

/** The app's dependencies on the outside world. */
export interface AppDeps {
  storage: Storage;
  scheduler: Scheduler;
  /** Saves a file for the user (a download in the browser). */
  download(name: string, blob: Blob): void | Promise<void>;
}

export interface MountedApp {
  hook: LogomocjaHook;
  destroy(): void;
}

type Page = 'workspace' | 'examples' | 'challenges' | 'reference';

const PAGES: { page: Page; href: string; label: string; title: string }[] = [
  { page: 'workspace', href: '#/', label: 'Pracownia', title: 'Pracownia' },
  { page: 'examples', href: '#/przyklady', label: 'Przykłady', title: 'Przykłady' },
  { page: 'challenges', href: '#/wyzwania', label: 'Wyzwania', title: 'Wyzwania' },
  { page: 'reference', href: '#/polecenia', label: 'Polecenia', title: 'Polecenia języka' },
];

const normalizeMode = (mode: string): Mode => (String(mode).toLowerCase() === '3d' ? '3d' : '2d');
const MODE_NAME: Record<Mode, string> = { '2d': '2D', '3d': '3D' };

export function mountApp(root: HTMLElement, deps: AppDeps): MountedApp {
  const store = createStore(deps.storage);
  const toaster = createToaster();
  const draftOf = (m: Mode) => store.draft(m) ?? WELCOME[m];
  /** Programs the app itself wrote: replacing them never loses the user's work. */
  const builtIn = new Set<string>([...Object.values(WELCOME), ...EXAMPLES.map((e) => e.source)]);

  const workspace = createWorkspace({
    store,
    scheduler: deps.scheduler,
    initialMode: store.mode() ?? '2d',
    initialSource: draftOf,
  });

  const examplesPage = createExamplesPage({ onOpen: (example) => void openExample(example) });

  // Header and pages.
  const navLinks = PAGES.map(({ page, href, label }) => h('a', { href, class: 'nav-link', 'data-page': page }, label));
  const shortcutsDialog = createDialog('Skróty klawiszowe');
  shortcutsDialog.body.append(
    h(
      'table',
      { class: 'shortcuts' },
      h('thead', null, h('tr', null, h('th', { scope: 'col' }, 'Działanie'), h('th', { scope: 'col' }, 'Klawisze'))),
      h('tbody', null, SHORTCUTS.map((s) => h('tr', null, h('td', null, s.label), h('td', null, h('kbd', null, s.keys))))),
    ),
    h(
      'p',
      { class: 'muted' },
      'Na Macu zamiast Ctrl można użyć ⌘. W edytorze Tab wstawia wcięcie; Esc, a potem Tab, przenosi do kolejnego elementu. Na rysunku: strzałki przesuwają (w 3D obracają), + i − przybliżają, F dopasowuje widok.',
    ),
  );
  const header = h(
    'header',
    { class: 'topbar' },
    h('a', { class: 'brand', href: '#/' }, logo(), h('span', { class: 'brand-name' }, 'Logomocja')),
    h('nav', { class: 'nav', 'aria-label': 'Główna' }, navLinks),
    h(
      'div',
      { class: 'topbar-actions' },
      h(
        'button',
        { type: 'button', class: 'btn btn-icon btn-ghost', 'aria-label': 'Skróty klawiszowe', title: 'Skróty klawiszowe', onclick: () => shortcutsDialog.open() },
        icon(ICONS.keyboard),
      ),
    ),
  );
  const pages: Record<Page, HTMLElement> = {
    workspace: h('section', { class: 'page page-workspace', 'aria-label': 'Pracownia' }, workspace.element),
    examples: h('section', { class: 'page page-examples' }, examplesPage.element),
    challenges: h('section', { class: 'page page-challenges' }, h('div', { class: 'page-inner' }, h('h1', { tabindex: '-1' }, 'Wyzwania'))),
    reference: h('section', { class: 'page page-reference' }, h('div', { class: 'page-inner' }, h('h1', { tabindex: '-1' }, 'Polecenia języka'))),
  };
  const main = h('main', { id: 'main', class: 'main' }, Object.values(pages));
  const skip = h('a', { class: 'skip-link', href: '#editor', onclick: (e: Event) => (e.preventDefault(), showPage('workspace'), workspace.focusEditor()) }, 'Przejdź do edytora');
  root.append(h('div', { class: 'app' }, skip, header, main, toaster.element));

  let current: Page | null = null;
  function showPage(page: Page, focus = false) {
    if (page === current) return;
    current = page;
    for (const [name, el] of Object.entries(pages)) el.hidden = name !== page;
    for (const a of navLinks) {
      if (a.dataset.page === page) a.setAttribute('aria-current', 'page');
      else a.removeAttribute('aria-current');
    }
    const meta = PAGES.find((p) => p.page === page)!;
    document.title = page === 'workspace' ? 'Logomocja — pracownia żółwia' : `${meta.title} — Logomocja`;
    if (page === 'examples') examplesPage.refresh();
    if (focus) pages[page].querySelector<HTMLElement>('h1')?.focus();
  }

  /**
   * Replaces a mode's draft with another program. When the draft holds the user's own work,
   * asks first and keeps it as a backup that a toast offers to restore.
   */
  async function replaceDraft(mode: Mode, source: string, what: string, confirmLabel: string): Promise<boolean> {
    const draft = draftOf(mode);
    if (draft.trim() !== '' && draft !== source && !builtIn.has(draft)) {
      const ok = await confirmDialog({
        title: 'Zastąpić szkic?',
        message: `W trybie ${MODE_NAME[mode]} masz własny program. ${what} zajmie jego miejsce, a Twój szkic zachowam jako kopię, którą możesz przywrócić.`,
        confirm: confirmLabel,
      });
      if (!ok) return false;
      store.saveBackup(mode, draft);
      toaster.show(`${what}: wczytano. Twój poprzedni szkic jest bezpieczny.`, {
        label: 'Przywróć szkic',
        run: () => restoreBackup(mode),
      });
    }
    workspace.show(source, mode);
    return true;
  }

  function restoreBackup(mode: Mode) {
    const backup = store.backup(mode);
    if (backup === null) return;
    store.saveBackup(mode, workspace.mode === mode ? workspace.source : draftOf(mode));
    workspace.show(backup, mode);
    showPage('workspace');
  }

  async function openExample(example: Example) {
    if (!(await replaceDraft(example.mode, example.source, `Przykład „${example.title}”`, 'Wczytaj przykład'))) return;
    navigate('#/');
    workspace.run();
  }

  /** Changes the address without adding a history entry, then shows the page. */
  function navigate(hash: string) {
    history.replaceState(null, '', hash);
    route(false);
  }

  function route(focus = true) {
    const path = decodeURIComponent(location.hash.replace(/^#/, '')) || '/';
    const example = /^\/przyklad\/([^/]+)$/.exec(path);
    if (example) {
      const found = findExample(example[1]);
      navigate('#/');
      if (found) void openExample(found);
      else toaster.show(`Nie ma przykładu o nazwie „${example[1]}”.`);
      return;
    }
    const page = PAGES.find((p) => p.href === `#${path}`)?.page ?? 'workspace';
    showPage(page, focus);
  }
  const onHashChange = () => route();
  window.addEventListener('hashchange', onHashChange);

  const onKeyDown = (event: KeyboardEvent) => {
    if (current === 'workspace') workspace.handleShortcut(event);
  };
  document.addEventListener('keydown', onKeyDown);

  route(false);

  const hook: LogomocjaHook = {
    version,
    run: (source, m) => run(String(source), normalizeMode(m)),
    async open(source, m) {
      const target = normalizeMode(m);
      document.querySelectorAll<HTMLDialogElement>('dialog[open]').forEach((d) => d.close());
      if (current !== 'workspace') navigate('#/');
      workspace.show(String(source), target);
      const snapshot = await workspace.runAtOnce();
      return { segments: run(workspace.source, target).segments, error: snapshot.error };
    },
  };
  window.logomocja = hook;

  return {
    hook,
    destroy() {
      window.removeEventListener('hashchange', onHashChange);
      document.removeEventListener('keydown', onKeyDown);
      shortcutsDialog.element.remove();
      document.querySelectorAll('dialog').forEach((d) => d.remove());
      workspace.destroy();
      root.replaceChildren();
    },
  };
}

function logo(): SVGSVGElement {
  return icon(TURTLE_LOGO, 'brand-logo');
}

