  function route(focus = true) {
    const path = decodeURIComponent(location.hash.replace(/^#/, '')) || '/';
    const example = /^\/przyklad\/([^/]+)$/.exec(path);
    if (example) {
      const found = findExample(example[1]);
      navigate('#/');
      if (found) void openExample(found);
      else toaster.show(`Nie ma przykładu o nazwie „${example[1]}”.`);
      return;
    }
    const page = PAGES.find((p) => p.href === `#${path}`)?.page ?? 'workspace';
    showPage(page, focus);
  }
  const onHashChange = () => route();
  window.addEventListener('hashchange', onHashChange);

  const onKeyDown = (event: KeyboardEvent) => {
    if (current === 'workspace') workspace.handleShortcut(event);
  };
  document.addEventListener('keydown', onKeyDown);

  route(false);

  const hook: LogomocjaHook = {
    version,
    run: (source, m) => run(String(source), normalizeMode(m)),
    async open(source, m) {
      const target = normalizeMode(m);
      document.querySelectorAll<HTMLDialogElement>('dialog[open]').forEach((d) => d.close());
      if (current !== 'workspace') navigate('#/');
      workspace.show(String(source), target);
      const snapshot = await workspace.runAtOnce();
      return { segments: run(workspace.source, target).segments, error: snapshot.error };
    },
  };
  window.logomocja = hook;

  return {
    hook,
    destroy() {
      window.removeEventListener('hashchange', onHashChange);
      document.removeEventListener('keydown', onKeyDown);
      document.querySelectorAll('dialog').forEach((d) => d.remove());
      workspace.destroy();
      root.replaceChildren();
    },
  };
}

function logo(): SVGSVGElement {
  return icon(TURTLE_LOGO, 'brand-logo');
}

