import { version } from '../../package.json';
import { check, run, type LogoError, type Mode, type RunResult } from '../lang';
import { createController, MAX_SPEED, type Scheduler, type Snapshot } from './controller';
import { h, plural } from './dom';
import { createEditor } from './editor';
import { WELCOME } from './examples';
import { createStore } from './store';
import { createSurface } from './surface';
import { createDialog } from './ui';

/** The testing hook installed as `window.logomocja`. */
export interface LogomocjaHook {
  version: string;
  run(source: string, mode: Mode): RunResult;
  open(source: string, mode: Mode): Promise<RunResult>;
}

declare global {
  interface Window {
    logomocja: LogomocjaHook;
  }
}

/** The app's dependencies on the outside world. */
export interface AppDeps {
  storage: Storage;
  scheduler: Scheduler;
  /** Saves a file for the user (a download in the browser). */
  download(name: string, blob: Blob): void | Promise<void>;
}

export interface MountedApp {
  hook: LogomocjaHook;
  destroy(): void;
}

function describe(s: Snapshot): string {
  const drawn = `${s.segments.length} ${plural(s.segments.length, 'odcinek', 'odcinki', 'odcinków')}`;
  switch (s.state) {
    case 'idle':
      return 'Gotowe do pracy. Napisz program i naciśnij „Uruchom”.';
    case 'running':
      return 'Żółw rysuje…';
    case 'paused':
      return `Pauza${s.line ? ` w linii ${s.line}` : ''}. Narysowano ${drawn}.`;
    case 'finished':
      return `Gotowe: narysowano ${drawn} (${s.operations} ${plural(s.operations, 'operacja', 'operacje', 'operacji')}).`;
    case 'stopped':
      return `Zatrzymano, bo kod się zmienił. Narysowano ${drawn}.`;
    case 'error':
      return s.error ? `Linia ${s.error.line}, kolumna ${s.error.column}: ${s.error.message}` : 'Błąd.';
  }
}

type Action = 'run' | 'step' | 'pause' | 'reset';

/** Keyboard shortcuts; Ctrl may also be ⌘ on a Mac. */
export const SHORTCUTS: { action: Action; label: string; keys: string; aria: string; match: (e: KeyboardEvent) => boolean }[] = [
  { action: 'run', label: 'Uruchom program', keys: 'Ctrl + Enter', aria: 'Control+Enter', match: (e) => e.key === 'Enter' && !e.shiftKey },
  { action: 'step', label: 'Jeden krok', keys: 'Ctrl + Shift + Enter', aria: 'Control+Shift+Enter', match: (e) => e.key === 'Enter' && e.shiftKey },
  { action: 'pause', label: 'Pauza / wznów', keys: 'Ctrl + .', aria: 'Control+.', match: (e) => e.key === '.' && !e.shiftKey },
  { action: 'reset', label: 'Reset rysunku', keys: 'Ctrl + Shift + Backspace', aria: 'Control+Shift+Backspace', match: (e) => e.key === 'Backspace' && e.shiftKey },
];

function speedText(level: number): string {
  if (level >= MAX_SPEED) return 'natychmiast';
  if (level <= 2) return 'bardzo wolno';
  if (level <= 4) return 'wolno';
  if (level <= 6) return 'średnio';
  if (level <= 8) return 'szybko';
  return 'bardzo szybko';
}

const normalizeMode = (mode: string): Mode => (String(mode).toLowerCase() === '3d' ? '3d' : '2d');

export function mountApp(root: HTMLElement, deps: AppDeps): MountedApp {
  const store = createStore(deps.storage);
  const controller = createController({ scheduler: deps.scheduler });
  controller.setSpeed(store.speed() ?? controller.speed);
  let mode: Mode = store.mode() ?? '2d';
  const draftOf = (m: Mode) => store.draft(m) ?? WELCOME[m];

  const nextFrame = () => new Promise<void>((resolve) => deps.scheduler.request(() => resolve()));
  const surface = createSurface({ request: (cb) => deps.scheduler.request(cb) });
  const editor = createEditor({ id: 'editor', describedBy: 'status', onInput: () => onEdit() });

  const modeInputs = (['2d', '3d'] as const).map((m) =>
    h('input', { type: 'radio', name: 'mode', value: m, id: `mode-${m}`, onchange: () => setMode(m) }),
  );
  const modeSwitch = h(
    'fieldset',
    { class: 'mode-switch' },
    h('legend', { class: 'sr-only' }, 'Tryb rysowania'),
    ...modeInputs.map((input, i) => h('label', { class: 'mode-option', for: input.id }, input, h('span', null, i ? '3D' : '2D'))),
  );

  const status = h('p', { class: 'status', role: 'status', id: 'status' });

  const runButton = h('button', { type: 'button', class: 'btn btn-primary', onclick: () => actions.run() }, 'Uruchom');
  const stepButton = h('button', { type: 'button', class: 'btn', onclick: () => actions.step() }, 'Krok');
  const pauseButton = h('button', { type: 'button', class: 'btn', onclick: () => actions.pause() }, 'Pauza');
  const resetButton = h('button', { type: 'button', class: 'btn', onclick: () => actions.reset() }, 'Reset');
  const speedLabel = h('span', { class: 'speed-value' });
  const speed = h('input', {
    type: 'range',
    min: '1',
    max: String(MAX_SPEED),
    step: '1',
    value: String(controller.speed),
    'aria-label': 'Prędkość',
    oninput: () => setSpeed(Number(speed.value)),
  });
  const runBar = h(
    'div',
    { class: 'run-bar', role: 'group', 'aria-label': 'Wykonanie programu' },
    runButton,
    stepButton,
    pauseButton,
    resetButton,
    h('label', { class: 'speed' }, h('span', { class: 'speed-label' }, 'Prędkość'), speed, speedLabel),
  );

  const actions: Record<Action, () => void> = {
    run: () => controller.run(editor.value, mode),
    step: () => controller.step(editor.value, mode),
    pause: () => togglePause(),
    reset: () => controller.reset(mode),
  };
  const buttons: Record<Action, HTMLButtonElement> = { run: runButton, step: stepButton, pause: pauseButton, reset: resetButton };
  for (const shortcut of SHORTCUTS) {
    buttons[shortcut.action].setAttribute('aria-keyshortcuts', shortcut.aria);
    buttons[shortcut.action].title = `${shortcut.label} (${shortcut.keys})`;
  }
  const onKeyDown = (event: KeyboardEvent) => {
    if (!(event.ctrlKey || event.metaKey) || event.altKey) return;
    const shortcut = SHORTCUTS.find((s) => s.match(event));
    if (!shortcut) return;
    event.preventDefault();
    actions[shortcut.action]();
  };
  document.addEventListener('keydown', onKeyDown);

  const shortcutsDialog = createDialog('Skróty klawiszowe');
  shortcutsDialog.body.append(
    h(
      'table',
      { class: 'shortcuts' },
      h('thead', null, h('tr', null, h('th', { scope: 'col' }, 'Działanie'), h('th', { scope: 'col' }, 'Klawisze'))),
      h(
        'tbody',
        null,
        SHORTCUTS.map((s) => h('tr', null, h('td', null, s.label), h('td', null, h('kbd', null, s.keys)))),
      ),
    ),
    h('p', { class: 'muted' }, 'Na Macu zamiast Ctrl można użyć ⌘. W edytorze Tab wstawia wcięcie; Esc, a potem Tab, przenosi do kolejnego elementu.'),
  );
  const shortcutsButton = h('button', { type: 'button', class: 'btn btn-ghost', 'aria-label': 'Skróty klawiszowe', onclick: () => shortcutsDialog.open() }, '⌨');

  root.append(h('div', { class: 'app' }, shortcutsButton, modeSwitch, runBar, editor.element, status, surface.element));

  /** The running program no longer matches the code, so it stops; what it drew stays. */
  function onEdit() {
    store.saveDraft(mode, editor.value);
    controller.stop();
    showError(null);
    scheduleCheck();
  }

  let checkTimer: ReturnType<typeof setTimeout> | undefined;
  /** Checks the program shortly after typing stops and marks a parse error inline. */
  function scheduleCheck() {
    clearTimeout(checkTimer);
    checkTimer = setTimeout(() => {
      const error = check(editor.value, mode);
      showError(error, true);
    }, 400);
  }

  function showError(error: LogoError | null, live = false) {
    editor.setError(error && { ...error, live });
    editor.textarea.setAttribute('aria-invalid', String(error !== null));
  }

  function togglePause() {
    const { state } = controller.snapshot();
    if (state === 'running') controller.pause();
    else if (state === 'paused') controller.resume();
  }

  function setSpeed(level: number) {
    controller.setSpeed(level);
    store.saveSpeed(controller.speed);
    speed.value = String(controller.speed);
    const text = speedText(controller.speed);
    speedLabel.textContent = text;
    speed.setAttribute('aria-valuetext', text);
  }
  setSpeed(controller.speed);

  /** Switches the drawing mode; the editor shows that mode's draft. */
  function setMode(m: Mode, text = draftOf(m)) {
    const changed = m !== mode || editor.value !== text;
    mode = m;
    store.saveMode(m);
    modeInputs.forEach((input) => (input.checked = input.value === m));
    surface.setMode(m);
    if (changed) {
      editor.value = text;
      store.saveDraft(m, text);
      controller.reset(m);
      showError(null);
    }
  }

  let shownState = '';
  const render = (s: Snapshot) => {
    surface.setScene({ segments: s.segments, turtle: s.turtle, ghost: [], showTurtle: true });
    editor.setActiveLine(s.state === 'running' || s.state === 'paused' ? s.line : null);
    // The live region only changes on state changes, so screen readers are not flooded while drawing.
    const key = s.state === 'running' ? 'running' : `${s.state}:${s.line}:${s.error?.line}:${s.error?.column}:${s.segments.length}`;
    pauseButton.textContent = s.state === 'paused' ? 'Wznów' : 'Pauza';
    pauseButton.disabled = s.state !== 'running' && s.state !== 'paused';
    if (key !== shownState) {
      shownState = key;
      status.textContent = describe(s);
      status.dataset.state = s.state;
      if (s.state !== 'stopped') {
        clearTimeout(checkTimer);
        showError(s.error);
      }
    }
  };
  controller.subscribe(render);
  editor.value = draftOf(mode);
  setMode(mode);
  render(controller.snapshot());

  const hook: LogomocjaHook = {
    version,
    run: (source, m) => run(String(source), normalizeMode(m)),
    async open(source, m) {
      const target = normalizeMode(m);
      setMode(target, String(source));
      controller.reset(target);
      controller.finish(editor.value, target);
      surface.fit();
      surface.renderNow();
      await nextFrame();
      return run(editor.value, target);
    },
  };
  window.logomocja = hook;

  return {
    hook,
    destroy() {
      clearTimeout(checkTimer);
      document.removeEventListener('keydown', onKeyDown);
      shortcutsDialog.element.remove();
      controller.reset();
      surface.destroy();
      root.replaceChildren();
    },
  };
}

