import { afterEach, describe, expect, test } from 'bun:test';
import { screen } from '@testing-library/dom';
import { mountApp, type AppDeps, type MountedApp } from '../src/app/app';
import type { Scheduler } from '../src/app/controller';

/** A frame scheduler the test drives by hand. */
function manualClock() {
  const callbacks = new Map<number, (now: number) => void>();
  let next = 0;
  let now = 0;
  const scheduler: Scheduler = {
    request(callback) {
      callbacks.set(++next, callback);
      return next;
    },
    cancel(handle) {
      callbacks.delete(handle);
    },
  };
  const tick = () => {
    now += 16;
    const due = [...callbacks.values()];
    callbacks.clear();
    for (const callback of due) callback(now);
  };
  return {
    scheduler,
    advance(ms: number) {
      for (let t = 0; t < ms; t += 16) tick();
    },
    tick,
  };
}

let app: MountedApp | null = null;
let clock = manualClock();
const downloads: { name: string; text: string }[] = [];

function mount(hash = '#/', storage: Storage = window.localStorage): MountedApp {
  app?.destroy();
  document.body.innerHTML = '<div id="app"></div>';
  history.replaceState(null, '', hash);
  clock = manualClock();
  const deps: AppDeps = {
    storage,
    scheduler: clock.scheduler,
    download: async (name, blob) => {
      downloads.push({ name, text: await blob.text() });
    },
  };
  app = mountApp(document.getElementById('app')!, deps);
  return app;
}

/** Resolves a promise that waits for animation frames by advancing the manual clock. */
async function settle<T>(promise: Promise<T>): Promise<T> {
  let done = false;
  let value: T;
  promise.then((v) => {
    done = true;
    value = v;
  });
  for (let i = 0; i < 200 && !done; i++) {
    clock.tick();
    await new Promise((resolve) => setTimeout(resolve, 0));
  }
  if (!done) throw new Error('promise did not settle');
  return value!;
}

const editor = () => screen.getByRole('textbox', { name: 'Kod programu' }) as HTMLTextAreaElement;
const modeRadio = (mode: '2D' | '3D') => screen.getByRole('radio', { name: mode }) as HTMLInputElement;

afterEach(() => {
  app?.destroy();
  app = null;
  window.localStorage.clear();
  downloads.length = 0;
});

const button = (name: string | RegExp) => screen.getByRole('button', { name }) as HTMLButtonElement;
const statusText = () => screen.getByRole('status').textContent ?? '';

function type(text: string) {
  const area = editor();
  area.value = text;
  area.dispatchEvent(new Event('input', { bubbles: true }));
}

function setSpeed(level: number) {
  const slider = screen.getByRole('slider', { name: /Prędkość/ }) as HTMLInputElement;
  slider.value = String(level);
  slider.dispatchEvent(new Event('input', { bubbles: true }));
}

describe('execution controls', () => {
  test('Krok executes one command at a time and highlights the line being executed', () => {
    mount();
    type('np 10\npw 90\nnp 20');
    button('Krok').click();
    button('Krok').click();
    expect(statusText()).toContain('Pauza w linii 2');
    expect(document.querySelector('.editor-active-line')?.getAttribute('style')).toContain('--line: 1');
  });

  test('Uruchom animates the program; Pauza and Wznów stop and continue it; Reset clears it', () => {
    mount();
    setSpeed(1);
    type('np 10\npw 90\nnp 20');
    button('Uruchom').click();
    clock.advance(1100);
    button('Pauza').click();
    const paused = statusText();
    clock.advance(5000);
    button('Wznów').click();
    clock.advance(3000);
    const finished = statusText();
    button('Reset').click();
    expect([paused, finished, statusText()]).toEqual([
      'Pauza w linii 2. Narysowano 1 odcinek.',
      'Gotowe: narysowano 2 odcinki (3 operacje).',
      'Gotowe do pracy. Napisz program i naciśnij „Uruchom”.',
    ]);
  });
});

describe('editing while running', () => {
  test('editing the code while the program runs stops it and keeps what was drawn', () => {
    mount();
    setSpeed(1);
    type('np 10\npw 90\nnp 20');
    button('Uruchom').click();
    clock.advance(1100);
    type('np 10\npw 90\nnp 30');
    clock.advance(5000);
    expect(statusText()).toBe('Zatrzymano, bo kod się zmienił. Narysowano 1 odcinek.');
  });
});

describe('checking while typing', () => {
  const marker = () => document.querySelector('.editor .error-lens')?.textContent ?? null;
  const pause = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

  test('a parse error is marked shortly after typing stops and cleared once fixed', async () => {
    mount();
    type('np 10\npowtorz 4 [np 5');
    const immediately = marker();
    await pause(600);
    const later = marker();
    type('np 10\npowtorz 4 [np 5]');
    await pause(600);
    expect([immediately, later, marker()]).toEqual([null, 'Nawias „[” nie został zamknięty — brakuje „]”.', null]);
  });

  test('a run-time error from the last run disappears when the code is edited', async () => {
    mount();
    setSpeed(10);
    type('np 10 / 0');
    button('Uruchom').click();
    const shown = marker();
    type('np 10 / 2');
    expect([shown, marker()]).toEqual(['Nie można dzielić przez zero.', null]);
  });
});

describe('drafts', () => {
  test('each mode keeps its own draft, and both survive a reload together with the mode', () => {
    mount();
    type('np 77');
    modeRadio('3D').click();
    type('gora 90 np 5');
    mount(); // reload with the same local storage
    const after3d = [modeRadio('3D').checked, editor().value];
    modeRadio('2D').click();
    expect([...after3d, editor().value]).toEqual([true, 'gora 90 np 5', 'np 77']);
  });

  test('a first visit starts with a ready-to-run program in each mode', () => {
    mount();
    const first2d = editor().value;
    modeRadio('3D').click();
    const first3d = editor().value;
    expect([window.logomocja.run(first2d, '2d').error, window.logomocja.run(first3d, '3d').error]).toEqual([null, null]);
    expect(first2d.length > 0 && first3d.length > 0 && first2d !== first3d).toBe(true);
  });
});

const pause = (ms = 0) => new Promise((resolve) => setTimeout(resolve, ms));
const link = (name: string | RegExp) => screen.getByRole('link', { name }) as HTMLAnchorElement;

/** Follows an in-app link the way a click would (happy-dom does not navigate on its own). */
async function follow(anchor: HTMLAnchorElement) {
  location.hash = anchor.getAttribute('href')!;
  window.dispatchEvent(new HashChangeEvent('hashchange'));
  await pause();
}

describe('examples', () => {
  test('every standard program is offered under its name and opens in its mode', async () => {
    mount();
    await follow(link('Przykłady'));
    const offered = screen.getAllByRole('button', { name: /^Otwórz przykład/ }).map((b) => b.getAttribute('aria-label'));
    expect(offered.length).toBe(13);
    button('Otwórz przykład Schody').click();
    await pause();
    expect([modeRadio('3D').checked, editor().value.startsWith('; Żółw wspina się w przestrzeni.'), location.hash]).toEqual([
      true,
      true,
      '#/',
    ]);
  });

  test('loading an example over the user’s own draft asks first, and the draft can be restored', async () => {
    mount();
    type('np 13');
    await follow(link('Przykłady'));
    button('Otwórz przykład Gwiazda').click();
    await pause();
    screen.getByRole('dialog', { name: 'Zastąpić szkic?' });
    button('Anuluj').click();
    await pause();
    const kept = editor().value;
    button('Otwórz przykład Gwiazda').click();
    await pause();
    button('Wczytaj przykład').click();
    await pause();
    const loaded = editor().value.split('\n')[0];
    button('Przywróć szkic').click();
    await pause();
    expect([kept, loaded, editor().value]).toEqual(['np 13', '; Sekret gwiazdy? Kąt 144 stopni.', 'np 13']);
  });

  test('an example opens by its name from the address', async () => {
    mount('#/przyklad/drzewo3d');
    await pause();
    expect([modeRadio('3D').checked, editor().value.split('\n')[0]]).toEqual([
      true,
      '; Drzewo w przestrzeni: gałęzie obracają się wokół pnia.',
    ]);
  });
});

describe('keyboard shortcuts', () => {
  const press = (key: string, mods: KeyboardEventInit = {}) =>
    editor().dispatchEvent(new KeyboardEvent('keydown', { key, bubbles: true, cancelable: true, ...mods }));

  test('run, step, pause/resume and reset have shortcuts that work from the editor', () => {
    mount();
    setSpeed(1);
    type('np 10\npw 90\nnp 20');
    press('Enter', { ctrlKey: true, shiftKey: true });
    const stepped = statusText();
    press('Enter', { ctrlKey: true });
    clock.advance(20);
    press('.', { ctrlKey: true });
    const paused = statusText();
    press('.', { ctrlKey: true });
    const resumed = controllerState();
    press('Backspace', { ctrlKey: true, shiftKey: true });
    expect([stepped, paused, resumed, statusText()]).toEqual([
      'Pauza w linii 1. Narysowano 1 odcinek.',
      'Pauza w linii 1. Narysowano 1 odcinek.',
      'running',
      'Gotowe do pracy. Napisz program i naciśnij „Uruchom”.',
    ]);
    expect(editor().value).toBe('np 10\npw 90\nnp 20');
  });

  test('the shortcuts are listed in the interface', () => {
    mount();
    button('Skróty klawiszowe').click();
    const dialog = screen.getByRole('dialog', { name: 'Skróty klawiszowe' });
    for (const keys of ['Ctrl + Enter', 'Ctrl + Shift + Enter', 'Ctrl + .', 'Ctrl + Shift + Backspace']) {
      expect(dialog.textContent).toContain(keys);
    }
    expect(button('Uruchom').getAttribute('aria-keyshortcuts')).toBe('Control+Enter');
  });
});

const controllerState = () => document.querySelector<HTMLElement>('[role="status"]')?.dataset.state;

describe('testing hook', () => {
  test('window.logomocja exposes a version, run and open', () => {
    mount();
    const hook = window.logomocja;
    expect([typeof hook.version, typeof hook.run, typeof hook.open]).toEqual(['string', 'function', 'function']);
