import type { Mode } from '../lang';

/** The hash route of a permalink: `#/program/<mode>/<base64url of the UTF-8 source>`. */
export function permalinkHash(source: string, mode: Mode): string {
  return `#/program/${mode}/${toBase64Url(source)}`;
}

/** The full address of a permalink, relative to the current page (works under any base path). */
export function permalink(source: string, mode: Mode, location: Location = window.location): string {
  return `${location.origin}${location.pathname}${location.search}${permalinkHash(source, mode)}`;
}

/** Reads a permalink route (without the leading `#`); null when it is not one or is damaged. */
export function readPermalink(path: string): { source: string; mode: Mode } | null {
  const match = /^\/program\/(2d|3d)\/([A-Za-z0-9_-]*)$/i.exec(path);
  if (!match) return null;
  try {
    return { mode: match[1].toLowerCase() as Mode, source: fromBase64Url(match[2]) };
  } catch {
    return null;
  }
}

function toBase64Url(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let binary = '';
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function fromBase64Url(data: string): string {
  const binary = atob(data.replace(/-/g, '+').replace(/_/g, '/'));
  const bytes = Uint8Array.from(binary, (c) => c.charCodeAt(0));
  return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
}

