import { run, type Mode, type Segment, type Vec3 } from '../lang';

export interface Challenge {
  id: string;
  title: string;
  mode: Mode;
  /** 1 = first steps, 2 = needs a construct, 3 = a puzzle. */
  level: 1 | 2 | 3;
  /** What to draw. */
  brief: string;
  hint: string;
  /** What the editor starts with. */
  starter: string;
  /** A reference program; its drawing is the target. */
  solution: string;
}

export interface Verdict {
  passed: boolean;
  reason: string;
}

/** How far (in turtle steps) a line may be from the target and still count as the same. */
export const TOLERANCE = 1.5;

/** Compares the program's drawing with the challenge's target drawing. */
export function checkSolution(challenge: Challenge, source: string): Verdict {
  const attempt = run(source, challenge.mode);
  if (attempt.error) {
    return { passed: false, reason: `Program ma błąd w linii ${attempt.error.line}: ${attempt.error.message}` };
  }
  if (attempt.segments.length === 0) return { passed: false, reason: 'Program niczego nie narysował.' };
  const target = run(challenge.solution, challenge.mode).segments;
  const missing = uncovered(target, attempt.segments);
  const extra = uncovered(attempt.segments, target);
  if (!missing && !extra) return { passed: true, reason: 'Brawo! Rysunek zgadza się ze wzorem.' };
  if (missing) return { passed: false, reason: 'Brakuje części wzoru.' };
  return { passed: false, reason: 'Narysowano linie, których nie ma we wzorze.' };
}

/** The first sample point of `drawing` farther than TOLERANCE from every segment of `other`. */
function uncovered(drawing: readonly Segment[], other: readonly Segment[]): Vec3 | null {
  for (const s of drawing) {
    for (const p of samples(s)) {
      if (!other.some((o) => distanceToSegment(p, o.from, o.to) <= TOLERANCE)) return p;
    }
  }
  return null;
}

function samples(s: Segment): Vec3[] {
  const length = Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
  const n = Math.max(1, Math.ceil(length / TOLERANCE));
  return Array.from({ length: n + 1 }, (_, i) => {
    const t = i / n;
    return [s.from[0] + (s.to[0] - s.from[0]) * t, s.from[1] + (s.to[1] - s.from[1]) * t, s.from[2] + (s.to[2] - s.from[2]) * t];
  });
}

function distanceToSegment(p: Vec3, a: Vec3, b: Vec3): number {
  const ab = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
  const ap = [p[0] - a[0], p[1] - a[1], p[2] - a[2]];
  const len2 = ab[0] * ab[0] + ab[1] * ab[1] + ab[2] * ab[2];
  const t = len2 === 0 ? 0 : Math.max(0, Math.min(1, (ap[0] * ab[0] + ap[1] * ab[1] + ap[2] * ab[2]) / len2));
  return Math.hypot(ap[0] - ab[0] * t, ap[1] - ab[1] * t, ap[2] - ab[2] * t);
}

export const CHALLENGES: Challenge[] = [];

