import { CHALLENGES, checkSolution, type Challenge } from '../src/app/challenges';

const square: Challenge = {
  id: 'test-square',
  title: 'Kwadrat',
  mode: '2d',
  level: 1,
  brief: 'Narysuj kwadrat o boku 100.',
  hint: '',
  starter: '',
  solution: 'powtorz 4 [np 100 pw 90]',
};

describe('checking a solution', () => {
  test('the same drawing passes whatever the order, direction or splitting of its segments', () => {
    const variants = [
      'powtorz 4 [np 100 pw 90]',
      'np 50 np 50 pw 90 np 100 pw 90 np 100 pw 90 np 100',
      'pw 90 np 100 lw 90 np 100 lw 90 np 100 lw 90 np 100',
      'np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100 np 0 pw 90 np 30',
    ];
    expect(variants.map((v) => checkSolution(square, v).passed)).toEqual([true, true, true, true]);
  });

  test('the shape may be drawn anywhere on the page', () => {
    expect(checkSolution(square, 'pod pw 90 np 37 lw 90 ws 12 opu\npowtorz 4 [np 100 pw 90]').passed).toBe(true);
  });

  test('a wrong size, a missing part or an extra line fails with a reason', () => {
    const verdicts = [
      checkSolution(square, 'powtorz 4 [np 120 pw 90]'),
      checkSolution(square, 'powtorz 3 [np 100 pw 90]'),
      checkSolution(square, 'powtorz 4 [np 100 pw 90]\npw 45 np 141.42'),
    ];
    expect(verdicts.map((v) => [v.passed, v.reason.split(' (')[0]])).toEqual([
      [false, 'Rysunek ma wymiary 120 × 120, a wzór 100 × 100.'],
      [false, 'Brakuje części wzoru'],
      [false, 'Narysowano linie, których nie ma we wzorze'],
    ]);
  });

  test('when colours matter, each line must have the colour of the matching target line', () => {
    const coloured: Challenge = { ...square, checkColors: true, solution: 'kolor "#c1763d" powtorz 4 [np 100 pw 90]' };
    const wrong = checkSolution(coloured, 'powtorz 4 [np 100 pw 90]');
    expect([wrong.passed, wrong.reason.split(' (')[0], checkSolution(coloured, 'kolor "#C1763D" powtorz 4 [np 100 pw 90]').passed]).toEqual([
      false,
      'Kształt się zgadza, ale kolory nie',
      true,
    ]);
  });

  test('a challenge may require a construct, and says which one is missing', () => {
    const withRepeat: Challenge = { ...square, requires: ['repeat'] };
    const withProcedure: Challenge = { ...square, requires: ['procedure'] };
    const longhand = 'np 100 pw 90 np 100 pw 90 np 100 pw 90 np 100';
    const procedure = 'oto bok ma: d\n  np d pw 90\njuż\npowtorz 4 [bok 100]';
    expect([
      checkSolution(withRepeat, longhand).reason,
      checkSolution(withRepeat, 'powtorz 4 [np 100 pw 90]').passed,
      checkSolution(withProcedure, 'powtorz 4 [np 100 pw 90]').reason,
      checkSolution(withProcedure, procedure).passed,
    ]).toEqual([
      'Rysunek się zgadza, ale to wyzwanie trzeba rozwiązać z użyciem „powtórz”.',
      true,
      'Rysunek się zgadza, ale to wyzwanie trzeba rozwiązać z użyciem własnej procedury („oto … już”).',
      true,
    ]);
  });

  test('a program with an error or with no drawing fails and says why', () => {
    const broken = checkSolution(square, 'np 100\npw');
    const empty = checkSolution(square, 'pw 90');
    expect([broken.passed, broken.reason.includes('linii 2'), empty.passed, empty.reason]).toEqual([
      false,
      true,
      false,
      'Program niczego nie narysował.',
    ]);
  });
});

