import { run } from '../../lang';
import { CHALLENGES, type Challenge } from '../challenges';
import { h, icon } from '../dom';
import { ICONS } from '../icons';
import type { ChallengeProgress } from '../store';
import { drawThumbnail } from '../thumbnail';

const LEVELS = { 1: 'Na rozgrzewkę', 2: 'Średnie', 3: 'Dla wytrwałych' } as const;

export interface ChallengesPage {
  element: HTMLElement;
  /** Shows the progress and draws the target pictures. */
  refresh(progress: ChallengeProgress): void;
}

export function createChallengesPage(options: { onSolve(challenge: Challenge): void }): ChallengesPage {
  const summary = h('p', { class: 'progress-summary' });
  const meter = h('div', { class: 'progress-meter', role: 'presentation' }, h('span', { class: 'progress-fill' }));
  const items = CHALLENGES.map((challenge) => {
    const canvas = h('canvas', { class: 'card-thumb', width: '280', height: '180', 'aria-hidden': 'true' });
    const status = h('span', { class: 'badge badge-status' });
    const titleId = `challenge-${challenge.id}`;
    const item = h(
      'li',
      { class: 'card card-challenge', 'aria-labelledby': titleId },
      canvas,
      h(
        'div',
        { class: 'card-body' },
        h(
          'h3',
          { class: 'card-title', id: titleId },
          challenge.title,
          h('span', { class: 'badge' }, challenge.mode.toUpperCase()),
        ),
        h('p', { class: 'card-meta' }, LEVELS[challenge.level], ' · ', status),
        h('p', { class: 'card-text' }, challenge.brief),
        h(
          'button',
          {
            type: 'button',
            class: 'btn btn-small card-action',
            'aria-label': `Rozwiąż wyzwanie ${challenge.title}`,
            onclick: () => options.onSolve(challenge),
          },
          icon(ICONS.target),
          h('span', null, 'Rozwiąż'),
        ),
      ),
    );
    return { challenge, item, canvas, status, titleId };
  });

  const element = h(
    'div',
    { class: 'page-inner' },
    h(
      'header',
      { class: 'page-head' },
      h('h1', { tabindex: '-1' }, 'Wyzwania'),
      h(
        'p',
        { class: 'lead' },
        'Każde wyzwanie pokazuje rysunek do odtworzenia. Napisz program, naciśnij „Sprawdź”, a Logomocja porówna Twój rysunek ze wzorem (z dokładnością do półtora kroku; rysunek może leżeć w innym miejscu kartki).',
      ),
      summary,
      meter,
    ),
    h('ul', { class: 'cards' }, items.map((i) => i.item)),
  );

  return {
    element,
    refresh(progress) {
      let solved = 0;
      for (const { challenge, item, canvas, status, titleId } of items) {
        const done = challenge.id in progress.solved;
        if (done) solved++;
        status.textContent = done ? 'Zaliczone ✓' : 'Do zrobienia';
        status.classList.toggle('is-done', done);
        item.classList.toggle('is-done', done);
        item.setAttribute('aria-label', `${challenge.title} — ${done ? 'zaliczone' : 'do zrobienia'}`);
        item.removeAttribute('aria-labelledby');
        void titleId;
        drawThumbnail(canvas, run(challenge.solution, challenge.mode).segments, challenge.mode);
      }
      summary.textContent = `Zaliczone: ${solved} z ${CHALLENGES.length}.`;
      meter.style.setProperty('--progress', String(solved / CHALLENGES.length));
    },
  };
}

