import { run } from '../lang';
import type { Challenge, Verdict } from './challenges';
import { h, icon } from './dom';
import { ICONS } from './icons';
import { drawThumbnail } from './thumbnail';

export interface ChallengePanel {
  element: HTMLElement;
  show(challenge: Challenge, solved: boolean): void;
  hide(): void;
  setResult(verdict: Verdict): void;
  refreshThumbnail(): void;
}

/** The brief, target picture and check button shown above the editor during a challenge. */
export function createChallengePanel(options: {
  onCheck(): void;
  onExit(): void;
  onGhost(visible: boolean): void;
}): ChallengePanel {
  const title = h('h2', { class: 'challenge-title' });
  const badge = h('span', { class: 'badge badge-status' });
  const brief = h('p', { class: 'challenge-brief' });
  const hint = h('p', { class: 'challenge-hint-text' });
  const canvas = h('canvas', { class: 'challenge-thumb', width: '160', height: '110', role: 'img' });
  const result = h('div', { class: 'challenge-result', role: 'region', 'aria-label': 'Wynik sprawdzenia', 'aria-live': 'polite' });
  const ghost = h('input', { type: 'checkbox', checked: true, onchange: () => options.onGhost(ghost.checked) });
  let current: Challenge | null = null;

  const element = h(
    'div',
    { class: 'challenge-panel', hidden: true },
    h(
      'div',
      { class: 'challenge-head' },
      h('p', { class: 'challenge-kicker' }, icon(ICONS.target), 'Wyzwanie'),
      h(
        'button',
        { type: 'button', class: 'btn btn-small btn-ghost', onclick: () => options.onExit() },
        icon(ICONS.cross),
        h('span', null, 'Zakończ wyzwanie'),
      ),
    ),
    h(
      'div',
      { class: 'challenge-main' },
      canvas,
      h('div', { class: 'challenge-text' }, h('div', { class: 'challenge-title-row' }, title, badge), brief),
    ),
    h('details', { class: 'challenge-hint' }, h('summary', null, icon(ICONS.lightbulb), 'Podpowiedź'), hint),
    h(
      'div',
      { class: 'challenge-actions' },
      h('button', { type: 'button', class: 'btn btn-primary', onclick: () => options.onCheck() }, icon(ICONS.check), h('span', null, 'Sprawdź')),
      h('label', { class: 'check' }, ghost, h('span', null, 'Pokaż wzór na rysunku')),
    ),
    result,
  );

  const markSolved = (solved: boolean) => {
    badge.textContent = solved ? 'Zaliczone ✓' : 'Do zrobienia';
    badge.classList.toggle('is-done', solved);
  };

  return {
    element,
    show(challenge, solved) {
      current = challenge;
      element.hidden = false;
      title.textContent = challenge.title;
      brief.textContent = challenge.brief;
      hint.textContent = challenge.hint;
      canvas.setAttribute('aria-label', `Wzór do narysowania: ${challenge.brief}`);
      result.textContent = '';
      result.dataset.verdict = '';
      ghost.checked = true;
      markSolved(solved);
      drawThumbnail(canvas, run(challenge.solution, challenge.mode).segments, challenge.mode);
    },
    hide() {
      current = null;
      element.hidden = true;
    },
    setResult(verdict) {
      result.textContent = `${verdict.passed ? 'Zaliczone!' : 'Jeszcze nie.'} ${verdict.reason}`;
      result.dataset.verdict = verdict.passed ? 'pass' : 'fail';
      if (verdict.passed) markSolved(true);
    },
    refreshThumbnail() {
      if (current) drawThumbnail(canvas, run(current.solution, current.mode).segments, current.mode);
    },
  };
}

