import type { Mode } from '../lang';

/** One command: its Polish and English spellings, argument, meaning and a runnable example. */
export interface CommandDoc {
  polish: string[];
  english: string[];
  argument: string;
  description: string;
  example: string;
  mode: Mode;
}

export interface ExampleDoc {
  title: string;
  source: string;
  mode: Mode;
}

export interface Section {
  id: string;
  title: string;
  /** Paragraphs; `kod` becomes code and **słowa** are emphasised. */
  intro: string[];
  commands?: CommandDoc[];
  examples?: ExampleDoc[];
  /** Code shown without running it (e.g. a mistake to avoid). */
  snippets?: { caption: string; code: string }[];
  table?: { head: string[]; rows: string[][] };
}

export const REFERENCE: Section[] = [
  {
    id: 'poczatek',
    title: 'Na początek',
    intro: [
      'Program to ciąg poleceń dla żółwia. Żółw stoi na kartce i niesie pióro: kiedy idzie z opuszczonym piórem, zostawia linię. Piszesz program w edytorze, naciskasz **Uruchom** (Ctrl+Enter) i patrzysz, jak rysuje. **Krok** wykonuje jedno polecenie naraz — aktualna linia jest podświetlona.',
      'Układ współrzędnych: oś X biegnie w prawo, oś Y do przodu (na kartce: w górę), a oś Z wychodzi z kartki ku Tobie (w 3D: do góry). Żółw zaczyna w punkcie (0, 0, 0), patrzy wzdłuż osi Y, jego prawa strona wskazuje oś X, a grzbiet — oś Z. Pióro jest opuszczone, kolor to `"#16866a"`, grubość 3.',
      'Wielkość liter nie ma znaczenia: `NP 50` to to samo co `np 50`. Polecenia mają polskie i angielskie nazwy; polskie można pisać z ogonkami albo bez (`powtórz` i `powtorz`). Odstępy i nowe wiersze tylko rozdzielają słowa — nowy wiersz ma znaczenie wyłącznie w definicji procedury.',
      'Średnik zaczyna komentarz, który trwa do końca wiersza: `np 50 ; to jest komentarz`.',
    ],
    examples: [{ title: 'Pierwszy rysunek', mode: '2d', source: '; Domek bez dachu\npowtorz 4 [np 80 pw 90]' }],
  },
  {
    id: 'ruch',
    title: 'Ruch',
    intro: ['Żółw chodzi tylko prosto — przed siebie albo tyłem. Jeśli pióro jest opuszczone, a żółw zmieni miejsce, powstaje odcinek. Krok o długości 0 niczego nie rysuje.'],
    commands: [
      {
        polish: ['np', 'naprzód', 'naprzod'],
        english: ['fd', 'forward'],
        argument: 'liczba — długość kroku',
        description: 'Idzie naprzód o podaną liczbę kroków w kierunku, w którym patrzy żółw.',
        example: 'np 100',
        mode: '2d',
      },
      {
        polish: ['ws', 'wstecz'],
        english: ['bk', 'back'],
        argument: 'liczba — długość kroku',
        description: 'Cofa się o podaną liczbę kroków, nie odwracając się.',
        example: 'np 80\npw 90\nws 40',
        mode: '2d',
      },
      {
        polish: ['dom'],
        english: ['home'],
        argument: 'brak',
        description:
          'Wraca do punktu (0, 0, 0) — z opuszczonym piórem rysuje przy tym odcinek — i ustawia się jak na początku. Pióro, kolor i grubość zostają bez zmian.',
        example: 'pw 45\nnp 100\npw 90\nnp 60\ndom',
        mode: '2d',
      },
    ],
  },
  {
    id: 'obroty',
    title: 'Obroty',
    intro: ['Kąty podaje się w stopniach; mogą być ułamkowe. Ujemny kąt obraca w drugą stronę, więc `pw -90` to to samo co `lw 90`.'],
    commands: [
      {
        polish: ['pw', 'prawo'],
        english: ['rt', 'right'],
        argument: 'liczba — kąt w stopniach',
        description: 'Obraca żółwia w prawo (zgodnie z ruchem wskazówek zegara, patrząc z góry).',
        example: 'powtorz 3 [np 100 pw 120]',
        mode: '2d',
      },
      {
        polish: ['lw', 'lewo'],
        english: ['lt', 'left'],
        argument: 'liczba — kąt w stopniach',
        description: 'Obraca żółwia w lewo.',
        example: 'np 60\nlw 90\nnp 60\nlw 45\nnp 60',
        mode: '2d',
      },
    ],
  },
  {
    id: 'pioro',
    title: 'Pióro',
    intro: ['Ustawienia pióra obowiązują, dopóki ich nie zmienisz.'],
    commands: [
      {
        polish: ['pod', 'podnieś', 'podnies'],
        english: ['pu', 'penup'],
        argument: 'brak',
        description: 'Podnosi pióro: żółw chodzi, ale nie rysuje.',
        example: 'np 30\npod\nnp 20\nopu\nnp 30',
        mode: '2d',
      },
      {
        polish: ['opu', 'opuść', 'opusc'],
        english: ['pd', 'pendown'],
        argument: 'brak',
        description: 'Opuszcza pióro: od teraz żółw znów rysuje.',
        example: 'powtorz 5 [np 15 pod np 10 opu]',
        mode: '2d',
      },
      {
        polish: ['kolor'],
        english: ['color'],
        argument: 'kolor w cudzysłowie: # i sześć cyfr szesnastkowych',
        description: 'Ustawia kolor pióra, np. `kolor "#c1763d"`. Wielkość liter w zapisie koloru nie ma znaczenia.',
        example: 'kolor "#c1763d"\nnp 60\nkolor "#2b6fb3"\npw 90\nnp 60',
        mode: '2d',
      },
      {
        polish: ['grubość', 'grubosc'],
        english: ['width'],
        argument: 'liczba całkowita od 1 do 12',
        description: 'Ustawia grubość linii.',
        example: 'powtorz 6 [grubosc nrpowt * 2 np 50 pw 60]',
        mode: '2d',
      },
    ],
  },
  {
    id: 'powtarzanie',
    title: 'Powtarzanie',
    intro: [
      '`powtórz liczba [ polecenia ]` wykonuje polecenia w nawiasach kwadratowych podaną liczbę razy (liczba całkowita od 0 do 10 000; 0 nie robi nic). W nawiasach może być wszystko: inne powtórzenia, warunki, wywołania procedur.',
      '`nrpowt` to numer bieżącego powtórzenia najbliższego `powtórz`, liczony od 1. „Najbliższe” znaczy: to, w którego nawiasach `nrpowt` jest zapisane — dlatego `nrpowt` poza nawiasami `powtórz` (także w procedurze wywoływanej z wnętrza `powtórz`) jest błędem.',
    ],
    commands: [
      {
        polish: ['powtórz', 'powtorz'],
        english: ['repeat'],
        argument: 'liczba powtórzeń, potem [ polecenia ]',
        description: 'Powtarza polecenia w nawiasach.',
        example: 'powtorz 12 [\n  powtorz 4 [np 60 pw 90]\n  pw 30\n]',
        mode: '2d',
      },
      {
        polish: ['nrpowt'],
        english: ['repcount'],
        argument: '— (to wartość, nie polecenie)',
        description: 'Numer bieżącego powtórzenia: 1, 2, 3…',
        example: 'powtorz 20 [np nrpowt * 8 pw 90]',
        mode: '2d',
      },
    ],
  },
  {
    id: 'wyrazenia',
    title: 'Wyrażenia',
    intro: [
      'Wszędzie, gdzie polecenie potrzebuje liczby, można wpisać wyrażenie: liczbę (`80`, `12.5`, `.5`), nazwę zmiennej lub parametru (także z dwukropkiem: `:bok`), `nrpowt`, wyrażenie w nawiasach okrągłych albo działanie `+`, `-`, `*`, `/`. Zapisy `1e3`, `0x10`, `NaN` czy `Infinity` nie są liczbami.',
      'Mnożenie i dzielenie wykonuje się przed dodawaniem i odejmowaniem; działania tej samej rangi liczy się od lewej: `20 - 5 - 3` to 12, a `2 + 3 * 4` to 14.',
      '**Odstępy wokół działań:** znak działania musi mieć odstęp po obu stronach albo po żadnej. `np 10 - 5` i `np 10-5` idą o 5 kroków, ale `np 10 -5` to `np 10`, po którym stoi osobna wartość `-5` — a to błąd. Ta zasada nie dotyczy porównań.',
      'Znaki `-` i `+` przed wartością można stawiać wszędzie i łączyć: `np -(3 - 5)`, `np - -2`, `np -bok`. Dzielenie przez zero i wynik zbyt duży, by go użyć, to błędy wykonania.',
    ],
    examples: [
      { title: 'Kolejność działań', mode: '2d', source: 'np 2 + 3 * 4\npw 90\nnp (2 + 3) * 4' },
      { title: 'Minus przed wartością', mode: '2d', source: 'niech bok 40\npw 90\nnp -bok\nnp - -bok * 2' },
    ],
    snippets: [
      { caption: 'Tak zadziała: odstępy po obu stronach albo po żadnej.', code: 'np 100 - 20\nnp 100-20' },
      { caption: 'Tak nie: „-20” stoi osobno, bo minus ma odstęp tylko z lewej.', code: 'np 100 -20' },
    ],
  },
  {
    id: 'zmienne',
    title: 'Zmienne',
    intro: [
      '`niech nazwa wyrażenie` zapamiętuje wartość pod nazwą; kolejne `niech` z tą samą nazwą ją zmienia. Nazwa składa się z liter (także polskich), cyfr i podkreślnika, zaczyna się od litery i nie może być nazwą polecenia ani procedury.',
      '`niech` w głównym programie tworzy zmienną globalną. `niech` wewnątrz procedury tworzy zmienną lokalną tego wywołania: od tej chwili do końca wywołania przesłania globalną o tej samej nazwie, a po jego zakończeniu znika. Tak samo można zmienić wartość parametru.',
