import { highlight, run, type Mode } from '../../lang';
import { escapeHtml, h, icon } from '../dom';
import { ICONS } from '../icons';
import { REFERENCE, type CommandDoc, type ExampleDoc, type Section } from '../reference';
import { drawThumbnail } from '../thumbnail';

export interface ReferencePage {
  element: HTMLElement;
  refresh(): void;
  /** Scrolls a section into view by its id. */
  reveal(id: string): void;
}

/** Paragraph markup: `code` and **emphasis**. */
function rich(text: string): HTMLElement {
  const p = h('p');
  p.innerHTML = escapeHtml(text)
    .replace(/`([^`]+)`/g, (_, code) => `<code>${code}</code>`)
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  return p;
}

/** A read-only, syntax-highlighted block of Logo code. */
export function codeBlock(source: string): HTMLElement {
  const code = h('code');
  let html = '';
  let pos = 0;
  for (const span of highlight(source)) {
    html += escapeHtml(source.slice(pos, span.start));
    html += `<span class="tok tok-${span.kind}">${escapeHtml(source.slice(span.start, span.end))}</span>`;
    pos = span.end;
  }
  code.innerHTML = html + escapeHtml(source.slice(pos));
  return h('pre', { class: 'code-block' }, code);
}

export function createReferencePage(options: { onTry(source: string, mode: Mode, title: string): void }): ReferencePage {
  const thumbnails: { canvas: HTMLCanvasElement; source: string; mode: Mode }[] = [];

  const example = (title: string, source: string, mode: Mode, label: string) => {
    const canvas = h('canvas', { class: 'ref-thumb', width: '120', height: '90', 'aria-hidden': 'true' });
    thumbnails.push({ canvas, source, mode });
    return h(
      'figure',
      { class: 'ref-example' },
      h(
        'div',
        { class: 'ref-example-code' },
        codeBlock(source),
        h(
          'div',
          { class: 'ref-example-bar' },
          h('span', { class: 'badge' }, mode.toUpperCase()),
          h(
            'button',
            {
              type: 'button',
              class: 'btn btn-small',
              'aria-label': `Wypróbuj przykład: ${label}`,
              onclick: () => options.onTry(source, mode, title),
            },
            icon(ICONS.play),
            h('span', null, 'Wypróbuj'),
          ),
        ),
      ),
      canvas,
    );
  };

  const command = (doc: CommandDoc) =>
    h(
      'article',
      { class: 'ref-command' },
      h(
        'h3',
        { class: 'ref-names' },
        doc.polish.map((name) => h('code', { class: 'ref-name' }, name)),
        h('span', { class: 'ref-english' }, doc.english.map((name) => h('code', null, name))),
      ),
      h('p', { class: 'ref-argument' }, h('span', { class: 'ref-label' }, 'Argument: '), doc.argument),
      rich(doc.description),
      example(`Polecenie ${doc.polish[0]}`, doc.example, doc.mode, doc.polish[0]),
    );

  const section = (s: Section) =>
    h(
      'section',
      { class: 'ref-section', id: `ref-${s.id}`, 'aria-labelledby': `ref-${s.id}-title` },
      h('h2', { id: `ref-${s.id}-title`, tabindex: '-1' }, s.title),
      s.intro.map(rich),
      s.commands?.map(command),
      s.examples?.map((e: ExampleDoc) => example(e.title, e.source, e.mode, e.title)),
      s.snippets?.map((snippet) => h('figure', { class: 'ref-snippet' }, codeBlock(snippet.code), h('figcaption', null, snippet.caption))),
      s.table &&
        h(
          'table',
          { class: 'ref-table' },
          h('thead', null, h('tr', null, s.table.head.map((cell) => h('th', { scope: 'col' }, cell)))),
          h('tbody', null, s.table.rows.map((row) => h('tr', null, row.map((cell) => h('td', null, cell))))),
        ),
    );

  const toc = h(
    'nav',
    { class: 'ref-toc', 'aria-label': 'Spis treści' },
    h('h2', { class: 'ref-toc-title' }, 'Spis treści'),
    h('ol', null, REFERENCE.map((s) => h('li', null, h('a', { href: `#/polecenia/${s.id}` }, s.title)))),
  );

  const element = h(
    'div',
    { class: 'page-inner page-reference-inner' },
    h(
      'header',
      { class: 'page-head' },
      h('h1', { tabindex: '-1' }, 'Polecenia języka'),
      h('p', { class: 'lead' }, 'Cały język Logomocji na jednej stronie: polecenia z przykładami, wyrażenia, zmienne, warunki, procedury i ograniczenia. Każdy przykład można od razu uruchomić.'),
    ),
    h('div', { class: 'ref-layout' }, toc, h('div', { class: 'ref-content' }, REFERENCE.map(section))),
  );

  return {
    element,
    refresh() {
      for (const t of thumbnails) drawThumbnail(t.canvas, run(t.source, t.mode).segments, t.mode);
    },
    reveal(id) {
      const target = element.querySelector<HTMLElement>(`#ref-${CSS.escape(id)}`);
      if (!target) return;
      target.scrollIntoView?.({ block: 'start' });
      target.querySelector<HTMLElement>('h2')?.focus({ preventScroll: true });
    },
  };
}

