import { afterEach, describe, expect, test } from 'bun:test';
import { screen } from '@testing-library/dom';
import { mountApp, type AppDeps, type MountedApp } from '../src/app/app';
import type { Scheduler } from '../src/app/controller';

/** A frame scheduler the test drives by hand. */
function manualClock() {
  const callbacks = new Map<number, (now: number) => void>();
  let next = 0;
  let now = 0;
  const scheduler: Scheduler = {
    request(callback) {
      callbacks.set(++next, callback);
      return next;
    },
    cancel(handle) {
      callbacks.delete(handle);
    },
  };
  const tick = () => {
    now += 16;
    const due = [...callbacks.values()];
    callbacks.clear();
    for (const callback of due) callback(now);
  };
  return {
    scheduler,
    advance(ms: number) {
      for (let t = 0; t < ms; t += 16) tick();
    },
    tick,
  };
}

let app: MountedApp | null = null;
let clock = manualClock();
const downloads: { name: string; text: string }[] = [];

function mount(hash = '#/', storage: Storage = window.localStorage): MountedApp {
  app?.destroy();
  document.body.innerHTML = '<div id="app"></div>';
  history.replaceState(null, '', hash);
  clock = manualClock();
  const deps: AppDeps = {
    storage,
    scheduler: clock.scheduler,
    download: async (name, blob) => {
      downloads.push({ name, text: await blob.text() });
    },
  };
  app = mountApp(document.getElementById('app')!, deps);
  return app;
}

/** Resolves a promise that waits for animation frames by advancing the manual clock. */
async function settle<T>(promise: Promise<T>): Promise<T> {
  let done = false;
  let value: T;
  promise.then((v) => {
    done = true;
    value = v;
  });
  for (let i = 0; i < 200 && !done; i++) {
    clock.tick();
    await new Promise((resolve) => setTimeout(resolve, 0));
  }
  if (!done) throw new Error('promise did not settle');
  return value!;
}

const editor = () => screen.getByRole('textbox', { name: 'Kod programu' }) as HTMLTextAreaElement;
const modeRadio = (mode: '2D' | '3D') => screen.getByRole('radio', { name: mode }) as HTMLInputElement;

