import { h, icon } from './dom';
import { ICONS } from './icons';
import type { Store, ThemeChoice } from './store';

const NEXT: Record<ThemeChoice, ThemeChoice> = { system: 'light', light: 'dark', dark: 'system' };
const NAMES = { light: 'jasny', dark: 'ciemny' } as const;

export interface ThemeControl {
  button: HTMLButtonElement;
  destroy(): void;
}

/** Light and dark themes: follows the system unless the user picks one; the choice is remembered. */
export function createThemeControl(store: Store, onChange: () => void): ThemeControl {
  const query = typeof matchMedia === 'function' ? matchMedia('(prefers-color-scheme: dark)') : null;
  let choice = store.theme();
  const button = h('button', { type: 'button', class: 'btn btn-icon btn-ghost theme-toggle', onclick: () => cycle() });

  const apply = () => {
    const effective = choice === 'system' ? (query?.matches ? 'dark' : 'light') : choice;
    const root = document.documentElement;
    root.dataset.theme = effective;
    root.dataset.themeChoice = choice;
    root.style.colorScheme = effective;
    document.querySelector('meta[name="theme-color"]')?.setAttribute('content', effective === 'dark' ? '#121a19' : '#f4efe4');
    const label = choice === 'system' ? `systemowy (teraz ${NAMES[effective]})` : NAMES[choice];
    button.setAttribute('aria-label', `Motyw: ${label}`);
    button.title = `Motyw: ${label} — kliknij, aby zmienić`;
    button.replaceChildren(icon(choice === 'system' ? ICONS.system : choice === 'dark' ? ICONS.moon : ICONS.sun));
    onChange();
  };
  const cycle = () => {
    choice = NEXT[choice];
    store.saveTheme(choice);
    apply();
  };
  const onSystemChange = () => {
    if (choice === 'system') apply();
  };
  query?.addEventListener?.('change', onSystemChange);
  apply();

  return {
    button,
    destroy() {
      query?.removeEventListener?.('change', onSystemChange);
    },
  };
}

