// Static file server mounting a directory under a sub-path, with no rewrites (like a plain static host).
const [dir, base, port] = [process.argv[2], process.argv[3], Number(process.argv[4] ?? 4173)];
Bun.serve({
  port,
  async fetch(req) {
    const url = new URL(req.url);
    if (!url.pathname.startsWith(base)) return new Response('Not found', { status: 404 });
    let rel = decodeURIComponent(url.pathname.slice(base.length));
    if (rel === '' || rel.endsWith('/')) rel += 'index.html';
    const file = Bun.file(`${dir}/${rel}`);
    return (await file.exists()) ? new Response(file) : new Response('Not found', { status: 404 });
  },
});
console.log(`serving ${dir} at http://localhost:${port}${base}`);
EOF
