import { render3D, fit3D } from '/work/src/app/view3d';
import type { Palette, Scene } from '/work/src/app/scene';

const light: Palette = { background: '#fbf8f1', grid: '#eee8dc', gridMajor: '#ddd4c1', axis: '#9e937e', axisX: '#c4503d', axisY: '#3b8b4f', axisZ: '#3a6fc4', ink: '#1f2a2a', muted: '#5a6462', ghost: 'rgba(179, 103, 47, 0.38)', turtleOutline: '#1f2a2a' };
const dark: Palette = { background: '#18221f', grid: '#213029', gridMajor: '#2d3f3a', axis: '#6b7f79', axisX: '#e57a68', axisY: '#6fc485', axisZ: '#74a7ee', ink: '#e6eee9', muted: '#a2b1ac', ghost: 'rgba(224, 154, 98, 0.45)', turtleOutline: '#e6eee9' };

export function renderProgram(source: string, mode: Mode, file: string, palette = light, w = 640, h = 420) {
  const started = start(source, mode);
  const ex = started.execution!;
  let o = ex.next();
  while (o.kind === 'op') o = ex.next();
  const scene: Scene = { segments: ex.segments, turtle: ex.turtle, ghost: [], showTurtle: true };
  const canvas = createCanvas(w * 2, h * 2);
  const ctx = canvas.getContext('2d') as unknown as CanvasRenderingContext2D;
  ctx.setTransform(2, 0, 0, 2, 0, 0);
  if (mode === '2d') render2D(ctx, scene, fit2D(scene, w, h), w, h, palette);
  else render3D(ctx, scene, fit3D(scene, w, h), w, h, palette);
  Bun.write(file, canvas.toBuffer('image/png'));
}

if (import.meta.main) {
  const which = process.argv[2];
  for (const e of EXAMPLES.filter((e) => !which || which.split(',').includes(e.id))) {
    renderProgram(e.source, e.mode, `/tmp/render/out/${e.id}.png`, process.argv[3] === 'dark' ? dark : light);
  }
  console.log('done');
}
