python3 - <<'EOF'
p='src/app/view3d.ts'
s=open(p).read()
start=s.index("function drawGround(")
end=s.index("/** Draws segments far to near")
new='''function drawGround(ctx: CanvasRenderingContext2D, p: Projector, cam: Camera3D, scene: Scene, pal: Palette): void {
  const b = boundsOf(scene.segments);
  const step = niceStep(cam.distance / 14);
  const reach = Math.max(
    step * 10,
    b ? Math.max(Math.abs(b.min[0]), Math.abs(b.max[0]), Math.abs(b.min[1]), Math.abs(b.max[1])) + step * 3 : 0,
  );
  const n = Math.min(60, Math.ceil(reach / step));
  const extent = n * step;
  const pieces = 12;
  ctx.lineWidth = 1;
  // Grid lines fade out toward the edge of the ground, in pieces so the fade is smooth.
  for (let i = -n; i <= n; i++) {
    if (i === 0) continue;
    const v = i * step;
    const color = i % 5 === 0 ? pal.gridMajor : pal.grid;
    for (const axis of [0, 1]) {
      for (let k = 0; k < pieces; k++) {
        const t0 = -extent + (2 * extent * k) / pieces;
        const t1 = t0 + (2 * extent) / pieces;
        const mid = (t0 + t1) / 2;
        const fade = 1 - Math.hypot(v, mid) / extent;
        if (fade <= 0) continue;
        const a: Vec3 = axis === 0 ? [v, t0, 0] : [t0, v, 0];
        const c: Vec3 = axis === 0 ? [v, t1, 0] : [t1, v, 0];
        const s = projectSegment(p, a, c);
        if (!s) continue;
        ctx.globalAlpha = Math.min(1, fade * 1.6);
        ctx.strokeStyle = color;
        ctx.beginPath();
        ctx.moveTo(s.a[0], s.a[1]);
        ctx.lineTo(s.b[0], s.b[1]);
        ctx.stroke();
      }
    }
  }
  ctx.globalAlpha = 1;
  // Axes from the origin: X red, Y green, Z blue; light enough not to look like part of a drawing.
  const length = step * 3;
  const axes: [Vec3, string, string][] = [
    [[1, 0, 0], pal.axisX, 'x'],
    [[0, 1, 0], pal.axisY, 'y'],
    [[0, 0, 1], pal.axisZ, 'z'],
  ];
  ctx.font = '600 12px system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (const [dir, color, label] of axes) {
    const far = label === 'z' ? length : extent * 0.85;
    const neg = label === 'z' ? null : projectSegment(p, scale(dir, -far), [0, 0, 0]);
    if (neg) {
      ctx.strokeStyle = mix(color, pal.background, 0.65);
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(neg.a[0], neg.a[1]);
      ctx.lineTo(neg.b[0], neg.b[1]);
      ctx.stroke();
    }
    const pos = projectSegment(p, [0, 0, 0], scale(dir, far));
    if (!pos) continue;
    ctx.strokeStyle = mix(color, pal.background, 0.3);
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(pos.a[0], pos.a[1]);
    ctx.lineTo(pos.b[0], pos.b[1]);
    ctx.stroke();
    const tip = projectSegment(p, [0, 0, 0], scale(dir, label === 'z' ? length * 1.15 : length * 1.2));
    if (tip) {
      ctx.fillStyle = color;
      ctx.fillText(label, tip.b[0] + (label === 'z' ? 10 : 0), tip.b[1] - (label === 'z' ? 0 : 10));
    }
  }
  const o = projectSegment(p, [0, 0, 0], [0, 0, 0]);
  if (o) {
    ctx.fillStyle = pal.background;
    ctx.strokeStyle = pal.axis;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(o.a[0], o.a[1], 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }
}

'''
s=s[:start]+new+s[end:]
open(p,'w').write(s)
EOF
