import { describe, expect, test } from 'bun:test';
import { createController, type Scheduler } from '../src/app/controller';

/** A frame scheduler driven by the test instead of the browser. */
function manualClock() {
  const callbacks = new Map<number, (now: number) => void>();
  let next = 0;
  let now = 0;
  const scheduler: Scheduler = {
    request(callback) {
      callbacks.set(++next, callback);
      return next;
    },
    cancel(handle) {
      callbacks.delete(handle);
    },
  };
  return {
    scheduler,
    /** Moves time forward by `ms`, one 16 ms frame at a time. */
    advance(ms: number) {
      for (let t = 0; t < ms; t += 16) {
        now += 16;
        const due = [...callbacks.values()];
        callbacks.clear();
        for (const callback of due) callback(now);
      }
    },
  };
}

const SQUARE = 'np 10\npw 90\nnp 20';

describe('running', () => {
  test('run animates the program over time at the chosen speed', () => {
    const clock = manualClock();
    const controller = createController({ scheduler: clock.scheduler });
    controller.setSpeed(1); // one command per second
    controller.run(SQUARE, '2d');
    const progress: string[] = [controller.snapshot().state];
    clock.advance(1100);
    progress.push(`${controller.snapshot().segments.length} after 1.1 s`);
    clock.advance(2000);
    progress.push(controller.snapshot().state, `${controller.snapshot().segments.length} at the end`);
    expect(progress).toEqual(['running', '1 after 1.1 s', 'finished', '2 at the end']);
  });

  test('at the highest speed the program runs to the end at once', () => {
    const controller = createController({ scheduler: manualClock().scheduler });
    controller.setSpeed(10);
    controller.run(SQUARE, '2d');
    expect([controller.snapshot().state, controller.snapshot().segments.length]).toEqual(['finished', 2]);
  });
});

describe('finishing', () => {
  test('finish runs the rest of the program at once whatever the speed, from scratch or from a pause', () => {
    const controller = createController({ scheduler: manualClock().scheduler });
    controller.setSpeed(1);
    controller.finish(SQUARE, '2d');
    const fromScratch = controller.snapshot();
    controller.step('np 1\nnp 2\nnp 3', '2d');
    controller.finish('np 1\nnp 2\nnp 3', '2d');
    const fromPause = controller.snapshot();
    expect([fromScratch.state, fromScratch.segments.length, fromPause.state, fromPause.segments.length]).toEqual([
      'finished',
      2,
      'finished',
      3,
    ]);
  });
});

describe('pausing', () => {
  test('pause freezes the animation where it is and resume continues from there', () => {
    const clock = manualClock();
    const controller = createController({ scheduler: clock.scheduler });
    controller.setSpeed(1);
    controller.run(SQUARE, '2d');
    clock.advance(1100);
    controller.pause();
    clock.advance(5000);
    const paused = controller.snapshot();
    controller.resume();
    const resumed = controller.snapshot().state;
    clock.advance(3000);
    expect([paused.state, paused.segments.length, paused.line, resumed, controller.snapshot().state]).toEqual([
      'paused',
      1,
      2,
      'running',
      'finished',
    ]);
    expect(controller.snapshot().segments.length).toBe(2);
  });

  test('step while running pauses and executes exactly one more command', () => {
    const clock = manualClock();
    const controller = createController({ scheduler: clock.scheduler });
    controller.setSpeed(1);
    controller.run(SQUARE, '2d');
    clock.advance(20); // the first command runs on the first frame
    controller.step(SQUARE, '2d');
    clock.advance(5000);
    const s = controller.snapshot();
    expect([s.state, s.line, s.segments.length]).toEqual(['paused', 2, 1]);
  });
});

describe('reset and errors', () => {
  test('reset stops the program and clears the drawing, putting the turtle home', () => {
    const clock = manualClock();
    const controller = createController({ scheduler: clock.scheduler });
    controller.setSpeed(1);
    controller.run(SQUARE, '2d');
    clock.advance(2100);
    controller.reset();
    clock.advance(5000);
    const s = controller.snapshot();
    expect([s.state, s.segments.length, s.line, s.turtle.position, s.turtle.heading]).toEqual([
      'idle',
      0,
      null,
      [0, 0, 0],
      [0, 1, 0],
    ]);
  });

  test('a parse-time error draws nothing; a run-time error keeps the drawing and reports its line', () => {
    const controller = createController({ scheduler: manualClock().scheduler });
    controller.setSpeed(10);
    controller.run('np 10\nnp 1 +', '2d');
    const parse = controller.snapshot();
    controller.run('np 10\nnp 1 / 0\nnp 5', '2d');
    const runtime = controller.snapshot();
    expect([parse.state, parse.segments.length, parse.error?.line, parse.error?.column]).toEqual(['error', 0, 2, 6]);
    expect([runtime.state, runtime.segments.length, runtime.error?.line, runtime.line]).toEqual(['error', 1, 2, 2]);
  });

  test('stop keeps the drawing but ends the program, so the next step starts over', () => {
    const controller = createController({ scheduler: manualClock().scheduler });
    controller.step(SQUARE, '2d');
    controller.step(SQUARE, '2d');
    controller.stop();
    const stopped = controller.snapshot();
    controller.step('np 99', '2d');
    expect([stopped.state, stopped.segments.length, stopped.line, controller.snapshot().segments[0].to]).toEqual([
      'stopped',
      1,
      null,
      [0, 99, 0],
    ]);
  });
});

describe('stepping', () => {
  test('step executes one command at a time and reports the line being executed', () => {
    const controller = createController({ scheduler: manualClock().scheduler });
    const seen: [string, number, number | null][] = [];
    for (let i = 0; i < 4; i++) {
      controller.step(SQUARE, '2d');
      const s = controller.snapshot();
      seen.push([s.state, s.segments.length, s.line]);
    }
    expect(seen).toEqual([
      ['paused', 1, 1],
      ['paused', 1, 2],
      ['paused', 2, 3],
      ['finished', 2, null],
    ]);
  });
});

