    button('Zapisz obraz PNG').click();
    for (let i = 0; i < 3; i++) await pause();
    // happy-dom has no canvas pixels, so no file can be made here.
    expect([downloads.length, document.querySelector('.toasts')?.textContent?.includes('PNG')]).toEqual([0, true]);
  });

  async function chooseFile(file: File) {
