function finite(value: number): number {
  if (!Number.isFinite(value)) throw new EvalProblem('Wynik obliczenia jest za duży, by go użyć.');
  return value;
}

function evaluate(m: Machine, f: Frame, expr: Expr): number {
  switch (expr.kind) {
    case 'num':
      return expr.value;
    case 'var': {
      const value = f.locals?.get(expr.name) ?? m.globals.get(expr.name);
      if (value === undefined) throw new EvalProblem(`Zmienna „${expr.token.text}” nie ma jeszcze wartości — najpierw nadaj ją przez „niech”.`);
      return value;
    }
    case 'repcount':
      return f.iterations[f.iterations.length - 1];
    case 'negate':
      return -evaluate(m, f, expr.operand);
    case 'binary': {
      const a = evaluate(m, f, expr.left);
      const b = evaluate(m, f, expr.right);
      if (expr.op === '/' && b === 0) throw new EvalProblem('Nie można dzielić przez zero.');
      return finite(applyOp(expr.op, a, b));
    }
  }
}

function evaluateArg(m: Machine, f: Frame, arg: Arg): number {
  try {
    return evaluate(m, f, arg.expr);
  } catch (e) {
    if (e instanceof EvalProblem) throw LogoFailure.at(arg.first, e.message);
    throw e;
  }
}

function holds(m: Machine, f: Frame, cond: Condition): boolean {
  try {
    const a = evaluate(m, f, cond.left);
    const b = evaluate(m, f, cond.right);
    switch (cond.op) {
      case '<':
        return a < b;
      case '>':
        return a > b;
      case '=':
        return a === b;
      case '<=':
        return a <= b;
      case '>=':
        return a >= b;
      case '<>':
        return a !== b;
    }
  } catch (e) {
    if (e instanceof EvalProblem) throw LogoFailure.at(cond.first, e.message);
    throw e;
  }
}

/** Moves the turtle to `to`, drawing a segment when the pen is down and the position changes. */
function moveTo(m: Machine, to: Vec3, token: Token): void {
  if (to.some((v) => Math.abs(v) > LIMITS.coordinate)) {
    throw LogoFailure.at(token, 'Żółw wyszedłby poza obszar rysowania: każda współrzędna musi mieścić się w zakresie ±100 000.');
  }
  const t = m.turtle;
  const from = t.position;
  const moved = from[0] !== to[0] || from[1] !== to[1] || from[2] !== to[2];
  if (t.penDown && moved) {
    // Every segment costs an operation, so the operation limit is normally reached first.
    if (m.segments.length >= LIMITS.segments) {
      throw LogoFailure.at(token, 'Rysunek ma już 10 000 odcinków — to limit. Użyj „czyść”, by zacząć od nowa.');
    }
    m.segments.push({ from, to, color: t.color, width: t.width });
  }
  t.position = to;
}

function move(m: Machine, distance: number, token: Token): void {
  const h = m.turtle.orientation.heading();
  const from = m.turtle.position;
  moveTo(m, [from[0] + h[0] * distance, from[1] + h[1] * distance, from[2] + h[2] * distance], token);
}

/** Returned by a statement or list when `stop` ended the current call (or the program). */
const STOP = 'stop';
type Signal = typeof STOP | undefined;
type Run = Generator<Step, Signal>;

function count(m: Machine, token: Token): void {
  if (++m.operations > LIMITS.operations) {
    throw LogoFailure.at(token, 'Program wykonał już 10 000 operacji — to limit. Może któraś pętla albo rekurencja nie ma końca?');
  }
}

function enterFrame(m: Machine, token: Token): void {
  if (++m.frames > LIMITS.frames) {
    throw LogoFailure.at(token, 'Za głęboko: naraz może działać najwyżej 32 wywołań procedur i powtórzeń. Czy rekurencja ma warunek zakończenia?');
  }
}

/** Counts and reports finishing a body at its closing token. */
function* finish(m: Machine, token: Token): Generator<Step, void> {
  count(m, token);
  yield { token, finish: true };
}

function* execStmt(m: Machine, f: Frame, stmt: Stmt): Run {
  count(m, stmt.token);
  const step: Step = { token: stmt.token, finish: false };
  switch (stmt.kind) {
    case 'move':
      move(m, evaluateArg(m, f, stmt.arg) * stmt.sign, stmt.token);
      break;
    case 'turn': {
      const deg = evaluateArg(m, f, stmt.arg) * stmt.sign;
      const o = m.turtle.orientation;
      if (stmt.axis === 'yaw') o.turn(deg);
      else if (stmt.axis === 'pitch') o.pitch(deg);
      else o.roll(deg);
      break;
    }
    case 'pen':
      m.turtle.penDown = stmt.down;
      break;
    case 'home':
      moveTo(m, [0, 0, 0], stmt.token);
      m.turtle.orientation.reset();
      break;
    case 'clear':
      m.segments = [];
      break;
    case 'color':
      m.turtle.color = stmt.color;
      break;
    case 'width': {
      const width = evaluateArg(m, f, stmt.arg);
      checkWidth(width, stmt.arg.first);
      m.turtle.width = width;
      break;
    }
    case 'let':
      (f.locals ?? m.globals).set(stmt.name, evaluateArg(m, f, stmt.arg));
      break;
    case 'if': {
      const branch = holds(m, f, stmt.cond) ? stmt.then : stmt.otherwise;
      yield step;
      if (!branch) return undefined;
      if ((yield* execList(m, f, branch.body)) === STOP) return STOP;
      yield* finish(m, branch.close);
      return undefined;
    }
    case 'call': {
      const locals = new Map<string, number>();
      stmt.args.forEach((arg, i) => locals.set(stmt.proc.params[i], evaluateArg(m, f, arg)));
      enterFrame(m, stmt.token);
      yield step;
      const signal = yield* execList(m, { locals, iterations: [] }, stmt.proc.body);
      if (signal !== STOP) yield* finish(m, stmt.proc.end);
      m.frames--;
      return undefined;
    }
    case 'stop':
      yield step;
      return STOP;
    case 'repeat': {
      const n = evaluateArg(m, f, stmt.count);
      checkRepeatCount(n, stmt.count.first);
      enterFrame(m, stmt.token);
      yield step;
      f.iterations.push(0);
      let signal: Signal;
      for (let i = 1; i <= n && !signal; i++) {
        f.iterations[f.iterations.length - 1] = i;
        signal = yield* execList(m, f, stmt.body);
        if (!signal) yield* finish(m, stmt.close);
      }
      f.iterations.pop();
      m.frames--;
      return signal;
    }
  }
  yield step;
  return undefined;
}

function* execList(m: Machine, f: Frame, list: Stmt[]): Run {
  for (const stmt of list) {
    if ((yield* execStmt(m, f, stmt)) === STOP) return STOP;
  }
  return undefined;
}

export function* execute(m: Machine, program: Program): Generator<Step, void> {
  yield* execList(m, { locals: null, iterations: [] }, program.body);
}

