const DIGIT = /[0-9]/;
// Phone keyboards often turn " into typographic quotes, so those are accepted too.
const QUOTE = /["„“”]/;
const WORD_CHAR = /[\p{L}\p{M}\p{N}_]/u;
const WORD_START = /[\p{L}_]/u;

export const SOURCE_LIMITS = { characters: 50_000, tokens: 10_000 } as const;

/** Reports the first character past the limit, counting characters as code points. */
function checkLength(source: string): void {
  if (source.length <= SOURCE_LIMITS.characters) return;
  let count = 0;
  let line = 1;
  let column = 1;
  for (const ch of source) {
    if (++count > SOURCE_LIMITS.characters) {
      throw new LogoFailure('Program jest za długi: może mieć najwyżej 50 000 znaków.', line, column);
    }
    if (ch === '\n') {
      line++;
      column = 1;
    } else {
      column++;
    }
  }
}

export function tokenize(source: string): Token[] {
  checkLength(source);
  const tokens: Token[] = [];
  let i = 0;
  let line = 1;
  let column = 1;
  let spaceBefore = true;
  const push = (type: TokenType, start: number, value = NaN) => {
    if (tokens.length >= SOURCE_LIMITS.tokens) {
      throw new LogoFailure('Program jest za długi: może mieć najwyżej 10 000 elementów (słów, liczb, znaków i nawiasów).', line, column);
    }
    const text = source.slice(start, i);
    const bare = type === 'name' ? text.slice(1) : type === 'label' ? text.slice(0, -1) : text;
    const norm = bare.normalize('NFC').toLowerCase();
    const lineStart = tokens.length === 0 || tokens[tokens.length - 1].line !== line;
    if (lineStart && tokens.length > 0) tokens[tokens.length - 1].lineEnd = true;
    tokens.push({
      type, text, norm, value, line, column, start, end: i,
      spaceBefore, spaceAfter: false, lineStart, lineEnd: false,
    });
    column += i - start;
    spaceBefore = false;
  };
  const space = () => {
    if (tokens.length > 0) tokens[tokens.length - 1].spaceAfter = true;
    spaceBefore = true;
  };
  while (i < source.length) {
    const ch = source[i];
    const start = i;
    if (ch === '\n') {
      i++;
      line++;
      column = 1;
      space();
    } else if (/\s/.test(ch)) {
      i++;
      column++;
      space();
    } else if (ch === ';') {
      while (i < source.length && source[i] !== '\n') i++;
      column += i - start;
      space();
    } else if (ch === '[' || ch === ']' || ch === '(' || ch === ')') {
      i++;
      push(ch, start);
    } else if (ch === '+' || ch === '-' || ch === '*' || ch === '/') {
      i++;
      push('op', start);
    } else if (ch === ',') {
      i++;
      push(',', start);
    } else if (ch === '<' || ch === '>' || ch === '=') {
      i++;
      if ((ch === '<' && (source[i] === '=' || source[i] === '>')) || (ch === '>' && source[i] === '=')) i++;
      push('cmp', start);
    } else if (QUOTE.test(ch)) {
      i++;
      while (i < source.length && !QUOTE.test(source[i]) && source[i] !== '\n') i++;
      if (i >= source.length || source[i] === '\n') {
        throw new LogoFailure('Brakuje cudzysłowu zamykającego napis, np. "#16866a".', line, column);
      }
      i++;
      push('str', start);
    } else if (DIGIT.test(ch) || (ch === '.' && DIGIT.test(source[i + 1] ?? ''))) {
      while (DIGIT.test(source[i] ?? '')) i++;
      if (source[i] === '.' && DIGIT.test(source[i + 1] ?? '')) {
        i++;
        while (DIGIT.test(source[i] ?? '')) i++;
      }
      if (WORD_CHAR.test(source[i] ?? '') || source[i] === '.') {
        while (WORD_CHAR.test(source[i] ?? '') || source[i] === '.') i++;
        const text = source.slice(start, i);
        throw new LogoFailure(
          `„${text}” nie jest poprawną liczbą. Liczby zapisuje się cyframi, np. 80, 12.5 albo .5.`,
          line,
          column,
        );
      }
      const value = Number(source.slice(start, i));
      if (!Number.isFinite(value)) throw new LogoFailure('Ta liczba jest za duża.', line, column);
      push('num', start, value);
    } else if (ch === ':' && WORD_START.test(source[i + 1] ?? '')) {
      i++;
      while (i < source.length && WORD_CHAR.test(source[i])) i++;
      push('name', start);
    } else {
      while (i < source.length && WORD_CHAR.test(source[i])) i++;
      if (i === start) {
        const char = String.fromCodePoint(source.codePointAt(i)!);
        const message =
          char === ':'
            ? 'Po dwukropku powinna być nazwa bez odstępu, np. „:bok”.'
            : `Znak „${char}” nie należy do języka Logo.`;
        throw new LogoFailure(message, line, column);
      }
      if (source[i] === ':') {
        i++;
        push('label', start);
      } else {
        push('word', start);
      }
    }
  }
  space();
  if (tokens.length > 0) tokens[tokens.length - 1].lineEnd = true;
  return tokens;
}

