const draftOf = (m: Mode) => store.draft(m) ?? WELCOME[m];
/** Programs the app itself wrote: replacing them never loses the user's work. */
const builtIn = new Set<string>([
  ...Object.values(WELCOME),
  ...EXAMPLES.map((e) => e.source),
  ...REFERENCE.flatMap((s) => [...(s.commands ?? []).map((c) => c.example), ...(s.examples ?? []).map((e) => e.source)]),
  ...CHALLENGES.map((c) => c.starter),
]);

/** The challenge being solved; its program is kept apart from the free-play drafts. */
let active: Challenge | null = null;
let modeBeforeChallenge: Mode | null = null;

const workspace = createWorkspace({
  store,
  scheduler: deps.scheduler,
  initialMode: store.mode() ?? '2d',
  initialSource: draftOf,
  persistDraft: (m, text) => {
    if (!active) return store.saveDraft(m, text);
    const progress = store.progress();
    progress.drafts[active.id] = text;
    store.saveProgress(progress);
  },
  persistMode: (m) => {
    if (!active) store.saveMode(m);
  },
});

const examplesPage = createExamplesPage({ onOpen: (example) => void openExample(example) });
const referencePage = createReferencePage({
  onTry: (source, mode, title) => void tryExample(source, mode, title),
});
const challengesPage = createChallengesPage({ onSolve: (challenge) => navigate(`#/wyzwanie/${challenge.id}`) });
const challengePanel = createChallengePanel({
  onCheck: () => checkActive(),
  onExit: () => navigate('#/'),
  onGhost: (visible) => workspace.setGhost(visible && active ? run(active.solution, active.mode).segments : []),
});
workspace.aside.append(challengePanel.element);

function enterChallenge(challenge: Challenge) {
  if (active?.id === challenge.id) return;
  if (!active) modeBeforeChallenge = workspace.mode;
  active = challenge;
  const progress = store.progress();
  workspace.show(progress.drafts[challenge.id] ?? challenge.starter, challenge.mode);
  workspace.lockMode(true);
  workspace.setGhost(run(challenge.solution, challenge.mode).segments);
  challengePanel.show(challenge, challenge.id in progress.solved);
}

function exitChallenge() {
  if (!active) return;
  active = null;
  workspace.lockMode(false);
  workspace.setGhost([]);
  challengePanel.hide();
  const mode = modeBeforeChallenge ?? workspace.mode;
  workspace.show(draftOf(mode), mode);
}

function checkActive() {
  if (!active) return;
  const verdict = checkSolution(active, workspace.source);
  workspace.run();
  challengePanel.setResult(verdict);
  if (verdict.passed) {
    const progress = store.progress();
    progress.solved[active.id] ??= Date.now();
    store.saveProgress(progress);
  }
}

// Sharing.
const shareDialog = createDialog('Udostępnij program');
const shareField = h('input', { type: 'text', readonly: true, class: 'share-field', id: 'share-link', 'aria-label': 'Link do programu' });
const shareNote = h('p', { class: 'muted', 'aria-live': 'polite' });
shareDialog.body.append(
  h('p', null, 'Ten link zawiera cały program i tryb. Kto go otworzy, zobaczy Twój kod i od razu go uruchomi.'),
  h(
    'div',
    { class: 'share-row' },
    shareField,
    h('button', { type: 'button', class: 'btn btn-primary', onclick: () => void copyLink() }, 'Kopiuj'),
  ),
  shareNote,
);
async function copyLink() {
  shareField.select();
  try {
    await navigator.clipboard.writeText(shareField.value);
    shareNote.textContent = 'Skopiowano link do schowka.';
  } catch {
    shareNote.textContent = 'Nie udało się skopiować automatycznie — zaznaczyłem link, skopiuj go (Ctrl+C).';
  }
}
function share() {
  shareField.value = permalink(workspace.source, workspace.mode);
  shareNote.textContent = shareField.value.length > 8000 ? 'Uwaga: to bardzo długi link — niektóre komunikatory mogą go przyciąć.' : '';
  shareDialog.open();
  shareField.select();
}
// Files.
const fileInput = h('input', {
  type: 'file',
  accept: '.logo,.txt,text/plain',
  class: 'sr-only',
  tabindex: '-1',
  'aria-label': 'Otwórz plik .logo',
  onchange: () => {
    const file = fileInput.files?.[0];
    fileInput.value = '';
    if (file) void openFile(file);
