const theme = createThemeControl(store, () => {
  workspace.refreshPalette();
  if (current === 'examples') examplesPage.refresh();
  if (current === 'challenges') challengesPage.refresh(store.progress());
  if (current === 'reference') referencePage.refresh();
  challengePanel.refreshThumbnail();
});

// Header and pages.
const navLinks = PAGES.map(({ page, href, label }) => h('a', { href, class: 'nav-link', 'data-page': page }, label));
const shortcutsDialog = createDialog('Skróty klawiszowe');
shortcutsDialog.body.append(
  h(
    'table',
    { class: 'shortcuts' },
    h('thead', null, h('tr', null, h('th', { scope: 'col' }, 'Działanie'), h('th', { scope: 'col' }, 'Klawisze'))),
    h('tbody', null, SHORTCUTS.map((s) => h('tr', null, h('td', null, s.label), h('td', null, h('kbd', null, s.keys))))),
  ),
  h(
    'p',
    { class: 'muted' },
    'Na Macu zamiast Ctrl można użyć ⌘. W edytorze Tab wstawia wcięcie; Esc, a potem Tab, przenosi do kolejnego elementu. Na rysunku: strzałki przesuwają (w 3D obracają), + i − przybliżają, F dopasowuje widok.',
  ),
);
const header = h(
  'header',
  { class: 'topbar' },
  h('a', { class: 'brand', href: '#/' }, logo(), h('span', { class: 'brand-name' }, 'Logomocja')),
  h('nav', { class: 'nav', 'aria-label': 'Główna' }, navLinks),
  h(
    'div',
    { class: 'topbar-actions' },
    h(
      'button',
      { type: 'button', class: 'btn btn-icon btn-ghost', 'aria-label': 'Skróty klawiszowe', title: 'Skróty klawiszowe', onclick: () => shortcutsDialog.open() },
      icon(ICONS.keyboard),
    ),
    theme.button,
  ),
);
const pages: Record<Page, HTMLElement> = {
  workspace: h('section', { class: 'page page-workspace', 'aria-label': 'Pracownia' }, workspace.element),
  examples: h('section', { class: 'page page-examples' }, examplesPage.element),
  challenges: h('section', { class: 'page page-challenges' }, challengesPage.element),
  reference: h('section', { class: 'page page-reference' }, referencePage.element),
};
const main = h('main', { id: 'main', class: 'main' }, Object.values(pages));
const skip = h(
  'a',
  { class: 'skip-link', href: '#editor', onclick: (e: Event) => (e.preventDefault(), showPage('workspace'), workspace.focusEditor()) },
  'Przejdź do edytora',
);
root.append(h('div', { class: 'app' }, skip, header, main, toaster.element));

let current: Page | null = null;
function showPage(page: Page, focus = false) {
  if (page === current) return;
  current = page;
  for (const [name, el] of Object.entries(pages)) el.hidden = name !== page;
  for (const a of navLinks) {
    if (a.dataset.page === page) a.setAttribute('aria-current', 'page');
    else a.removeAttribute('aria-current');
  }
  const meta = PAGES.find((p) => p.page === page)!;
  document.title = page === 'workspace' ? 'Logomocja — pracownia żółwia' : `${meta.title} — Logomocja`;
  if (page === 'examples') examplesPage.refresh();
  if (page === 'challenges') challengesPage.refresh(store.progress());
  if (page === 'reference') referencePage.refresh();
  if (focus) pages[page].querySelector<HTMLElement>('h1')?.focus();
}

/**
 * Replaces a mode's draft with another program. When the draft holds the user's own work,
 * asks first and keeps it as a backup that a toast offers to restore.
 */
async function replaceDraft(mode: Mode, source: string, what: string, confirmLabel: string): Promise<boolean> {
  // During a challenge the program being replaced is the challenge's own.
  const draft = active ? workspace.source : draftOf(mode);
  if (draft.trim() !== '' && draft !== source && !builtIn.has(draft)) {
    const ok = await confirmDialog({
      title: 'Zastąpić szkic?',
      message: `W trybie ${MODE_NAME[mode]} masz własny program. ${what} zajmie jego miejsce, a Twój szkic zachowam jako kopię, którą możesz przywrócić.`,
      confirm: confirmLabel,
    });
    if (!ok) return false;
    if (!active) store.saveBackup(mode, draft);
    if (!active) {
      toaster.show(`${what}: wczytano. Twój poprzedni szkic jest bezpieczny.`, {
        label: 'Przywróć szkic',
        run: () => restoreBackup(mode),
      });
    }
  }
  workspace.show(source, mode);
  return true;
}

/** Examples, reference programs and links open outside any challenge. */
function leaveChallenge() {
  if (active) navigate('#/');
}

function restoreBackup(mode: Mode) {
  const backup = store.backup(mode);
  if (backup === null) return;
  leaveChallenge();
  store.saveBackup(mode, draftOf(mode));
  workspace.show(backup, mode);
