new='''/** Frames the drawing from the current direction (or the default one), filling the view. */
export function fit3D(scene: Scene, w: number, h: number, from: Camera3D = DEFAULT_CAMERA_3D): Camera3D {
  const b = boundsOf([...scene.segments, ...scene.ghost], scene.showTurtle ? [scene.turtle.position] : []);
  if (!b || (scene.segments.length === 0 && scene.ghost.length === 0)) {
    return { ...from, target: [0, 0, 0], distance: DEFAULT_CAMERA_3D.distance };
  }
  const target: Vec3 = [(b.min[0] + b.max[0]) / 2, (b.min[1] + b.max[1]) / 2, (b.min[2] + b.max[2]) / 2];
  const corners: Vec3[] = [];
  for (const x of [b.min[0], b.max[0]]) for (const y of [b.min[1], b.max[1]]) for (const z of [b.min[2], b.max[2]]) corners.push([x, y, z]);
  const width = w > 0 ? w : 600;
  const height = h > 0 ? h : 400;
  const margin = Math.min(56, Math.min(width, height) * 0.12);
  // The largest share of the half-view that a corner takes; at most 1 means everything is visible.
  const spread = (distance: number) => {
    const p = projector({ ...from, target, distance }, width, height);
    let worst = 0;
    for (const c of corners) {
      const v = toView(p, c);
      if (v[2] <= p.near) return Infinity;
      const [sx, sy] = toScreen(p, v);
      worst = Math.max(worst, Math.abs(sx - width / 2) / (width / 2 - margin), Math.abs(sy - height / 2) / (height / 2 - margin));
    }
    return worst;
  };
  const radius = Math.max(Math.hypot(b.max[0] - b.min[0], b.max[1] - b.min[1], b.max[2] - b.min[2]) / 2, 10);
  let lo = radius * 0.2;
  let hi = radius * 20;
  for (let i = 0; i < 40; i++) {
    const mid = (lo + hi) / 2;
    if (spread(mid) > 1) lo = mid;
    else hi = mid;
  }
  return { ...from, target, distance: clampDistance(Math.max(hi, radius * 0.6)) };
}

'''
